window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["JOB"]={"book":"JOB","editions":{"fin-biblia1776":[[1,1,"Yksi mies oli Utsin maalla nimeltä Job; ja se mies oli vakaa ja hurskas, ja Jumalaa pelkääväinen, ja vältti pahaa.","Yksi mies oli Utsin maalla nimeltä Job; ja se mies oli vakaa ja hurskas, ja Jumalaa pelkääväinen, ja vältti pahaa."],[1,2,"Ja hänelle oli syntynyt seitsemän poikaa ja kolme tytärtä.","Ja hänelle oli syntynyt seitsemän poikaa ja kolme tytärtä."],[1,3,"Ja hänen karjansa oli seitsemäntuhatta lammasta, kolmetuhatta kamelia, viisisataa paria härkiä ja viisisataa aasia, ja myös sangen paljo perhettä. Ja se mies oli voimallisempi kuin kaikki, jotka itäisellä maalla asuivat.","Ja hänen karjansa oli seitsemäntuhatta lammasta, kolmetuhatta kamelia, viisisataa paria härkiä ja viisisataa aasia, ja myös sangen paljo perhettä. Ja se mies oli voimallisempi kuin kaikki, jotka itäisellä maalla asuivat."],[1,4,"Ja hänen poikansa menivät ja tekivät pidon huoneessansa itsekukin päivänänsä, ja lähettivät ja antoivat kutsua kolme sisartansa syömään ja juomaan kanssansa.","Ja hänen poikansa menivät ja tekivät pidon huoneessansa itsekukin päivänänsä, ja lähettivät ja antoivat kutsua kolme sisartansa syömään ja juomaan kanssansa."],[1,5,"Ja kuin pitopäivät olivat kuluneet, lähetti Job ja pyhitti heitä, ja nousi aamulla varhain ja uhrasi polttouhria kaikkein heidän lukunsa jälkeen. Sillä Job ajatteli: minun poikani ovat taitaneet syntiä tehdä ja unohtaneet Jumalan sydämessänsä. Näin teki Job joka päivä.","Ja kuin pitopäivät olivat kuluneet, lähetti Job ja pyhitti heitä, ja nousi aamulla varhain ja uhrasi polttouhria kaikkein heidän lukunsa jälkeen. Sillä Job ajatteli: minun poikani ovat taitaneet syntiä tehdä ja unohtaneet Jumalan sydämessänsä. Näin teki Job joka päivä."],[1,6,"Mutta tapahtui yhtenä päivänä, että Jumalan lapset tulivat ja astuivat Herran eteen, ja tuli myös saatana heidän kanssansa.","Mutta tapahtui yhtenä päivänä, että Jumalan lapset tulivat ja astuivat Herran eteen, ja tuli myös saatana heidän kanssansa."],[1,7,"Mutta Herra sanoi saatanalle: kusta sinä tulet? Saatana vastasi Herraa ja sanoi: minä olen käynyt ja vaeltanut ympäri maan.","Mutta Herra sanoi saatanalle: kusta sinä tulet? Saatana vastasi Herraa ja sanoi: minä olen käynyt ja vaeltanut ympäri maan."],[1,8,"Niin sanoi Herra saatanalle: etkö ole ottanut vaaria palveliastani Jobista? sillä ei hänen vertaistansa ole maalla: hän on vakaa ja hurskas, Jumalaa pelkääväinen mies, ja välttää pahaa.","Niin sanoi Herra saatanalle: etkö ole ottanut vaaria palveliastani Jobista? sillä ei hänen vertaistansa ole maalla: hän on vakaa ja hurskas, Jumalaa pelkääväinen mies, ja välttää pahaa."],[1,9,"Saatana vastasi Herraa ja sanoi: turhaanko Job pelkää Jumalaa?","Saatana vastasi Herraa ja sanoi: turhaanko Job pelkää Jumalaa?"],[1,10,"Etkös ole piirittänyt häntä, hänen huonettansa ja kaikkia mitä hänellä on ympäri? sinä olet siunannut hänen käsialansa, ja hänen tavaransa on levitetty maassa.","Etkös ole piirittänyt häntä, hänen huonettansa ja kaikkia mitä hänellä on ympäri? sinä olet siunannut hänen käsialansa, ja hänen tavaransa on levitetty maassa."],[1,11,"Mutta ojenna kätes ja tartu kaikkeen hänen saatuunsa, mitämaks hän luopuu sinusta kasvois edessä.","Mutta ojenna kätes ja tartu kaikkeen hänen saatuunsa, mitämaks hän luopuu sinusta kasvois edessä."],[1,12,"Herra sanoi saatanalle: katso, kaikki hänen tavaransa olkoon sinun kädessäs, ainoastaan älä häneen kättäs satuta. Silloin läksi saatana Herran tyköä.","Herra sanoi saatanalle: katso, kaikki hänen tavaransa olkoon sinun kädessäs, ainoastaan älä häneen kättäs satuta. Silloin läksi saatana Herran tyköä."],[1,13,"Mutta sinä päivänä, kuin hänen poikansa ja tyttärensä söivät ja joivat viinaa vanhimman veljensä huoneessa,","Mutta sinä päivänä, kuin hänen poikansa ja tyttärensä söivät ja joivat viinaa vanhimman veljensä huoneessa,"],[1,14,"Tuli sanansaattaja Jobin tykö ja sanoi: härjillä kynnettiin, ja aasit kävivät läsnä laitumella;","Tuli sanansaattaja Jobin tykö ja sanoi: härjillä kynnettiin, ja aasit kävivät läsnä laitumella;"],[1,15,"Niin he tulivat rikkaasta Arabiasta ja ottivat ne, ja löivät palveliat miekan terällä; ja minä ainoastaan yksin pääsin sanomaan sinulle.","Niin he tulivat rikkaasta Arabiasta ja ottivat ne, ja löivät palveliat miekan terällä; ja minä ainoastaan yksin pääsin sanomaan sinulle."],[1,16,"Kuin hän vielä puhui, tuli toinen ja sanoi: Jumalan tuli putosi taivaasta ja sytytti lampaat ja palveliat, ja poltti ne; ja minä ainoastaan yksin pääsin sanomaan sinulle.","Kuin hän vielä puhui, tuli toinen ja sanoi: Jumalan tuli putosi taivaasta ja sytytti lampaat ja palveliat, ja poltti ne; ja minä ainoastaan yksin pääsin sanomaan sinulle."],[1,17,"Kuin hän vielä puhui, tuli yksi ja sanoi: Kaldealaiset tekivät kolme joukkoa ja hyökkäsivät kamelein päälle, ja ottivat ne pois, ja löivät miekan terällä; ja minä ainoastaan yksin pääsin sanomaan sinulle.","Kuin hän vielä puhui, tuli yksi ja sanoi: Kaldealaiset tekivät kolme joukkoa ja hyökkäsivät kamelein päälle, ja ottivat ne pois, ja löivät miekan terällä; ja minä ainoastaan yksin pääsin sanomaan sinulle."],[1,18,"Kuin hän vielä puhui, tuli yksi ja sanoi: sinun poikas ja tyttäres söivät ja joivat viinaa vanhimman veljensä huoneessa.","Kuin hän vielä puhui, tuli yksi ja sanoi: sinun poikas ja tyttäres söivät ja joivat viinaa vanhimman veljensä huoneessa."],[1,19,"Ja katso, suuri tuulispää tuli korvesta ja sysäsi neljään huoneen nurkkaan, ja se kaatui nuorukaisten päälle, niin että he kuolivat; ja minä ainoastaan yksin pääsin sanomaan sinulle.","Ja katso, suuri tuulispää tuli korvesta ja sysäsi neljään huoneen nurkkaan, ja se kaatui nuorukaisten päälle, niin että he kuolivat; ja minä ainoastaan yksin pääsin sanomaan sinulle."],[1,20,"Silloin Job nousi ja repäisi vaatteensa, ja repi päätänsä, ja heittäysi maahan ja rukoili.","Silloin Job nousi ja repäisi vaatteensa, ja repi päätänsä, ja heittäysi maahan ja rukoili."],[1,21,"Ja sanoi: alasti olen minä tullut äitini kohdusta ja alasti pitää minun sinne jälleen menemän; Herra antoi ja Herra otti: Herran nimi olkoon kiitetty!","Ja sanoi: alasti olen minä tullut äitini kohdusta ja alasti pitää minun sinne jälleen menemän; Herra antoi ja Herra otti: Herran nimi olkoon kiitetty!"],[1,22,"Näissä kaikissa ei rikkonut Job, eikä tehnyt tyhmästi Jumalaa vastaan.","Näissä kaikissa ei rikkonut Job, eikä tehnyt tyhmästi Jumalaa vastaan."],[2,1,"Ja tapahtui yhtenä päivänä, kuin Jumalan lapset tulivat ja astuivat Herran eteen, että saatana myös tuli heidän kanssansa ja astui Herran eteen.","Ja tapahtui yhtenä päivänä, kuin Jumalan lapset tulivat ja astuivat Herran eteen, että saatana myös tuli heidän kanssansa ja astui Herran eteen."],[2,2,"Silloin sanoi Herra saatanalle: kusta tulet? Saatana vastasi Herraa ja sanoi: minä olen käynyt ja vaeltanut ympäri maan.","Silloin sanoi Herra saatanalle: kusta tulet? Saatana vastasi Herraa ja sanoi: minä olen käynyt ja vaeltanut ympäri maan."],[2,3,"Ja Herra sanoi saatanalle: etkös ole ottanut vaaria palveliastani Jobista? sillä ei hänen vertaistansa ole maalla: hän on vakaa ja hurskas ja Jumalaa pelkääväinen mies, ja välttää pahaa ja pysyy vielä vakuudessansa, ja sinä yllytit minua häntä hävittämään ilman syytä.","Ja Herra sanoi saatanalle: etkös ole ottanut vaaria palveliastani Jobista? sillä ei hänen vertaistansa ole maalla: hän on vakaa ja hurskas ja Jumalaa pelkääväinen mies, ja välttää pahaa ja pysyy vielä vakuudessansa, ja sinä yllytit minua häntä hävittämään ilman syytä."],[2,4,"Saatana vastasi Herraa ja sanoi: nahka nahasta, ja kaikki, mitä ihmisessä on, antaa hän henkensä edestä.","Saatana vastasi Herraa ja sanoi: nahka nahasta, ja kaikki, mitä ihmisessä on, antaa hän henkensä edestä."],[2,5,"Mutta ojenna kätes ja rupee hänen luihinsa ja lihaansa; mitämaks hän luopuu sinusta kasvois edessä.","Mutta ojenna kätes ja rupee hänen luihinsa ja lihaansa; mitämaks hän luopuu sinusta kasvois edessä."],[2,6,"Herra sanoi saatanalle: katso, hän olkoon sinun kädessäs; kuitenkin säästä hänen henkeänsä.","Herra sanoi saatanalle: katso, hän olkoon sinun kädessäs; kuitenkin säästä hänen henkeänsä."],[2,7,"Silloin läksi saatana Herran tyköä ja löi Jobin pahoilla paisumilla, hänen kantapäästä kiireesen asti.","Silloin läksi saatana Herran tyköä ja löi Jobin pahoilla paisumilla, hänen kantapäästä kiireesen asti."],[2,8,"Ja hän otti saviastian ja kaapi itseänsä sillä, ja istui tuhassa.","Ja hän otti saviastian ja kaapi itseänsä sillä, ja istui tuhassa."],[2,9,"Ja hänen emäntänsä sanoi hänelle: Vieläkös pysyt vakuudessas? siunaa Jumalaa ja kuole.","Ja hänen emäntänsä sanoi hänelle: Vieläkös pysyt vakuudessas? siunaa Jumalaa ja kuole."],[2,10,"Mutta hän sanoi hänelle: sinä puhut niinkuin tyhmät vaimot puhuvat. Jos me olemme hyvää saaneet Jumalalta, eikö myös meidän pidä ottaman pahaa vastaan? Kaikissa näissä ei Job syntiä tehnyt huulillansa.","Mutta hän sanoi hänelle: sinä puhut niinkuin tyhmät vaimot puhuvat. Jos me olemme hyvää saaneet Jumalalta, eikö myös meidän pidä ottaman pahaa vastaan? Kaikissa näissä ei Job syntiä tehnyt huulillansa."],[2,11,"Kuin Jobin kolme ystävää kuulivat kaiken sen onnettomuuden, joka hänelle tullut oli, tulivat he itsekukin paikkakunnastansa: Eliphas Temanista, Bildad Suasta ja Zophar Naemasta, ja kokoontuivat ynnä tulemaan, armahtelemaan ja lohduttamaan häntä.","Kuin Jobin kolme ystävää kuulivat kaiken sen onnettomuuden, joka hänelle tullut oli, tulivat he itsekukin paikkakunnastansa: Eliphas Temanista, Bildad Suasta ja Zophar Naemasta, ja kokoontuivat ynnä tulemaan, armahtelemaan ja lohduttamaan häntä."],[2,12,"Ja kuin he nostivat taampaa silmänsä, ei he häntä tunteneet, ja korottivat äänensä ja itkivät; ja jokainen repäisi vaatteensa, ja heittivät tomua päänsä päälle taivasta kohden,","Ja kuin he nostivat taampaa silmänsä, ei he häntä tunteneet, ja korottivat äänensä ja itkivät; ja jokainen repäisi vaatteensa, ja heittivät tomua päänsä päälle taivasta kohden,"],[2,13,"Ja istuivat hänen kanssansa maan päällä seitsemän päivää ja seitsemän yötä, ja ei sanaakaan hänen kanssansa puhuneet; sillä he näkivät hänen kipunsa sangen suureksi.","Ja istuivat hänen kanssansa maan päällä seitsemän päivää ja seitsemän yötä, ja ei sanaakaan hänen kanssansa puhuneet; sillä he näkivät hänen kipunsa sangen suureksi."],[3,1,"Sitte avasi Job suunsa ja kirosi päivänsä.","Sitte avasi Job suunsa ja kirosi päivänsä."],[3,2,"Ja Job vastasi ja sanoi:","Ja Job vastasi ja sanoi:"],[3,3,"Se päivä olkoon kadotettu, jona minä syntynyt olen, ja se yö, jona sanottiin: mies on siinnyt.","Se päivä olkoon kadotettu, jona minä syntynyt olen, ja se yö, jona sanottiin: mies on siinnyt."],[3,4,"Se päivä olkoon pimiä, ja älköön Jumala kysykö ylhäältä sen perään: älköön kirkkaus paistako hänen päällensä.","Se päivä olkoon pimiä, ja älköön Jumala kysykö ylhäältä sen perään: älköön kirkkaus paistako hänen päällensä."],[3,5,"Pimeys ja kuolon varjo peittäköön hänen, olkoon pilvi hänen päällänsä; ja musta päivän sumu tehkään hänen kauhiaksi.","Pimeys ja kuolon varjo peittäköön hänen, olkoon pilvi hänen päällänsä; ja musta päivän sumu tehkään hänen kauhiaksi."],[3,6,"Sen yön käsittäköön pimeys, ja älkään iloitko vuosikausien päiväin seassa, ja älkään tulko kuukausien lukuun.","Sen yön käsittäköön pimeys, ja älkään iloitko vuosikausien päiväin seassa, ja älkään tulko kuukausien lukuun."],[3,7,"Katso, olkoon se yö yksinäinen ja älköön yhtäkään iloa tulko siihen.","Katso, olkoon se yö yksinäinen ja älköön yhtäkään iloa tulko siihen."],[3,8,"Ne jotka päivää kiroovat, he kirotkoot sitä, ne jotka ovat valmiit herättämään Leviatania.","Ne jotka päivää kiroovat, he kirotkoot sitä, ne jotka ovat valmiit herättämään Leviatania."],[3,9,"Sen tähdet olkoot pimiät hämärässänsä, odottakoot valkeutta, ja ei tulko, ja älkööt nähkö aamuruskon silmäripsiä,","Sen tähdet olkoot pimiät hämärässänsä, odottakoot valkeutta, ja ei tulko, ja älkööt nähkö aamuruskon silmäripsiä,"],[3,10,"Ettei se sulkenut minun kohtuni ovea, ja ei kätkenyt onnettomuutta silmäini edestä.","Ettei se sulkenut minun kohtuni ovea, ja ei kätkenyt onnettomuutta silmäini edestä."],[3,11,"Miksi en minä kuollut äitini kohdussa? Miksi en minä läkähtynyt äitini kohdusta tultuani?","Miksi en minä kuollut äitini kohdussa? Miksi en minä läkähtynyt äitini kohdusta tultuani?"],[3,12,"Miksi he ovat ottaneet minun helmaansa? Miksi minä olen nisiä imenyt?","Miksi he ovat ottaneet minun helmaansa? Miksi minä olen nisiä imenyt?"],[3,13,"Niin minä nyt makaisin, olisin alallani, lepäisin, ja minulla olis lepo.","Niin minä nyt makaisin, olisin alallani, lepäisin, ja minulla olis lepo."],[3,14,"Maan kuningasten ja neuvojain kanssa, jotka heillensä rakentavat sitä mikä kylmillä on;","Maan kuningasten ja neuvojain kanssa, jotka heillensä rakentavat sitä mikä kylmillä on;"],[3,15,"Eli päämiesten kanssa, joilla kultaa on, ja joiden huoneet ovat täynnä hopiaa;","Eli päämiesten kanssa, joilla kultaa on, ja joiden huoneet ovat täynnä hopiaa;"],[3,16,"Eli niinkuin keskensyntyneet kätketyt; ja en oliskaan: niinkuin nuoret lapset, jotka ei koskaan valkeutta nähneet.","Eli niinkuin keskensyntyneet kätketyt; ja en oliskaan: niinkuin nuoret lapset, jotka ei koskaan valkeutta nähneet."],[3,17,"Siellä täytyy jumalattomain lakata väkivallastansa; siellä ovat ne levossa, jotka paljon vaivaa nähneet ovat;","Siellä täytyy jumalattomain lakata väkivallastansa; siellä ovat ne levossa, jotka paljon vaivaa nähneet ovat;"],[3,18,"Siellä on vangeilla rauha muiden kanssa, ja ei kuule vaatian ääntä;","Siellä on vangeilla rauha muiden kanssa, ja ei kuule vaatian ääntä;"],[3,19,"Siellä ovat sekä pienet että suuret, ja palveliat vapaat isännistänsä:","Siellä ovat sekä pienet että suuret, ja palveliat vapaat isännistänsä:"],[3,20,"Miksi valkeus on annettu vaivaisille, ja elämä murheellisille sydämille?","Miksi valkeus on annettu vaivaisille, ja elämä murheellisille sydämille?"],[3,21,"Niille, jotka odottavat kuolemaa, ja ei se tule, ja kaivaisivat sitä ennen kuin aarnihautaa?","Niille, jotka odottavat kuolemaa, ja ei se tule, ja kaivaisivat sitä ennen kuin aarnihautaa?"],[3,22,"Niille, jotka kovin iloitsevat ja riemuitsevat, että he saisivat haudan?","Niille, jotka kovin iloitsevat ja riemuitsevat, että he saisivat haudan?"],[3,23,"Ja sille miehelle, jonka tie kätketty on, ja hänen edestänsä Jumalalta peitetty?","Ja sille miehelle, jonka tie kätketty on, ja hänen edestänsä Jumalalta peitetty?"],[3,24,"Sillä minun leipäni tykönä minä huokaan, ja minun parkuni vuodatetaan niinkuin vesi,","Sillä minun leipäni tykönä minä huokaan, ja minun parkuni vuodatetaan niinkuin vesi,"],[3,25,"Sillä jota minä pelkäsin, se tuli minun päälleni, ja mitä minä kartin, tapahtui minulle.","Sillä jota minä pelkäsin, se tuli minun päälleni, ja mitä minä kartin, tapahtui minulle."],[3,26,"Enkö minä ollut onnellinen? enkö minä ollut rauhassa? eikö minulla ollut hyvä lepo? ja nyt senkaltainen levottomuus tulee.","Enkö minä ollut onnellinen? enkö minä ollut rauhassa? eikö minulla ollut hyvä lepo? ja nyt senkaltainen levottomuus tulee."],[4,1,"Ja Eliphas Temanilainen vastasi ja sanoi,","Ja Eliphas Temanilainen vastasi ja sanoi,"],[4,2,"Jos joku sinun kanssas rupeis puhumaan: mitämaks et sinä sitä kärsi; mutta kuka taitaa vaiti olla?","Jos joku sinun kanssas rupeis puhumaan: mitämaks et sinä sitä kärsi; mutta kuka taitaa vaiti olla?"],[4,3,"Katso, sinä olet monta neuvonut, ja vahvistanut väsyneitä käsiä.","Katso, sinä olet monta neuvonut, ja vahvistanut väsyneitä käsiä."],[4,4,"Sinun puhees on ojentanut langenneita, ja vapisevaisia polvia vahvistanut.","Sinun puhees on ojentanut langenneita, ja vapisevaisia polvia vahvistanut."],[4,5,"Mutta että se nyt tulee sinun päälles, niin sinä väsyit, ja että se lankesi sinun päälles, niin sinä peljästyit.","Mutta että se nyt tulee sinun päälles, niin sinä väsyit, ja että se lankesi sinun päälles, niin sinä peljästyit."],[4,6,"Tämäkö on sinun (Jumalan) pelkos, sinun uskallukses, sinun toivos ja sinun vakuutes?","Tämäkö on sinun (Jumalan) pelkos, sinun uskallukses, sinun toivos ja sinun vakuutes?"],[4,7,"Muistele nyt, kussa joku viatoin on hukkunut? eli kussa hurskaat ovat joskus hävinneet?","Muistele nyt, kussa joku viatoin on hukkunut? eli kussa hurskaat ovat joskus hävinneet?"],[4,8,"Niinkuin minä kyllä nähnyt olen, ne jotka kyntävät vääryyden, ja onnettomuuden kylvävät, sitä he myös niittävät.","Niinkuin minä kyllä nähnyt olen, ne jotka kyntävät vääryyden, ja onnettomuuden kylvävät, sitä he myös niittävät."],[4,9,"He ovat Jumalan puhalluksen kautta kadonneet, ja hänen vihansa hengeltä hukatut.","He ovat Jumalan puhalluksen kautta kadonneet, ja hänen vihansa hengeltä hukatut."],[4,10,"Jalopeuran kiljumus, ja julma jalopeuran ääni, ja nuorten jalopeurain hampaat ovat lovistetut.","Jalopeuran kiljumus, ja julma jalopeuran ääni, ja nuorten jalopeurain hampaat ovat lovistetut."],[4,11,"Vanha jalopeura hukkuu, ettei hänellä ole saalista; ja jalopeuran pojat hajoitetaan.","Vanha jalopeura hukkuu, ettei hänellä ole saalista; ja jalopeuran pojat hajoitetaan."],[4,12,"Ja minun tyköni on tullut salainen sana; ja minun korvani on saanut vähäisen siitä.","Ja minun tyköni on tullut salainen sana; ja minun korvani on saanut vähäisen siitä."],[4,13,"Kuin minä ajattelin yönäkyjä, kuin uni lankee ihmisten päälle,","Kuin minä ajattelin yönäkyjä, kuin uni lankee ihmisten päälle,"],[4,14,"Niin pelko ja vavistus tuli minun päälleni, ja kaikki minun luuni peljätettiin;","Niin pelko ja vavistus tuli minun päälleni, ja kaikki minun luuni peljätettiin;"],[4,15,"Ja henki meni minun sivuitseni; kaikki minun karvani nousivat ruumiissani.","Ja henki meni minun sivuitseni; kaikki minun karvani nousivat ruumiissani."],[4,16,"Silloin seisoi kuva minun silmäini edessä, jonka kasvoja en minä tuntenut; ja minä kuulin hiljaisen hyminän äänen:","Silloin seisoi kuva minun silmäini edessä, jonka kasvoja en minä tuntenut; ja minä kuulin hiljaisen hyminän äänen:"],[4,17,"Kuinka on ihminen hurskaampi kuin JumaIa? eli joku mies puhtaampi kuin se, joka hänen tehnyt on?","Kuinka on ihminen hurskaampi kuin JumaIa? eli joku mies puhtaampi kuin se, joka hänen tehnyt on?"],[4,18,"Katso, palveliainsa seassa ei löydä hän uskollisuutta ja enkeleissänsä löytää hän tyhmyyden:","Katso, palveliainsa seassa ei löydä hän uskollisuutta ja enkeleissänsä löytää hän tyhmyyden:"],[4,19,"Kuinka enemmin niissä jotka asuvat savihuoneissa, niissä jotka ovat perustetut maan päälle, jotka toukkain tavalla murentuvat?","Kuinka enemmin niissä jotka asuvat savihuoneissa, niissä jotka ovat perustetut maan päälle, jotka toukkain tavalla murentuvat?"],[4,20,"Se pysyy aamusta ehtoosen asti, niin he muserretaan; ja ennenkuin he sen havaitsevat, he ijankaikkisesti hukkuvat.","Se pysyy aamusta ehtoosen asti, niin he muserretaan; ja ennenkuin he sen havaitsevat, he ijankaikkisesti hukkuvat."],[4,21,"Eikö heidän jälkeenjääneensä pois oteta? he kuolevat, vaan ei viisaudessa.","Eikö heidän jälkeenjääneensä pois oteta? he kuolevat, vaan ei viisaudessa."],[5,1,"Nimitä siis, jos joku on, joka kanssas todistaa, ja kenen tykö pyhistä sinä itses käännät?","Nimitä siis, jos joku on, joka kanssas todistaa, ja kenen tykö pyhistä sinä itses käännät?"],[5,2,"Mutta tyhmän tappaa viha, ja taitamattoman kuolettaa kiivaus.","Mutta tyhmän tappaa viha, ja taitamattoman kuolettaa kiivaus."],[5,3,"Minä näin tyhmän juurtuneen, ja kirosin kohta hänen huonettansa.","Minä näin tyhmän juurtuneen, ja kirosin kohta hänen huonettansa."],[5,4,"Hänen lapsensa pitää oleman kaukana terveydestä; ja pitää rikki murrettaman portissa, kussa ei yhtään auttajaa ole.","Hänen lapsensa pitää oleman kaukana terveydestä; ja pitää rikki murrettaman portissa, kussa ei yhtään auttajaa ole."],[5,5,"Hänen elonsa pitää isoovaisen syömän, ja orjantappuroista sen ottaman; ja hänen kalunsa pitää ryövärien nielemän.","Hänen elonsa pitää isoovaisen syömän, ja orjantappuroista sen ottaman; ja hänen kalunsa pitää ryövärien nielemän."],[5,6,"Sillä ei vaiva käy ylös tomusta; ja onnettomuus ei kasva maasta.","Sillä ei vaiva käy ylös tomusta; ja onnettomuus ei kasva maasta."],[5,7,"Vaan ihminen syntyy onnettomuuteen; niinkuin kuumain hiilten kipinät sinkoilevat ylöskäsin.","Vaan ihminen syntyy onnettomuuteen; niinkuin kuumain hiilten kipinät sinkoilevat ylöskäsin."],[5,8,"Kuitenkin tahdon minä Jumalasta tutkistella: Jumalasta minä tahdon puhua,","Kuitenkin tahdon minä Jumalasta tutkistella: Jumalasta minä tahdon puhua,"],[5,9,"Joka voimallisia töitä tekee, joita ei tutkia taideta, ja ihmeitä, joita ei lukea taideta;","Joka voimallisia töitä tekee, joita ei tutkia taideta, ja ihmeitä, joita ei lukea taideta;"],[5,10,"Joka antaa sateen maan päälle, ja antaa tulla veden teiden päälle;","Joka antaa sateen maan päälle, ja antaa tulla veden teiden päälle;"],[5,11,"Joka ylentää nöyrät korkeuteen, ja korottaa sorrettuja autuuteen.","Joka ylentää nöyrät korkeuteen, ja korottaa sorrettuja autuuteen."],[5,12,"Hän tekee kavalain aivoitukset tyhjäksi, ettei heidän kätensä mitään toimittaa taida.","Hän tekee kavalain aivoitukset tyhjäksi, ettei heidän kätensä mitään toimittaa taida."],[5,13,"Hän käsittää taitavat kavaluudessansa, ja pahain neuvo kukistetaan,","Hän käsittää taitavat kavaluudessansa, ja pahain neuvo kukistetaan,"],[5,14,"Että he päivällä juoksevat pimeydessä, ja koperoitsevat puolipäivänä niinkuin yöllä.","Että he päivällä juoksevat pimeydessä, ja koperoitsevat puolipäivänä niinkuin yöllä."],[5,15,"Ja hän auttaa köyhää miekasta, ja heidän suustansa, ja voimallisten kädestä.","Ja hän auttaa köyhää miekasta, ja heidän suustansa, ja voimallisten kädestä."],[5,16,"Ja hän on köyhän turva, että vääryys pitäis suunsa kiinni.","Ja hän on köyhän turva, että vääryys pitäis suunsa kiinni."],[5,17,"Katso, autuas on se ihminen, jota Jumala kurittaa; sentähden älä hylkää Kaikkivaltiaan kuritusta.","Katso, autuas on se ihminen, jota Jumala kurittaa; sentähden älä hylkää Kaikkivaltiaan kuritusta."],[5,18,"Sillä hän haavoittaa ja sitoo; hän lyö ja hänen kätensä terveeksi tekee.","Sillä hän haavoittaa ja sitoo; hän lyö ja hänen kätensä terveeksi tekee."],[5,19,"Kuudesta murheesta päästää hän sinun; ja seitsemännestä ei tule mitään pahaa sinulle.","Kuudesta murheesta päästää hän sinun; ja seitsemännestä ei tule mitään pahaa sinulle."],[5,20,"Kalliilla ajalla vapahtaa hän sinun kuolemasta, ja sodassa miekasta.","Kalliilla ajalla vapahtaa hän sinun kuolemasta, ja sodassa miekasta."],[5,21,"Hän peittää sinun kielen ruoskalta; ja ei sinun pidä pelkäämän hävitystä, koska se tulee.","Hän peittää sinun kielen ruoskalta; ja ei sinun pidä pelkäämän hävitystä, koska se tulee."],[5,22,"Hävityksessä ja nälässä sinä naurat; ja et pelkää metsän petoja.","Hävityksessä ja nälässä sinä naurat; ja et pelkää metsän petoja."],[5,23,"Sillä sinun liittos pitää oleman kivien kanssa kedolla, ja maan pedot pitää sinun kanssas rauhallisesti oleman.","Sillä sinun liittos pitää oleman kivien kanssa kedolla, ja maan pedot pitää sinun kanssas rauhallisesti oleman."],[5,24,"Sinä ymmärrät, että sinun majas on rauhassa, ja sinä oleskelet asuinsiassas ilman syntiä.","Sinä ymmärrät, että sinun majas on rauhassa, ja sinä oleskelet asuinsiassas ilman syntiä."],[5,25,"Ja sinä saat ymmärtää, että siemenes on suureksi tuleva, ja vesas niinkuin ruoho maassa.","Ja sinä saat ymmärtää, että siemenes on suureksi tuleva, ja vesas niinkuin ruoho maassa."],[5,26,"Ja sinä tulet vanhalla ijällä hautaan, niinkuin elositoma ajallansa korjataan.","Ja sinä tulet vanhalla ijällä hautaan, niinkuin elositoma ajallansa korjataan."],[5,27,"Katso, sitä me olemme tutkineet, ja se on niin: kuule sitä, ja tunne sinä myös se hyväkses.","Katso, sitä me olemme tutkineet, ja se on niin: kuule sitä, ja tunne sinä myös se hyväkses."],[6,1,"Niin Job vastasi ja sanoi:","Niin Job vastasi ja sanoi:"],[6,2,"Jos minun surkeuteni punnittaisiin, ja minun kärsimiseni yhtä haavaa laskettaisiin vaa´an päälle,","Jos minun surkeuteni punnittaisiin, ja minun kärsimiseni yhtä haavaa laskettaisiin vaa´an päälle,"],[6,3,"Niin se olis raskaampi kuin santa meressä; sentähden ovat minun sanani nielletyt ylös.","Niin se olis raskaampi kuin santa meressä; sentähden ovat minun sanani nielletyt ylös."],[6,4,"Sillä Kaikkivaltiaan nuolet ovat minussa, joiden myrkky särpää minun henkeni; ja Jumalan kauhistus tarkoittaa minua.","Sillä Kaikkivaltiaan nuolet ovat minussa, joiden myrkky särpää minun henkeni; ja Jumalan kauhistus tarkoittaa minua."],[6,5,"Huutaako metsä-aasi, kuin hänellä ruohoja on? ammuuko härkä, kuin hänellä on ruokaa?","Huutaako metsä-aasi, kuin hänellä ruohoja on? ammuuko härkä, kuin hänellä on ruokaa?"],[6,6,"Syödäänkö mautointa ilman suolaa? eli maistaako valkuainen munan ruskuaisen ympäriltä?","Syödäänkö mautointa ilman suolaa? eli maistaako valkuainen munan ruskuaisen ympäriltä?"],[6,7,"Jota minun sieluni ennen kuoitti, se on nyt minun ruokani minun kipuni tähden.","Jota minun sieluni ennen kuoitti, se on nyt minun ruokani minun kipuni tähden."],[6,8,"Jospa minun rukoukseni tapahtuis, ja Jumala antais minulle, mitä minä toivon!","Jospa minun rukoukseni tapahtuis, ja Jumala antais minulle, mitä minä toivon!"],[6,9,"Että Jumala tahtois ja löis minun rikki, ja päästäis kätensä särkemään minua;","Että Jumala tahtois ja löis minun rikki, ja päästäis kätensä särkemään minua;"],[6,10,"Niin olis minulla vielä sitte lohdutus, ja minä vahvistuisin sairaudessani, ellei hän säästäisi minua: en ole mitään kuitenkaan kieltänyt pyhän puhetta.","Niin olis minulla vielä sitte lohdutus, ja minä vahvistuisin sairaudessani, ellei hän säästäisi minua: en ole mitään kuitenkaan kieltänyt pyhän puhetta."],[6,11,"Mikä on minun väkeni, että minä voisin toivoa? ja mikä on minun loppuni, että minun sieluni vois kärsiväinen olla?","Mikä on minun väkeni, että minä voisin toivoa? ja mikä on minun loppuni, että minun sieluni vois kärsiväinen olla?"],[6,12,"Onko minun väkeni kivinen? eli minun lihani vaskinen?","Onko minun väkeni kivinen? eli minun lihani vaskinen?"],[6,13,"Ei ole minulla missään apua; ja minun saatuni on pois ajettu minulta.","Ei ole minulla missään apua; ja minun saatuni on pois ajettu minulta."],[6,14,"Joka ei osoita lähimmäisellensä laupiutta, hän hylkää Kaikkivaltiaan pelvon.","Joka ei osoita lähimmäisellensä laupiutta, hän hylkää Kaikkivaltiaan pelvon."],[6,15,"Minun veljeni ovat rikkoneet minua vastaan, niinkuin oja ja niinkuin väkevä virta ohitse menneet,","Minun veljeni ovat rikkoneet minua vastaan, niinkuin oja ja niinkuin väkevä virta ohitse menneet,"],[6,16,"Jotka ovat kauhiat jäästä, ja jotka lumi peittää.","Jotka ovat kauhiat jäästä, ja jotka lumi peittää."],[6,17,"Kuin helle heitä ahdistaa, pitää heidän nääntymän, ja kuin palava on, pitää heidän katooman paikastansa.","Kuin helle heitä ahdistaa, pitää heidän nääntymän, ja kuin palava on, pitää heidän katooman paikastansa."],[6,18,"Heidän polkunsa poikkeevat pois; he raukeevat tyhjään ja hukkuvat.","Heidän polkunsa poikkeevat pois; he raukeevat tyhjään ja hukkuvat."],[6,19,"He katsoivat Temanin tietä, rikkaan Arabian polkuja he toivoivat.","He katsoivat Temanin tietä, rikkaan Arabian polkuja he toivoivat."],[6,20,"Mutta heidän pitää häpiään tuleman, ratki surutoinna ollessansa; ja heidän pitää häpeemän siihen tultuansa.","Mutta heidän pitää häpiään tuleman, ratki surutoinna ollessansa; ja heidän pitää häpeemän siihen tultuansa."],[6,21,"Sillä ette nyt mitään ole; ja että te näette surkeuden, pelkäätte te.","Sillä ette nyt mitään ole; ja että te näette surkeuden, pelkäätte te."],[6,22,"Olenko minä sanonut: Tuokaat minulle! eli antakaat minun edestäni lahjoja teidän tavarastanne?","Olenko minä sanonut: Tuokaat minulle! eli antakaat minun edestäni lahjoja teidän tavarastanne?"],[6,23,"Ja pelastakaat minua vihollisten kädestä, ja vapahtakaat minua tyrannein käsistä?","Ja pelastakaat minua vihollisten kädestä, ja vapahtakaat minua tyrannein käsistä?"],[6,24,"Opettakaat minua, minä olen ääneti, ja jota en minä tiedä, niin neuvokaat minua.","Opettakaat minua, minä olen ääneti, ja jota en minä tiedä, niin neuvokaat minua."],[6,25,"Kuinka vahvat ovat oikeuden puheet? kuka teissä on se, joka sitä laittaa taitaa?","Kuinka vahvat ovat oikeuden puheet? kuka teissä on se, joka sitä laittaa taitaa?"],[6,26,"Te ajattelette sanoja, ainoastaan nuhdellaksenne, ja teette sanoillanne epäileväisen mielen.","Te ajattelette sanoja, ainoastaan nuhdellaksenne, ja teette sanoillanne epäileväisen mielen."],[6,27,"Te karkaatte köyhän orvon päälle, ja kaivatte lähimmäisellenne kuoppaa.","Te karkaatte köyhän orvon päälle, ja kaivatte lähimmäisellenne kuoppaa."],[6,28,"Mutta että te nyt tahdotte, niin katsokaat minun päälleni, jos minä teidän edessänne valhettelen.","Mutta että te nyt tahdotte, niin katsokaat minun päälleni, jos minä teidän edessänne valhettelen."],[6,29,"Palatkaat nyt, olkoon pois vääryys: Tulkaat jälleen; minun vastaukseni pitää oikia oleman.","Palatkaat nyt, olkoon pois vääryys: Tulkaat jälleen; minun vastaukseni pitää oikia oleman."],[6,30,"Onko minun kielessäni vääryyttä? eikö minun suulakeni ymmärrä vaivoja?","Onko minun kielessäni vääryyttä? eikö minun suulakeni ymmärrä vaivoja?"],[7,1,"Eikö ihminen aina pidä oleman sodassa maan päällä; ja hänen päivänsä ovat niinkuin orjan päivät?","Eikö ihminen aina pidä oleman sodassa maan päällä; ja hänen päivänsä ovat niinkuin orjan päivät?"],[7,2,"Niinkuin palvelia halajaa varjoa, ja orja työnsä loppua,","Niinkuin palvelia halajaa varjoa, ja orja työnsä loppua,"],[7,3,"Niin olen minä minulleni saanut turhat kuukaudet, ja minulla on monta murheellista yötä ollut.","Niin olen minä minulleni saanut turhat kuukaudet, ja minulla on monta murheellista yötä ollut."],[7,4,"Kuin minä levätä panin, sanoin minä: Koskahan minä nousen? ja sitte lueskelen, koska ehtoo tullee: minä olen ravittu kävellyksistä hamaan pimeyteen asti.","Kuin minä levätä panin, sanoin minä: Koskahan minä nousen? ja sitte lueskelen, koska ehtoo tullee: minä olen ravittu kävellyksistä hamaan pimeyteen asti."],[7,5,"Minun lihani on puetettu madoilla ja maan tomulla; minun nahkani on ahvettunut ja hyljätyksi tullut.","Minun lihani on puetettu madoilla ja maan tomulla; minun nahkani on ahvettunut ja hyljätyksi tullut."],[7,6,"Minun päiväni ovat lentäneet nopiammasti pois kuin syöstävä ja kuluneet ilman viivytystä.","Minun päiväni ovat lentäneet nopiammasti pois kuin syöstävä ja kuluneet ilman viivytystä."],[7,7,"Muista, että minun elämäni on tuuli, ja minun silmäni ei palaja hyvää näkemään.","Muista, että minun elämäni on tuuli, ja minun silmäni ei palaja hyvää näkemään."],[7,8,"Ja ei yksikään silmä, joka minun nyt näkee, pidä minua enempi näkemän. Sinun silmäs katsokoon minua, sitte minä hukun.","Ja ei yksikään silmä, joka minun nyt näkee, pidä minua enempi näkemän. Sinun silmäs katsokoon minua, sitte minä hukun."],[7,9,"Pilvi raukee ja menee pois: niin myös se, joka menee alas hautaan, ei nouse jälleen,","Pilvi raukee ja menee pois: niin myös se, joka menee alas hautaan, ei nouse jälleen,"],[7,10,"Eikä palaja jälleen huoneesensa, ei myös hänen siansa häntä enää tunne.","Eikä palaja jälleen huoneesensa, ei myös hänen siansa häntä enää tunne."],[7,11,"Sentähden en minä estä suutani; minä puhun henkeni ahtaudessa, ja juttelen sieluni murheessa.","Sentähden en minä estä suutani; minä puhun henkeni ahtaudessa, ja juttelen sieluni murheessa."],[7,12,"Olenko minä meri eli valaskala, että sinä minun niin kätket?","Olenko minä meri eli valaskala, että sinä minun niin kätket?"],[7,13,"Kuin minä ajattelin: minun vuoteeni lohduttaa minun, ja minun kehtoni saattaa minulle levon, koska minä itselleni puhun;","Kuin minä ajattelin: minun vuoteeni lohduttaa minun, ja minun kehtoni saattaa minulle levon, koska minä itselleni puhun;"],[7,14,"Niin sinä peljätät minua unilla, ja kauhistat minua näyillä,","Niin sinä peljätät minua unilla, ja kauhistat minua näyillä,"],[7,15,"Että minun sieluni sois itsensä hirtetyksi, ja minun luuni kuolleiksi.","Että minun sieluni sois itsensä hirtetyksi, ja minun luuni kuolleiksi."],[7,16,"Minä kauhistun, enkä pyydä silleen elää: lakkaa minusta, sillä minun päiväni ovat turhat.","Minä kauhistun, enkä pyydä silleen elää: lakkaa minusta, sillä minun päiväni ovat turhat."],[7,17,"Mikä on ihminen,ettäs hänen suurena pidät, ja panet hänen sydämees?","Mikä on ihminen,ettäs hänen suurena pidät, ja panet hänen sydämees?"],[7,18,"Sinä etsit häntä joka päivä, ja koettelet häntä aina.","Sinä etsit häntä joka päivä, ja koettelet häntä aina."],[7,19,"Miksi et minusta luovu, ja päästä minua, siihen asti että minä sylkeni nielisin?","Miksi et minusta luovu, ja päästä minua, siihen asti että minä sylkeni nielisin?"],[7,20,"Minä olen syntiä tehnyt; mitä minun pitää sinulle tekemän, o sinä ihmisten vartia? miksis minun teit sinulles loukkaukseksi ja itselleni kuormaksi?","Minä olen syntiä tehnyt; mitä minun pitää sinulle tekemän, o sinä ihmisten vartia? miksis minun teit sinulles loukkaukseksi ja itselleni kuormaksi?"],[7,21,"Ja miksi et minun pahaa tekoani anna anteeksi ja ota pois minun vääryyttäni? Sillä nyt pitää minun makaaman mullassa: ja jos minua aamulla etsit, niin en minä enää ole.","Ja miksi et minun pahaa tekoani anna anteeksi ja ota pois minun vääryyttäni? Sillä nyt pitää minun makaaman mullassa: ja jos minua aamulla etsit, niin en minä enää ole."],[8,1,"Niin vastasi Bildad Suasta ja sanoi:","Niin vastasi Bildad Suasta ja sanoi:"],[8,2,"Kuinka kauvan sinä tahdot näitä puhua? ja sinun suus puheet ovat niinkuin väkevä tuuli?","Kuinka kauvan sinä tahdot näitä puhua? ja sinun suus puheet ovat niinkuin väkevä tuuli?"],[8,3,"Väärinkö Jumala tuomitsee, eli rikkooko Kaikkivaltias oikeuden?","Väärinkö Jumala tuomitsee, eli rikkooko Kaikkivaltias oikeuden?"],[8,4,"Jos poikas ovat syntiä tehneet hänen edessänsä, niin hän on hyljännyt heitä heidän pahain tekoinsa tähden.","Jos poikas ovat syntiä tehneet hänen edessänsä, niin hän on hyljännyt heitä heidän pahain tekoinsa tähden."],[8,5,"Mutta jos sinä aikanansa etsit Jumalaa, ja rukoilet Kaikkivaltiasta hartaasti,","Mutta jos sinä aikanansa etsit Jumalaa, ja rukoilet Kaikkivaltiasta hartaasti,"],[8,6,"Ja jos sinä olet puhdas ja hyvä, niin hän herättää sinun, ja taas tekee rauhalliseksi hurskautes majan.","Ja jos sinä olet puhdas ja hyvä, niin hän herättää sinun, ja taas tekee rauhalliseksi hurskautes majan."],[8,7,"Ja kussa sinulla oli ennen vähä, pitää tästedes sinulle sangen paljon lisääntymän.","Ja kussa sinulla oli ennen vähä, pitää tästedes sinulle sangen paljon lisääntymän."],[8,8,"Sillä kysy nyt entisiltä sukukunnilta, ja rupee kysymään heidän isiltänsä.","Sillä kysy nyt entisiltä sukukunnilta, ja rupee kysymään heidän isiltänsä."],[8,9,"Sillä me olemme niinkuin eilen tulleet, ja emme mitään tiedä: meidän elämämme on niinkuin varjo maan päällä.","Sillä me olemme niinkuin eilen tulleet, ja emme mitään tiedä: meidän elämämme on niinkuin varjo maan päällä."],[8,10,"Heidän pitää opettaman sinua, ja sanoman sinulle, ja tuoman puheensa edes sydämestänsä.","Heidän pitää opettaman sinua, ja sanoman sinulle, ja tuoman puheensa edes sydämestänsä."],[8,11,"Kasvaako kaisla, ellei seiso loassa? eli kasvaako ruoho ilman vettä?","Kasvaako kaisla, ellei seiso loassa? eli kasvaako ruoho ilman vettä?"],[8,12,"Koska se vielä kukoistaa ennenkuin se niitetään, kuivettuu se ennenkuin heinä korjataan.","Koska se vielä kukoistaa ennenkuin se niitetään, kuivettuu se ennenkuin heinä korjataan."],[8,13,"Niin käy kaikkein niiden, jotka Jumalan unhottavat, ja ulkokullattuin toivo katoo.","Niin käy kaikkein niiden, jotka Jumalan unhottavat, ja ulkokullattuin toivo katoo."],[8,14,"Sillä hänen toivonsa tulee tyhjäksi, ja hänen uskalluksensa niinkuin hämähäkin verkko.","Sillä hänen toivonsa tulee tyhjäksi, ja hänen uskalluksensa niinkuin hämähäkin verkko."],[8,15,"Hän luottaa huoneensa päälle, ja ei se pidä seisoman; hän turvaa siihen, ja ei se pidä pysyväinen oleman.","Hän luottaa huoneensa päälle, ja ei se pidä seisoman; hän turvaa siihen, ja ei se pidä pysyväinen oleman."],[8,16,"Se viheriöitsee kyllä ennen auringon nousemaa, ja sen heikot oksat kasvavat hänen yrttitarhassansa.","Se viheriöitsee kyllä ennen auringon nousemaa, ja sen heikot oksat kasvavat hänen yrttitarhassansa."],[8,17,"Hänen juurensa seisoo paksuna lähteen tykönä, ja huoneet kivien päällä.","Hänen juurensa seisoo paksuna lähteen tykönä, ja huoneet kivien päällä."],[8,18,"Mutta koska hän nielee sen paikastansa, kieltää hän sen, niinkuin ei olis nähnytkään sitä.","Mutta koska hän nielee sen paikastansa, kieltää hän sen, niinkuin ei olis nähnytkään sitä."],[8,19,"Katso, tämä on hänen menonsa riemu; ja toiset taas kasvavat tuhasta.","Katso, tämä on hänen menonsa riemu; ja toiset taas kasvavat tuhasta."],[8,20,"Sentähden katso, ei Jumala hyviä hylkää, eikä vahvista pahain kättä,","Sentähden katso, ei Jumala hyviä hylkää, eikä vahvista pahain kättä,"],[8,21,"Siihen asti että sinun suus naurulla täytetään ja huules riemulla.","Siihen asti että sinun suus naurulla täytetään ja huules riemulla."],[8,22,"Mutta ne jotka sinua vihaavat, pitää häpiään tuleman; ja jumalattomain asuinsia ei pidä pysyväinen oleman.","Mutta ne jotka sinua vihaavat, pitää häpiään tuleman; ja jumalattomain asuinsia ei pidä pysyväinen oleman."],[9,1,"Job vastasi ja sanoi:","Job vastasi ja sanoi:"],[9,2,"Minä kyllä sen tiedän, että niin on, ettei ihminen taida hurskas olla Jumalan edessä.","Minä kyllä sen tiedän, että niin on, ettei ihminen taida hurskas olla Jumalan edessä."],[9,3,"Jos hän tahtois riidellä hänen kanssansa, ei hän taitais vastata häntä yhtä tuhanteen.","Jos hän tahtois riidellä hänen kanssansa, ei hän taitais vastata häntä yhtä tuhanteen."],[9,4,"Hän on viisas ja voimallinen: kenenkä siitä on hyvää ollut, kuin häntä vastaan on itsensä asettanut?","Hän on viisas ja voimallinen: kenenkä siitä on hyvää ollut, kuin häntä vastaan on itsensä asettanut?"],[9,5,"Hän siirtää vuoret ennenkuin he sen ymmärtävät, jotka hän vihassansa kukistaa.","Hän siirtää vuoret ennenkuin he sen ymmärtävät, jotka hän vihassansa kukistaa."],[9,6,"Hän liikuttaa maan siastansa, niin että sen patsaat vapisevat.","Hän liikuttaa maan siastansa, niin että sen patsaat vapisevat."],[9,7,"Hän puhuu auringolle, niin ei se nouse; ja hän lukitsee tähdet.","Hän puhuu auringolle, niin ei se nouse; ja hän lukitsee tähdet."],[9,8,"Hän yksin levittää taivaat, ja käy meren aaltoin päällä.","Hän yksin levittää taivaat, ja käy meren aaltoin päällä."],[9,9,"Hän tekee Otavan ja Kointähden, Seulaiset ja ne tähdet etelään päin.","Hän tekee Otavan ja Kointähden, Seulaiset ja ne tähdet etelään päin."],[9,10,"Hän tekee suuria töitä, joita ei taideta tutkia, ja epälukuisia ihmeitä.","Hän tekee suuria töitä, joita ei taideta tutkia, ja epälukuisia ihmeitä."],[9,11,"Katso, hän käy minun ohitseni ennenkuin minä sen havaitsen, ja menee pois ennenkuin minä sen ymmärrän.","Katso, hän käy minun ohitseni ennenkuin minä sen havaitsen, ja menee pois ennenkuin minä sen ymmärrän."],[9,12,"Katso, jos hän menee äkisti, kuka noutaa hänen jälleen? kuka sanoo hänelle: mitäs teet?","Katso, jos hän menee äkisti, kuka noutaa hänen jälleen? kuka sanoo hänelle: mitäs teet?"],[9,13,"Hän on Jumala, hänen vihaansa ei yksikään aseta; hänen allensa pitää itsensä kumartaman ylpiätkin herrat.","Hän on Jumala, hänen vihaansa ei yksikään aseta; hänen allensa pitää itsensä kumartaman ylpiätkin herrat."],[9,14,"Kuinka minun pitäisi häntä vastaaman, ja löytämän sanoja häntä vastaan?","Kuinka minun pitäisi häntä vastaaman, ja löytämän sanoja häntä vastaan?"],[9,15,"Ehkä minulla vielä oikeus olis, niin en kuitenkaan taida minä häntä vastata; vaan täytyis oikeudessa rukoilla.","Ehkä minulla vielä oikeus olis, niin en kuitenkaan taida minä häntä vastata; vaan täytyis oikeudessa rukoilla."],[9,16,"Ja ehkä minä vielä häntä avuksihuutaisin, ja hän kuulis minua, niin en minä uskoisi, että hän kuultelis minun ääntäni;","Ja ehkä minä vielä häntä avuksihuutaisin, ja hän kuulis minua, niin en minä uskoisi, että hän kuultelis minun ääntäni;"],[9,17,"Sillä hän hän runtelee minun tuulispäällä, ja enentää minun haavani ilman syytä.","Sillä hän hän runtelee minun tuulispäällä, ja enentää minun haavani ilman syytä."],[9,18,"Ei hän anna minun henkeni virota, vaan täyttää minun murheella.","Ei hän anna minun henkeni virota, vaan täyttää minun murheella."],[9,19,"Jos joku tahtoo voimaa, katso, hän on voimallinen; jos joku tahtoo oikeutta, kuka todistaa minun kanssani?","Jos joku tahtoo voimaa, katso, hän on voimallinen; jos joku tahtoo oikeutta, kuka todistaa minun kanssani?"],[9,20,"Jos minä sanoisin: minä olen oikia, niin minun suuni kuitenkin tuomitsee minun: eli minä olen vakaa, niin hän kuitenkin tekee minun pahaksi.","Jos minä sanoisin: minä olen oikia, niin minun suuni kuitenkin tuomitsee minun: eli minä olen vakaa, niin hän kuitenkin tekee minun pahaksi."],[9,21,"Ehkä minä vielä vakaa olisin, niin en minä kuitenkaan tunne itsiäni; vaan minä suutun eIämääni.","Ehkä minä vielä vakaa olisin, niin en minä kuitenkaan tunne itsiäni; vaan minä suutun eIämääni."],[9,22,"Se on se ainoa minkä minä sanonut olen, hän kadottaa hyvän ja jumalattoman.","Se on se ainoa minkä minä sanonut olen, hän kadottaa hyvän ja jumalattoman."],[9,23,"Kuin hän rupee lyömään, niin hän tappaa äkisti, ja pilkkaa viattomain kiusausta.","Kuin hän rupee lyömään, niin hän tappaa äkisti, ja pilkkaa viattomain kiusausta."],[9,24,"Maa annetaan jumalattoman käsiin, hän peittää sen tuomarien kasvot: ellei se niin ole, kuinka se myös toisin on?","Maa annetaan jumalattoman käsiin, hän peittää sen tuomarien kasvot: ellei se niin ole, kuinka se myös toisin on?"],[9,25,"Minun päiväni ovat olleet nopiammat kuin juoksia: ne ovat paenneet, ja ei mitään hyvää nähneet.","Minun päiväni ovat olleet nopiammat kuin juoksia: ne ovat paenneet, ja ei mitään hyvää nähneet."],[9,26,"Ne ovat pois menneet kuin joutuva haaksi, kuin kotka lentää rualle.","Ne ovat pois menneet kuin joutuva haaksi, kuin kotka lentää rualle."],[9,27,"Koska minä ajattelen: minä unhotan valitukseni, ja muutan kasvoni ja virvoitan minuni:","Koska minä ajattelen: minä unhotan valitukseni, ja muutan kasvoni ja virvoitan minuni:"],[9,28,"Niin minä pelkään kaikkia minun kipujani, tietäen, ettes anna minun olla viatoinna.","Niin minä pelkään kaikkia minun kipujani, tietäen, ettes anna minun olla viatoinna."],[9,29,"Jos olen jumalatoin, miksi minä nyt itsiäni hukkaan vaivaan?","Jos olen jumalatoin, miksi minä nyt itsiäni hukkaan vaivaan?"],[9,30,"Vaikka minä pesisin itseni lumivedessä ja puhdistaisin käteni saippualla,","Vaikka minä pesisin itseni lumivedessä ja puhdistaisin käteni saippualla,"],[9,31,"Niin sinä kuitenkin pistäisit minun lokaan; ja minun vaatteeni olisivat minulle kauhistukseksi.","Niin sinä kuitenkin pistäisit minun lokaan; ja minun vaatteeni olisivat minulle kauhistukseksi."],[9,32,"Sillä ei hän ole minun vertaiseni, jota minä vastata taidan, että me ynnä tulisimme oikeuden eteen.","Sillä ei hän ole minun vertaiseni, jota minä vastata taidan, että me ynnä tulisimme oikeuden eteen."],[9,33,"Ei ole joka meitä eroittaa, joka laskis kätensä meidän kahden välillemme.","Ei ole joka meitä eroittaa, joka laskis kätensä meidän kahden välillemme."],[9,34,"Hän ottakoon vitsansa pois minusta, ja älköön hänen hirmuisuutensa peljättäkö minua;","Hän ottakoon vitsansa pois minusta, ja älköön hänen hirmuisuutensa peljättäkö minua;"],[9,35,"Että minä puhuisin ja en pelkäisi häntä; sillä en minä mitään kanssani tiedä.","Että minä puhuisin ja en pelkäisi häntä; sillä en minä mitään kanssani tiedä."],[10,1,"Minun sieluni suuttuu elämästä; minun valitukseni minusta annan minä olla ja puhun sieluni murheessa.","Minun sieluni suuttuu elämästä; minun valitukseni minusta annan minä olla ja puhun sieluni murheessa."],[10,2,"Sanon Jumalalle: älä minua tuomitse: anna minun tietää, minkätähden sinä riitelet minun kanssani.","Sanon Jumalalle: älä minua tuomitse: anna minun tietää, minkätähden sinä riitelet minun kanssani."],[10,3,"Onko sinulla ilo siitä, ettäs väkivaltaa teet, ja hylkäät minun, joka käsialas olen, ja annat jumalattomain aivoitukset kunniaan tulla?","Onko sinulla ilo siitä, ettäs väkivaltaa teet, ja hylkäät minun, joka käsialas olen, ja annat jumalattomain aivoitukset kunniaan tulla?"],[10,4,"Onko sinulla lihalliset silmät? eli katsotkos niinkuin ihminen katsoo?","Onko sinulla lihalliset silmät? eli katsotkos niinkuin ihminen katsoo?"],[10,5,"Onko sinun päiväs niinkuin ihmisen päivät? eli vuotes niinkuin ihmisen vuodet?","Onko sinun päiväs niinkuin ihmisen päivät? eli vuotes niinkuin ihmisen vuodet?"],[10,6,"Ettäs kysyt minun vääryyttäni, ja tutkit pahaa tekoani,","Ettäs kysyt minun vääryyttäni, ja tutkit pahaa tekoani,"],[10,7,"Vaikka tiedät, etten minä ole jumalatoin; ehkei yhtään ole, joka taitaa sinun kädestäs vapauttaa.","Vaikka tiedät, etten minä ole jumalatoin; ehkei yhtään ole, joka taitaa sinun kädestäs vapauttaa."],[10,8,"Sinun kätes ovat minun valmistaneet ja tehneet minun kaikki ympäri, ja sinä tahdot hukuttaa minun?","Sinun kätes ovat minun valmistaneet ja tehneet minun kaikki ympäri, ja sinä tahdot hukuttaa minun?"],[10,9,"Muista siis, että olet minun tehnyt niinkuin saven, ja annat minun tulla maaksi jälleen.","Muista siis, että olet minun tehnyt niinkuin saven, ja annat minun tulla maaksi jälleen."],[10,10,"Etkös minua ole lypsänyt kuin rieskaa, ja antanut minun juosta niinkuin juustoa?","Etkös minua ole lypsänyt kuin rieskaa, ja antanut minun juosta niinkuin juustoa?"],[10,11,"Sinä olet minun puettanut nahalla ja lihalla: luilla ja suonilla olet sinä minun peittänyt.","Sinä olet minun puettanut nahalla ja lihalla: luilla ja suonilla olet sinä minun peittänyt."],[10,12,"Elämän ja hyvän työn olet sinä minulle osoittanut, ja sinun katsomises minun henkeni kätkee.","Elämän ja hyvän työn olet sinä minulle osoittanut, ja sinun katsomises minun henkeni kätkee."],[10,13,"Ja vaikka sinä nämät salaat sydämessäs, niin minä tiedän sen kuitenkin, ettäs sen muistat,","Ja vaikka sinä nämät salaat sydämessäs, niin minä tiedän sen kuitenkin, ettäs sen muistat,"],[10,14,"Jos minä pahaa teen, niin sinä kohta havaitset, ja et jätä minun pahaa tekoani rankaisemata.","Jos minä pahaa teen, niin sinä kohta havaitset, ja et jätä minun pahaa tekoani rankaisemata."],[10,15,"Jos minä olen jumalatoin, voi minua! jos minä olen hurskas, niin en minä kuitenkaan uskalla nostaa ylös päätäni. Minä olen täynnä ylönkatsetta, katsos minun viheliäisyyttäni.","Jos minä olen jumalatoin, voi minua! jos minä olen hurskas, niin en minä kuitenkaan uskalla nostaa ylös päätäni. Minä olen täynnä ylönkatsetta, katsos minun viheliäisyyttäni."],[10,16,"Noustessa sinä ajat minua takaa niinkuin jalopeura, ja taas ihmeellisesti minun kanssani menettelet.","Noustessa sinä ajat minua takaa niinkuin jalopeura, ja taas ihmeellisesti minun kanssani menettelet."],[10,17,"Sinä uudistat todistukses minua vastaan, ja vihastut kovin minun päälleni. Minua vaivaa yksi toisensa jälkeen niinkuin sota.","Sinä uudistat todistukses minua vastaan, ja vihastut kovin minun päälleni. Minua vaivaa yksi toisensa jälkeen niinkuin sota."],[10,18,"Miksis minun annoit lähteä äitini kohdusta? jospa minä olisin kuollut, ettei yksikään silmä olisi minua nähnyt!","Miksis minun annoit lähteä äitini kohdusta? jospa minä olisin kuollut, ettei yksikään silmä olisi minua nähnyt!"],[10,19,"Niin minä olisin kuin en olisikaan ollut, kannettu äitini kohdusta hautaan.","Niin minä olisin kuin en olisikaan ollut, kannettu äitini kohdusta hautaan."],[10,20,"Eikö minun ikäni lyhyt ole? Lakkaa ja päästä minua, ja luovu minusta, että minä vähänkin virvoitusta saisin,","Eikö minun ikäni lyhyt ole? Lakkaa ja päästä minua, ja luovu minusta, että minä vähänkin virvoitusta saisin,"],[10,21,"Ennenkuin minä menen, enkä palaja, pimeyden ja kuolon varjon maalle,","Ennenkuin minä menen, enkä palaja, pimeyden ja kuolon varjon maalle,"],[10,22,"Joka on pimeyden maa ja synkiä kuolon varjo, jossa ei yhtään järjestystä ole, joka paisteessansa on niinkuin synkeys.","Joka on pimeyden maa ja synkiä kuolon varjo, jossa ei yhtään järjestystä ole, joka paisteessansa on niinkuin synkeys."],[11,1,"Niin vastasi Zophar Naemasta ja sanoi:","Niin vastasi Zophar Naemasta ja sanoi:"],[11,2,"Kuin joku on kauvan puhunut, eikö häntä pitäis vastattaman? eli pitääkö suupaltilla oikeus oleman?","Kuin joku on kauvan puhunut, eikö häntä pitäis vastattaman? eli pitääkö suupaltilla oikeus oleman?"],[11,3,"Pitääkö sinun jaarituksiis ihmisten vaikeneman, että sinä pilkkaat, eikä yksikäan sinua häpäisisi?","Pitääkö sinun jaarituksiis ihmisten vaikeneman, että sinä pilkkaat, eikä yksikäan sinua häpäisisi?"],[11,4,"Sinä sanot: minun opetukseni on selkiä, ja minä olen puhdas sinun silmäis edessä.","Sinä sanot: minun opetukseni on selkiä, ja minä olen puhdas sinun silmäis edessä."],[11,5,"Jospa Jumala puhuis ja avais huulensa sinua vastaan,","Jospa Jumala puhuis ja avais huulensa sinua vastaan,"],[11,6,"Ja ilmoittais sinulle salaisen tiedon! sillä hänellä olis vielä enempi tekemistä, ettäs tietäisit, ettei hän muistele kaikkia sinun pahoja töitäs.","Ja ilmoittais sinulle salaisen tiedon! sillä hänellä olis vielä enempi tekemistä, ettäs tietäisit, ettei hän muistele kaikkia sinun pahoja töitäs."],[11,7,"Luuletkos tutkistellessas Jumalan löytäväs? ja Kaikkivaltiaan täydellisesti löytäväs.","Luuletkos tutkistellessas Jumalan löytäväs? ja Kaikkivaltiaan täydellisesti löytäväs."],[11,8,"Hän on korkiampi kuin taivas, mitäs tahdot tehdä? syvempi kuin helvetti, kuinkas taidat tuta?","Hän on korkiampi kuin taivas, mitäs tahdot tehdä? syvempi kuin helvetti, kuinkas taidat tuta?"],[11,9,"Pitempi kuin maa, ja laviampi kuin meri.","Pitempi kuin maa, ja laviampi kuin meri."],[11,10,"Jos hän sen ylösalaisin kääntäis, eli kätkis, eli heittäis kokoon; kuka hänen estäis?","Jos hän sen ylösalaisin kääntäis, eli kätkis, eli heittäis kokoon; kuka hänen estäis?"],[11,11,"Sillä hän tuntee turhatkin ihmiset, ja näkee vääryydet; ja ei hänen pitäis ymmärtämän?","Sillä hän tuntee turhatkin ihmiset, ja näkee vääryydet; ja ei hänen pitäis ymmärtämän?"],[11,12,"Turha ihminen ylpeilee, ja syntynyt ihminen on niinkuin metsä-aasin varsa.","Turha ihminen ylpeilee, ja syntynyt ihminen on niinkuin metsä-aasin varsa."],[11,13,"Jos olisit valmistanut sydämes, ja nostanut kätes hänen tykönsä;","Jos olisit valmistanut sydämes, ja nostanut kätes hänen tykönsä;"],[11,14,"Jos vääryys on sinun kädessäs, niin heitä se kauvas, ettei yhtään vääryyttä asuisi majassas:","Jos vääryys on sinun kädessäs, niin heitä se kauvas, ettei yhtään vääryyttä asuisi majassas:"],[11,15,"Niin sinä ylennät kasvos ilman laitosta, ja olet vahva ja ei pelkääväinen.","Niin sinä ylennät kasvos ilman laitosta, ja olet vahva ja ei pelkääväinen."],[11,16,"Niin sinä myös unhotat vaivan; ja niinkuin ohitse juossut vesi, tulee se mielees.","Niin sinä myös unhotat vaivan; ja niinkuin ohitse juossut vesi, tulee se mielees."],[11,17,"Ja sinun elämäs aika pitää käymän ylös niinkuin puolipäivä, ja pimeys niinkuin kirkas aamu.","Ja sinun elämäs aika pitää käymän ylös niinkuin puolipäivä, ja pimeys niinkuin kirkas aamu."],[11,18,"Ole hyvässä turvassa, vielä nyt toivo on; sillä vaikkas nyt olet häpiässä, niin sinä kuitenkin olet rauhassa lepäävä.","Ole hyvässä turvassa, vielä nyt toivo on; sillä vaikkas nyt olet häpiässä, niin sinä kuitenkin olet rauhassa lepäävä."],[11,19,"Sinä olet makaava, ja ei kenkään sinua peljätä: monen pitää sinua kunnioittaman.","Sinä olet makaava, ja ei kenkään sinua peljätä: monen pitää sinua kunnioittaman."],[11,20,"Mutta jumalattomain silmät pitää nääntymän, ja ei voi päästää; sillä heidän toivonsa pitää puuttuman heidän sieluiltansa.","Mutta jumalattomain silmät pitää nääntymän, ja ei voi päästää; sillä heidän toivonsa pitää puuttuman heidän sieluiltansa."],[12,1,"Niin vastasi Job ja sanoi:","Niin vastasi Job ja sanoi:"],[12,2,"Te olette miehet; taito kuolee teidän kanssanne.","Te olette miehet; taito kuolee teidän kanssanne."],[12,3,"Minulla on niin sydän kuin teilläkin, enkä ole alemmaisempi teitä: kuka se on, joka ei näitä tiedä?","Minulla on niin sydän kuin teilläkin, enkä ole alemmaisempi teitä: kuka se on, joka ei näitä tiedä?"],[12,4,"Joka lähimmäiseltänsä pilkataan, niinkuin minä, hän rukoilee Jumalaa, ja hän kuulee häntä: hurskas ja vakaa pilkataan.","Joka lähimmäiseltänsä pilkataan, niinkuin minä, hän rukoilee Jumalaa, ja hän kuulee häntä: hurskas ja vakaa pilkataan."],[12,5,"Hän on ylönkatsottu kynttiläinen ylpeiden ajatuksissa, valmistettu, että he siihen loukkaavat jalkansa,","Hän on ylönkatsottu kynttiläinen ylpeiden ajatuksissa, valmistettu, että he siihen loukkaavat jalkansa,"],[12,6,"Ryövärein majoissa on kyllä, ja he härsyttelevät rohkiasti Jumalaa, ehkä Jumala on sen antanut heidän käteensä.","Ryövärein majoissa on kyllä, ja he härsyttelevät rohkiasti Jumalaa, ehkä Jumala on sen antanut heidän käteensä."],[12,7,"Kysy siis eläimiltä, ja he opettavat sinua, ja taivaan linnuilta, ja he sanovat sinulle.","Kysy siis eläimiltä, ja he opettavat sinua, ja taivaan linnuilta, ja he sanovat sinulle."],[12,8,"Taikka puhu maan kanssa, ja hän opettaa sinua; ja kalat meressä ilmoittavat sinulle.","Taikka puhu maan kanssa, ja hän opettaa sinua; ja kalat meressä ilmoittavat sinulle."],[12,9,"Kuka se on, joka ei kaikkia näitä tiedä, että Herran käsi on ne tehnyt?","Kuka se on, joka ei kaikkia näitä tiedä, että Herran käsi on ne tehnyt?"],[12,10,"Että hänen kädessänsä on kaikkein elävien sielu, ja kunkin lihan henki?","Että hänen kädessänsä on kaikkein elävien sielu, ja kunkin lihan henki?"],[12,11,"Eikö korva koettele puhetta, ja suu maista ruokaa?","Eikö korva koettele puhetta, ja suu maista ruokaa?"],[12,12,"Vanhoilla on taito, ja pitkä-ijällisillä ymmärrys.","Vanhoilla on taito, ja pitkä-ijällisillä ymmärrys."],[12,13,"Hänen tykönänsä on taito ja voima; hänen on neuvo ja ymmärrys.","Hänen tykönänsä on taito ja voima; hänen on neuvo ja ymmärrys."],[12,14,"Katso, koska hän kukistaa, niin ei auta rakentamaan: koska hän jonkun salpaa, niin ei kenkään taida avata.","Katso, koska hän kukistaa, niin ei auta rakentamaan: koska hän jonkun salpaa, niin ei kenkään taida avata."],[12,15,"Katso, koska hän pidättää veden, niin kaikki kuivettuu, ja koska hän laskee, niin se kääntää maan.","Katso, koska hän pidättää veden, niin kaikki kuivettuu, ja koska hän laskee, niin se kääntää maan."],[12,16,"Hän on vahva Ja pysyväinen: hänen on se joka eksyy, ja se joka eksyttää.","Hän on vahva Ja pysyväinen: hänen on se joka eksyy, ja se joka eksyttää."],[12,17,"Hän johdattaa kavalat niinkuin saaliin, ja saattaa tuomarit tyhmäksi.","Hän johdattaa kavalat niinkuin saaliin, ja saattaa tuomarit tyhmäksi."],[12,18,"Hän päästää kuningasten siteet, ja vyöttää heidän kupeensa.","Hän päästää kuningasten siteet, ja vyöttää heidän kupeensa."],[12,19,"Papit vie hän niinkuin saaliin, ja väkevät kukistaa.","Papit vie hän niinkuin saaliin, ja väkevät kukistaa."],[12,20,"Hän vääntää pois totisten huulet, vanhain toimen ottaa hän pois.","Hän vääntää pois totisten huulet, vanhain toimen ottaa hän pois."],[12,21,"Hän kaataa ylönkatseen päämiesten päälle, ja voimallisten väkevyyden hajoittaa.","Hän kaataa ylönkatseen päämiesten päälle, ja voimallisten väkevyyden hajoittaa."],[12,22,"Hän ilmoittaa pimiät perustukset, ja kuoleman varjon saattaa hän valkeuteen.","Hän ilmoittaa pimiät perustukset, ja kuoleman varjon saattaa hän valkeuteen."],[12,23,"Hän saattaa kansat suureksi, ja taas hukuttaa heidät; hän levittää kansan, ja taas vie pois heidät.","Hän saattaa kansat suureksi, ja taas hukuttaa heidät; hän levittää kansan, ja taas vie pois heidät."],[12,24,"Hän ottaa pois maan kansan ruhtinasten sydämet, ja eksyttää heitä korvessa, jossa ei tietä ole.","Hän ottaa pois maan kansan ruhtinasten sydämet, ja eksyttää heitä korvessa, jossa ei tietä ole."],[12,25,"Ja he koperoitsevat pimeydessä ilman valkeutta; ja hän eksyttää heitä kuin juopuneita.","Ja he koperoitsevat pimeydessä ilman valkeutta; ja hän eksyttää heitä kuin juopuneita."],[13,1,"Katso, kaikkia näitä ovat silmäni nähneet, ja korvani kuulleet, ja on ne ymmärtänyt.","Katso, kaikkia näitä ovat silmäni nähneet, ja korvani kuulleet, ja on ne ymmärtänyt."],[13,2,"Jota te tiedätte, sitä minäkin tiedän, enkä ole halvempi teitä.","Jota te tiedätte, sitä minäkin tiedän, enkä ole halvempi teitä."],[13,3,"Minä puhun siis Kaikkivaltiaan tykö, ja mielin kamppailla Jumalan kanssa.","Minä puhun siis Kaikkivaltiaan tykö, ja mielin kamppailla Jumalan kanssa."],[13,4,"Sillä te olette valheen saarnaajat, ja kaikki kelvottomat lääkärit.","Sillä te olette valheen saarnaajat, ja kaikki kelvottomat lääkärit."],[13,5,"Jospa te voisitte juuri ääneti olla, niin te olisitte taitavat.","Jospa te voisitte juuri ääneti olla, niin te olisitte taitavat."],[13,6,"Kuulkaat siis minun kamppaustani, ja ottakaat vaari asiasta, kuin minä puhun.","Kuulkaat siis minun kamppaustani, ja ottakaat vaari asiasta, kuin minä puhun."],[13,7,"Tahdotteko te Jumalan puolesta vastata vääryydellä? ja hänen puolestansa puhua petosta?","Tahdotteko te Jumalan puolesta vastata vääryydellä? ja hänen puolestansa puhua petosta?"],[13,8,"Tahdotteko te katsoa hänen mieltänsä? Tahdotteko te riidellä Jumalan puolesta?","Tahdotteko te katsoa hänen mieltänsä? Tahdotteko te riidellä Jumalan puolesta?"],[13,9,"Pitääkö se teille menestymän, koska hän teitä etsii? luuletteko te hänen pettävänne, niinkuin joku pettää ihmisen?","Pitääkö se teille menestymän, koska hän teitä etsii? luuletteko te hänen pettävänne, niinkuin joku pettää ihmisen?"],[13,10,"Hän kovin nuhtelee teitä, jos te salaisesti mieliä katsotte.","Hän kovin nuhtelee teitä, jos te salaisesti mieliä katsotte."],[13,11,"Eikö hänen korkeutensa teitä peljätä? ja hänen pelkonsa lankee teidän päällenne?","Eikö hänen korkeutensa teitä peljätä? ja hänen pelkonsa lankee teidän päällenne?"],[13,12,"Teidän muistonne vedetään tuhan verraksi, ja teidän selkänne pitää oleman niinkuin saviroukkio.","Teidän muistonne vedetään tuhan verraksi, ja teidän selkänne pitää oleman niinkuin saviroukkio."],[13,13,"Olkaat ääneti minun edessäni, minä puhun, tapahtukoon minulle mitä hyvänsä.","Olkaat ääneti minun edessäni, minä puhun, tapahtukoon minulle mitä hyvänsä."],[13,14,"Miksi minun pitää pureman lihaani hampaillani, ja asettaman sieluni minun käsiini?","Miksi minun pitää pureman lihaani hampaillani, ja asettaman sieluni minun käsiini?"],[13,15,"Katso, vaikka hän minun tappais, enkö minä vielä sittenkin toivoisi? kuitenkin minä nuhtelen teitäni hänen edessänsä.","Katso, vaikka hän minun tappais, enkö minä vielä sittenkin toivoisi? kuitenkin minä nuhtelen teitäni hänen edessänsä."],[13,16,"Hän on kuitenkin minun autuuteni; sillä ei yksikään ulkokullattu tule hänen eteensä.","Hän on kuitenkin minun autuuteni; sillä ei yksikään ulkokullattu tule hänen eteensä."],[13,17,"Kuulkaat juuri visusti minun puhettani, ja minun selitystäni teidän korvainne edessä.","Kuulkaat juuri visusti minun puhettani, ja minun selitystäni teidän korvainne edessä."],[13,18,"Katso, jo minä olen tuomion sanonut: Minä tiedän, että minä olen hurskas.","Katso, jo minä olen tuomion sanonut: Minä tiedän, että minä olen hurskas."],[13,19,"Kuka tahtoo käydä oikeudelle minun kanssani? Mutta minun täytyy nyt ääneti olla, ja loppua.","Kuka tahtoo käydä oikeudelle minun kanssani? Mutta minun täytyy nyt ääneti olla, ja loppua."],[13,20,"Ainoastaan älä tee minulle kahta, niin en minä kätke itsiäni sinun edestäs.","Ainoastaan älä tee minulle kahta, niin en minä kätke itsiäni sinun edestäs."],[13,21,"Anna kätes olla kaukana minusta, ja sinun kauhistukses älköön minua peljättäkö.","Anna kätes olla kaukana minusta, ja sinun kauhistukses älköön minua peljättäkö."],[13,22,"Kutsu minua, ja minä vastaan: eli minä puhun, ja vastaa sinä minua.","Kutsu minua, ja minä vastaan: eli minä puhun, ja vastaa sinä minua."],[13,23,"Kuinka usiat ovat minun vääryyteni ja pahat tekoni? anna minun saada tietää minun syntini ja rikokseni.","Kuinka usiat ovat minun vääryyteni ja pahat tekoni? anna minun saada tietää minun syntini ja rikokseni."],[13,24,"Miksi sinä peität kasvos, ja pidät minua vihollisena?","Miksi sinä peität kasvos, ja pidät minua vihollisena?"],[13,25,"Tahdotkos niin kova olla lentävää lehteä vastaan, ja vainota kuivaa oljen kortta?","Tahdotkos niin kova olla lentävää lehteä vastaan, ja vainota kuivaa oljen kortta?"],[13,26,"Sillä sinä kirjoitat minulle murhetta, ja annat minun periä nuoruuteni syntejä.","Sillä sinä kirjoitat minulle murhetta, ja annat minun periä nuoruuteni syntejä."],[13,27,"Sinä olet pannut minun jalkani jalkapuuhun, ja otat kaikista minun poluistani vaarin, ja katsot kaikkia minun askeleitani;","Sinä olet pannut minun jalkani jalkapuuhun, ja otat kaikista minun poluistani vaarin, ja katsot kaikkia minun askeleitani;"],[13,28,"Joka kuitenkin hukun niinkuin mädännyt raato, ja niinkuin koilta syöty vaate.","Joka kuitenkin hukun niinkuin mädännyt raato, ja niinkuin koilta syöty vaate."],[14,1,"Ihminen, vaimosta syntynyt, elää vähän aikaa, ja on täynnä levottomuutta,","Ihminen, vaimosta syntynyt, elää vähän aikaa, ja on täynnä levottomuutta,"],[14,2,"Kasvaa niinkuin kukkanen, ja kaatuu; pakenee niinkuin varjo, ja ei pysy.","Kasvaa niinkuin kukkanen, ja kaatuu; pakenee niinkuin varjo, ja ei pysy."],[14,3,"Ja senkaltaisen päälle sinä avaat silmäs, ja vedät minun kanssasi oikeuden eteen.","Ja senkaltaisen päälle sinä avaat silmäs, ja vedät minun kanssasi oikeuden eteen."],[14,4,"Kuka löytää puhtaan niiden seassa, kussa ei puhdasta ole?","Kuka löytää puhtaan niiden seassa, kussa ei puhdasta ole?"],[14,5,"Hänellä on määrätty aika, hänen kuukauttensa luku on sinun tykönäs: sinä olet määrän asettanut hänen eteensä, jota ei hän taida käydä ylitse.","Hänellä on määrätty aika, hänen kuukauttensa luku on sinun tykönäs: sinä olet määrän asettanut hänen eteensä, jota ei hän taida käydä ylitse."],[14,6,"Luovu hänestä, että hän sais levätä, niinkauvan kuin hänen aikansa tulee, jota hän odottaa niinkuin palkollinen.","Luovu hänestä, että hän sais levätä, niinkauvan kuin hänen aikansa tulee, jota hän odottaa niinkuin palkollinen."],[14,7,"Puulla on toivo, ehkä se hakattaisiin, että se uudistetaan, ja sen vesat kasvavat jälleen:","Puulla on toivo, ehkä se hakattaisiin, että se uudistetaan, ja sen vesat kasvavat jälleen:"],[14,8,"Ehkä sen juuret vanhenevat maassa, ja kanto mätänee mullassa,","Ehkä sen juuret vanhenevat maassa, ja kanto mätänee mullassa,"],[14,9,"Kuitenkin se versoo jälleen veden märkyydestä, ja kasvaa niinkuin se istutettu olis.","Kuitenkin se versoo jälleen veden märkyydestä, ja kasvaa niinkuin se istutettu olis."],[14,10,"Mutta kussa ihminen on, koska hän kuollut, hukkunut ja pois on?","Mutta kussa ihminen on, koska hän kuollut, hukkunut ja pois on?"],[14,11,"Niinkuin vesi juoksee ulos merestä, ja oja kureentuu ja kuivettuu,","Niinkuin vesi juoksee ulos merestä, ja oja kureentuu ja kuivettuu,"],[14,12,"Niin on ihminen, kuin hän kuollut on, ei hän nouse: niinkauvan kuin taivas pysyy, ei he virkoo eikä herää unestansa.","Niin on ihminen, kuin hän kuollut on, ei hän nouse: niinkauvan kuin taivas pysyy, ei he virkoo eikä herää unestansa."],[14,13,"O jospa sinä minun hautaan kätkisit ja peittäisit minun, niinkauvan kuin vihas menis pois, ja asettaisit minulle määrän muistaakses minua.","O jospa sinä minun hautaan kätkisit ja peittäisit minun, niinkauvan kuin vihas menis pois, ja asettaisit minulle määrän muistaakses minua."],[14,14,"Luuletkos kuolleen ihmisen tulevan eläväksi jälleen? Minä odotan joka päivä niinkauvan kuin minä sodin, siihenasti että minun muutteeni tulee,","Luuletkos kuolleen ihmisen tulevan eläväksi jälleen? Minä odotan joka päivä niinkauvan kuin minä sodin, siihenasti että minun muutteeni tulee,"],[14,15,"Että sinä kutsuisit minua, ja minä vastaisin sinua, ja ettes hylkäisi käsialaas;","Että sinä kutsuisit minua, ja minä vastaisin sinua, ja ettes hylkäisi käsialaas;"],[14,16,"Sillä sinä olet jo lukenut kaikki minun askeleeni: etkös ota vaaria minun synneistäni?","Sillä sinä olet jo lukenut kaikki minun askeleeni: etkös ota vaaria minun synneistäni?"],[14,17,"Minun rikokseni olet sinä lukinnut lyhteesen, ja pannut kokoon minun vääryyteni.","Minun rikokseni olet sinä lukinnut lyhteesen, ja pannut kokoon minun vääryyteni."],[14,18,"Jos tosin vuori kaatuu ja katoo, ja vaha siirtyy sialtansa,","Jos tosin vuori kaatuu ja katoo, ja vaha siirtyy sialtansa,"],[14,19,"Vesi kuluttaa kivet, ja virta vie maan pois, ja mitä sen päällä itse kasvaa: niin sinä myös ihmisen toivon kadotat.","Vesi kuluttaa kivet, ja virta vie maan pois, ja mitä sen päällä itse kasvaa: niin sinä myös ihmisen toivon kadotat."],[14,20,"Sinä olet häntä voimallisempi ijankaikkisesti, ja hänen täytyy mennä pois. Sinä muutat hänen kasvonsa, ja annat hänen mennä.","Sinä olet häntä voimallisempi ijankaikkisesti, ja hänen täytyy mennä pois. Sinä muutat hänen kasvonsa, ja annat hänen mennä."],[14,21,"Ovatko hänen lapsensa kunnniassa, sitä ei hän tiedä, taikka ovatko he ylönkatseessa, sitä ei hän ymmärrä.","Ovatko hänen lapsensa kunnniassa, sitä ei hän tiedä, taikka ovatko he ylönkatseessa, sitä ei hän ymmärrä."],[14,22,"Kuitenkin niinkauvan kuin hän kantaa lihaa, täytyy hänen olla vaivassa, ja niinkauvan kuin hänen sielunsa on hänessä, täytyy hänen murhetta kärsiä.","Kuitenkin niinkauvan kuin hän kantaa lihaa, täytyy hänen olla vaivassa, ja niinkauvan kuin hänen sielunsa on hänessä, täytyy hänen murhetta kärsiä."],[15,1,"Niin vastasi Eliphas Temanilainen ja sanoi:","Niin vastasi Eliphas Temanilainen ja sanoi:"],[15,2,"Pitääkö taitavan niin tuuleen puhuman, ja täyttämän vatsansa tuulella?","Pitääkö taitavan niin tuuleen puhuman, ja täyttämän vatsansa tuulella?"],[15,3,"Sinä nuhtelet kelvottomilla sanoilla ja puheilla, joista ei ole hyödytystä.","Sinä nuhtelet kelvottomilla sanoilla ja puheilla, joista ei ole hyödytystä."],[15,4,"Sinä olet hyljännyt pelvon, ja puhut ylönkatseella Jumalan edessä.","Sinä olet hyljännyt pelvon, ja puhut ylönkatseella Jumalan edessä."],[15,5,"Sillä sinun pahuutes opettaa niin sinun suus; ja sinä olet valinnut viekasten kielen.","Sillä sinun pahuutes opettaa niin sinun suus; ja sinä olet valinnut viekasten kielen."],[15,6,"Sinun suus pitää tuomitseman sinun, ja en minä: sinun huules pitää todistaman sinua vastaan:","Sinun suus pitää tuomitseman sinun, ja en minä: sinun huules pitää todistaman sinua vastaan:"],[15,7,"Oletkos ensimäinen ihminen, joka syntynyt on? eli ennen (kaikkia) vuoria luotu?","Oletkos ensimäinen ihminen, joka syntynyt on? eli ennen (kaikkia) vuoria luotu?"],[15,8,"Oletko sinä kuullut Jumalan salaisen neuvon? ja onko taito halvempi sinua?","Oletko sinä kuullut Jumalan salaisen neuvon? ja onko taito halvempi sinua?"],[15,9,"Mitä sinä tiedät, jota emme tiedä; mitäs ymmärrät, joka ei ole meidän tykönämme?","Mitä sinä tiedät, jota emme tiedä; mitäs ymmärrät, joka ei ole meidän tykönämme?"],[15,10,"Harmaapäät ja vanhat ovat meidän tykönämme, jotka ennen ovat eläneet kuin sinun isäs.","Harmaapäät ja vanhat ovat meidän tykönämme, jotka ennen ovat eläneet kuin sinun isäs."],[15,11,"Pitäiskö Jumalan lohdutukset oleman halvat sinulle? Eli onko jotakin salaista tykönäs?","Pitäiskö Jumalan lohdutukset oleman halvat sinulle? Eli onko jotakin salaista tykönäs?"],[15,12,"Mitä sinun sydämes aikoi? ja mitäs vilkutat silmiäs?","Mitä sinun sydämes aikoi? ja mitäs vilkutat silmiäs?"],[15,13,"Kuinka sinä asetat mieles Jumalaa vastaan? että sinä senkaltaiset sanat suustas päästät.","Kuinka sinä asetat mieles Jumalaa vastaan? että sinä senkaltaiset sanat suustas päästät."],[15,14,"Mikä on ihminen, että hän olis puhdas? ja että hän olis hurskas, joka vaimosta syntynyt on?","Mikä on ihminen, että hän olis puhdas? ja että hän olis hurskas, joka vaimosta syntynyt on?"],[15,15,"Katso, hänen pyhäinsä seassa ei ole yhtään nuhteetointa; ja taivaat ei ole puhtaat hänen edessänsä.","Katso, hänen pyhäinsä seassa ei ole yhtään nuhteetointa; ja taivaat ei ole puhtaat hänen edessänsä."],[15,16,"Kuinka paljon enemmin ihminen on kauhia ja ilkiä, joka juo vääryyttä niinkuin vettä?","Kuinka paljon enemmin ihminen on kauhia ja ilkiä, joka juo vääryyttä niinkuin vettä?"],[15,17,"Minä osoitan sinulle sen, kuule minua: minä luettelen sinulle, mitä minä nähnyt olen:","Minä osoitan sinulle sen, kuule minua: minä luettelen sinulle, mitä minä nähnyt olen:"],[15,18,"Mitä taitavat sanoneet ovat, jota ei yksikään heidän isistänsä ole salannut.","Mitä taitavat sanoneet ovat, jota ei yksikään heidän isistänsä ole salannut."],[15,19,"Joille ainoille maa annettu on, niin ettei yksikään outo saanut käydä heidän keskellänsä.","Joille ainoille maa annettu on, niin ettei yksikään outo saanut käydä heidän keskellänsä."],[15,20,"Jumalatoin vapisee kaiken elinaikansa, ja tyrannin vuosiluku on peitetty.","Jumalatoin vapisee kaiken elinaikansa, ja tyrannin vuosiluku on peitetty."],[15,21,"Pelvon ääni on hänen korvissansa, että rauhassakin pitää hävittäjä tuleman hänen päällensä.","Pelvon ääni on hänen korvissansa, että rauhassakin pitää hävittäjä tuleman hänen päällensä."],[15,22,"Ei hän usko palajavansa pimeydestä, ja varoo aina miekkaa.","Ei hän usko palajavansa pimeydestä, ja varoo aina miekkaa."],[15,23,"Kuin hän lähtee sinne ja tänne elatuksensa jälkeen, niin hän luulee aina pimeyden päivän käsissänsä olevan.","Kuin hän lähtee sinne ja tänne elatuksensa jälkeen, niin hän luulee aina pimeyden päivän käsissänsä olevan."],[15,24,"Ahdistus ja hätä peljättävät häntä, ja yllyttävät hänen, niinkuin kuningas valmis sotaan.","Ahdistus ja hätä peljättävät häntä, ja yllyttävät hänen, niinkuin kuningas valmis sotaan."],[15,25,"Sillä hän on ojentanut kätensä Jumalaa vastaan, ja vahvistanut itsensä Kaikkivaltiasta vastaan.","Sillä hän on ojentanut kätensä Jumalaa vastaan, ja vahvistanut itsensä Kaikkivaltiasta vastaan."],[15,26,"Hän juoksee päätäpäin häntä vastaan, ja seisoo ynseästi häntä vastaan.","Hän juoksee päätäpäin häntä vastaan, ja seisoo ynseästi häntä vastaan."],[15,27,"Hän on peittänyt kasvonsa lihavuudellansa, ja lihoittanut ja paisuttanut itsensä.","Hän on peittänyt kasvonsa lihavuudellansa, ja lihoittanut ja paisuttanut itsensä."],[15,28,"Mutta hänen pitää asuman hävitetyssä kaupungissa ja asumattomissa huoneissa, jotka roukkioksi riutumallansa ovat.","Mutta hänen pitää asuman hävitetyssä kaupungissa ja asumattomissa huoneissa, jotka roukkioksi riutumallansa ovat."],[15,29,"Ei hänen pidä rikastuman, eikä hänen tavaransa pysymän, eikä hänen onnensa pidä leviämän maassa.","Ei hänen pidä rikastuman, eikä hänen tavaransa pysymän, eikä hänen onnensa pidä leviämän maassa."],[15,30,"Ei hänen pidä pääsemän pimeydestä: tulen liekki kuivaa hänen oksansa, ja hänen suunsa hengellä katoo.","Ei hänen pidä pääsemän pimeydestä: tulen liekki kuivaa hänen oksansa, ja hänen suunsa hengellä katoo."],[15,31,"Ei hän taida uskaltaa turhuuteen, että hän on petetty; sillä turhuus on hänen palkkansa.","Ei hän taida uskaltaa turhuuteen, että hän on petetty; sillä turhuus on hänen palkkansa."],[15,32,"Hän loppuu ennen aikaansa, ja hänen oksansa ei pidä vihoittaman.","Hän loppuu ennen aikaansa, ja hänen oksansa ei pidä vihoittaman."],[15,33,"Hän poimitaan niinkuin kypsymätöin marja viinapuusta, ja niinkuin öljypuu varistaa kukoistuksensa.","Hän poimitaan niinkuin kypsymätöin marja viinapuusta, ja niinkuin öljypuu varistaa kukoistuksensa."],[15,34,"Sillä ulkokullattuin kokous pitää oleman yksinäinen, ja tulen pitää polttaman lahjain ottajan huoneen,","Sillä ulkokullattuin kokous pitää oleman yksinäinen, ja tulen pitää polttaman lahjain ottajan huoneen,"],[15,35,"Hän siittää onnettomuuden, ja synnyttää vaivaisuuden; ja heidän vatsansa valmistaa petoksen.","Hän siittää onnettomuuden, ja synnyttää vaivaisuuden; ja heidän vatsansa valmistaa petoksen."],[16,1,"Sitte vastasi Job ja sanoi:","Sitte vastasi Job ja sanoi:"],[16,2,"Minä olen usein senkaltaista kuullut: te olette kaikki häijyt lohduttajat.","Minä olen usein senkaltaista kuullut: te olette kaikki häijyt lohduttajat."],[16,3,"Koska siis nämät tyhjät puheet loppuvat? eli mikä sinun niin rohkaisee puhumaan?","Koska siis nämät tyhjät puheet loppuvat? eli mikä sinun niin rohkaisee puhumaan?"],[16,4,"Minä taitaisin myös puhua niinkuin tekin. Minä soisin teidän sielunne olevan minun sieluni siassa, niin minä löytäisin myös sanoja teitä vastaan, ja taitaisin vääntää päätäni teitä vastaan.","Minä taitaisin myös puhua niinkuin tekin. Minä soisin teidän sielunne olevan minun sieluni siassa, niin minä löytäisin myös sanoja teitä vastaan, ja taitaisin vääntää päätäni teitä vastaan."],[16,5,"Minä tahtoisin vahvistaa teitä suullani, ja lohduttaa huulillani.","Minä tahtoisin vahvistaa teitä suullani, ja lohduttaa huulillani."],[16,6,"Mutta ehkä minä puhuisin, niin ei kuitenkaan minun vaivani lakkaa: jos minä vaikenen, niin ei se kuitenkaan mene minusta pois.","Mutta ehkä minä puhuisin, niin ei kuitenkaan minun vaivani lakkaa: jos minä vaikenen, niin ei se kuitenkaan mene minusta pois."],[16,7,"Mutta nyt hän saattaa minulle vaivaisuuden: sinä hävität koko minun seurani.","Mutta nyt hän saattaa minulle vaivaisuuden: sinä hävität koko minun seurani."],[16,8,"Sinä olet tehnyt minun ryppyiseksi, että olis todistus minua vastaan: minun laihuuteni nousee minua vastaan, ja sanoo minua vastaan.","Sinä olet tehnyt minun ryppyiseksi, että olis todistus minua vastaan: minun laihuuteni nousee minua vastaan, ja sanoo minua vastaan."],[16,9,"Hänen vihansa repäisee minun, ja joka minua vihaa, kiristelee hampaitansa minun päälleni; ja minun viholliseni silmät kiiluvat minun päälleni.","Hänen vihansa repäisee minun, ja joka minua vihaa, kiristelee hampaitansa minun päälleni; ja minun viholliseni silmät kiiluvat minun päälleni."],[16,10,"He ammottivat suunsa minua vastaan, ja ovat minua häpiällisesti poskelle piesseet: he ovat sammuttaneet vihansa minun päälleni.","He ammottivat suunsa minua vastaan, ja ovat minua häpiällisesti poskelle piesseet: he ovat sammuttaneet vihansa minun päälleni."],[16,11,"Jumala on minun hyljännyt väärille, ja antanut minun tulla jumalattomain käsiin.","Jumala on minun hyljännyt väärille, ja antanut minun tulla jumalattomain käsiin."],[16,12,"Minä olin rauhassa, vaan hän on minun murentanut, hän on tarttunut minun kaulaani, ja särkenyt minun, ja pannut minun hänellensä maaliksi.","Minä olin rauhassa, vaan hän on minun murentanut, hän on tarttunut minun kaulaani, ja särkenyt minun, ja pannut minun hänellensä maaliksi."],[16,13,"Hänen ampujansa ovat piirittäneet minun: hän on reväissyt minun munaskuuni, eikä säästänyt: hän on vuodattanut minun sappeni maan päälle:","Hänen ampujansa ovat piirittäneet minun: hän on reväissyt minun munaskuuni, eikä säästänyt: hän on vuodattanut minun sappeni maan päälle:"],[16,14,"Hän on haavoittanut minun yhdellä haavalla toisen perään: Hän karkasi minun päälleni niinkuin joku väkevä.","Hän on haavoittanut minun yhdellä haavalla toisen perään: Hän karkasi minun päälleni niinkuin joku väkevä."],[16,15,"Minä ompelin säkin minun nahkani päälle, ja laskin sarveni multaan.","Minä ompelin säkin minun nahkani päälle, ja laskin sarveni multaan."],[16,16,"Minun kasvoni ovat soaistut itkusta, ja silmälautani päällä on kuoleman varjo.","Minun kasvoni ovat soaistut itkusta, ja silmälautani päällä on kuoleman varjo."],[16,17,"Ehkei kuitenkaan minun kädessäni ole vääryys, ja minun rukoukseni on puhdas.","Ehkei kuitenkaan minun kädessäni ole vääryys, ja minun rukoukseni on puhdas."],[16,18,"Maa, älä peitä minun vertani, ja älkään olko minun huudolleni siaa.","Maa, älä peitä minun vertani, ja älkään olko minun huudolleni siaa."],[16,19,"Ja katso, minun todistajani on taivaassa, ja joka minun tuntee, on korkeudessa.","Ja katso, minun todistajani on taivaassa, ja joka minun tuntee, on korkeudessa."],[16,20,"Minun ystäväni ovat minun pilkkaajani; mutta minun silmäni vuodattavat kyyneliä Jumalan tykö,","Minun ystäväni ovat minun pilkkaajani; mutta minun silmäni vuodattavat kyyneliä Jumalan tykö,"],[16,21,"Joka ihmisen puolesta vastaa Jumalan tykönä, niinkuin ihmisen lapsi lähimmäisensä puolesta.","Joka ihmisen puolesta vastaa Jumalan tykönä, niinkuin ihmisen lapsi lähimmäisensä puolesta."],[16,22,"Mutta määrätyt vuodet ovat tulleet, ja minä menen sitä tietä pois, jota en minä jälleen palaja.","Mutta määrätyt vuodet ovat tulleet, ja minä menen sitä tietä pois, jota en minä jälleen palaja."],[17,1,"Minun henkeni on heikko, minun päiväni ovat lyhetyt, ja hauta on käsissä.","Minun henkeni on heikko, minun päiväni ovat lyhetyt, ja hauta on käsissä."],[17,2,"En minä ketäkään pettänyt, ja kuitenkin minun silmäni täytyy olla murheessa.","En minä ketäkään pettänyt, ja kuitenkin minun silmäni täytyy olla murheessa."],[17,3,"Nyt siis taivuta sinus, ja ole itse minun takaukseni! kukas muu olis, joka minua takais?","Nyt siis taivuta sinus, ja ole itse minun takaukseni! kukas muu olis, joka minua takais?"],[17,4,"Ymmärryksen olet sinä heidän sydämistänsä kätkenyt, sentähden et sinä korota heitä.","Ymmärryksen olet sinä heidän sydämistänsä kätkenyt, sentähden et sinä korota heitä."],[17,5,"Hän kerskaa ystävillensä saaliistansa, mutta hänen lastensa silmät pitää vaipuman.","Hän kerskaa ystävillensä saaliistansa, mutta hänen lastensa silmät pitää vaipuman."],[17,6,"Hän on minun pannut sananlaskuksi kansain sekaan, ja ääniksi heidän keskellensä.","Hän on minun pannut sananlaskuksi kansain sekaan, ja ääniksi heidän keskellensä."],[17,7,"Minun silmäni ovat pimenneet minun suruni tähden, ja kaikki minun jäseneni ovat niinkuin varjo.","Minun silmäni ovat pimenneet minun suruni tähden, ja kaikki minun jäseneni ovat niinkuin varjo."],[17,8,"Tästä hurskaat hämmästyvät, ja viattomat asettavat heitänsä ulkokullatuita vastaan.","Tästä hurskaat hämmästyvät, ja viattomat asettavat heitänsä ulkokullatuita vastaan."],[17,9,"Hurskas pysyy tielIänsä: ja jolla on puhtaat kädet, se pysyy vahvana.","Hurskas pysyy tielIänsä: ja jolla on puhtaat kädet, se pysyy vahvana."],[17,10,"Kääntäkäät siis teitänne kaikki ja tulkaat nyt: en minä kuitenkaan löydä yhtään taitavaa teidän seassanne.","Kääntäkäät siis teitänne kaikki ja tulkaat nyt: en minä kuitenkaan löydä yhtään taitavaa teidän seassanne."],[17,11,"Minun päiväni ovat kuluneet: minun aivoitukseni ovat hajoitetut, jotka minun sydämessäni olivat,","Minun päiväni ovat kuluneet: minun aivoitukseni ovat hajoitetut, jotka minun sydämessäni olivat,"],[17,12,"Ja ovat yöstä päivän, ja valkeuden pimeydestä tehneet.","Ja ovat yöstä päivän, ja valkeuden pimeydestä tehneet."],[17,13,"Ja ehkä minä kauvan odottaisin, niin on kuitenkin hauta minun huoneeni, ja minä olen vuoteeni pimeydessä tehnyt.","Ja ehkä minä kauvan odottaisin, niin on kuitenkin hauta minun huoneeni, ja minä olen vuoteeni pimeydessä tehnyt."],[17,14,"Mätänemisen minä kutsuin isäkseni, ja madot äidikseni ja sisarekseni.","Mätänemisen minä kutsuin isäkseni, ja madot äidikseni ja sisarekseni."],[17,15,"Kussa on nyt minun odottamiseni? ja kuka ottaa minun toivostani vaarin?","Kussa on nyt minun odottamiseni? ja kuka ottaa minun toivostani vaarin?"],[17,16,"Hautaan se menee, ja makaa minun kanssani mullassa.","Hautaan se menee, ja makaa minun kanssani mullassa."],[18,1,"Niin vastasi Bildad Suasta ja sanoi:","Niin vastasi Bildad Suasta ja sanoi:"],[18,2,"Koska te lakkaatte puhumasta? ymmärtäkäät ensin, ja puhukaamme sitte.","Koska te lakkaatte puhumasta? ymmärtäkäät ensin, ja puhukaamme sitte."],[18,3,"Miksi me pidetään niinkuin juhdat, ja olemme niin saastaiset teidän silmäinne edestä?","Miksi me pidetään niinkuin juhdat, ja olemme niin saastaiset teidän silmäinne edestä?"],[18,4,"Tahdotkos revetä kiukussas? luuletkos, että maa sinun tähtes hyljätään ja kallio siirretään siastansa?","Tahdotkos revetä kiukussas? luuletkos, että maa sinun tähtes hyljätään ja kallio siirretään siastansa?"],[18,5,"Jumalattoman valkeus pitää myös sammutettaman, ja hänen valkiansa kipinä ei pidä paistaman.","Jumalattoman valkeus pitää myös sammutettaman, ja hänen valkiansa kipinä ei pidä paistaman."],[18,6,"Hänen majassansa pitää valkeus tuleman pimeydeksi, ja hänen kynttilänsä pitää siinä sammutettaman.","Hänen majassansa pitää valkeus tuleman pimeydeksi, ja hänen kynttilänsä pitää siinä sammutettaman."],[18,7,"Hänen voimansa askeleet pitää ahdistettaman; ja hänen neuvonsa pitää hänen maahan sysäämän.","Hänen voimansa askeleet pitää ahdistettaman; ja hänen neuvonsa pitää hänen maahan sysäämän."],[18,8,"Sillä hän on viety jalkoinensa paulaan, ja vaeltaa verkossa.","Sillä hän on viety jalkoinensa paulaan, ja vaeltaa verkossa."],[18,9,"Paula pitää pitämän hänen kantapäänsä, ja ryövärit pitää hänen käsittämän.","Paula pitää pitämän hänen kantapäänsä, ja ryövärit pitää hänen käsittämän."],[18,10,"Hänen paulansa on viritetty maan päälle, ja hänen satimensa hänen polullensa.","Hänen paulansa on viritetty maan päälle, ja hänen satimensa hänen polullensa."],[18,11,"Kaikin tahoin pitää kauhistukset häntä peljättämän, ja hänen jalkansa eksyttämän.","Kaikin tahoin pitää kauhistukset häntä peljättämän, ja hänen jalkansa eksyttämän."],[18,12,"Nälkä pitää oleman hänen tavaransa, ja onnettomuus pitää oleman valmistettu hänen kylkeensä.","Nälkä pitää oleman hänen tavaransa, ja onnettomuus pitää oleman valmistettu hänen kylkeensä."],[18,13,"Hänen nahkansa vahvuus pitää kulutettaman, ja hänen väkevyytensä pitää kuoleman esikoisen syömän.","Hänen nahkansa vahvuus pitää kulutettaman, ja hänen väkevyytensä pitää kuoleman esikoisen syömän."],[18,14,"Hänen toivonsa pitää revittämän ylös juurinensa hänen majastansa, ja hän pitää ajettaman pelkoin kuninkaan tykö.","Hänen toivonsa pitää revittämän ylös juurinensa hänen majastansa, ja hän pitää ajettaman pelkoin kuninkaan tykö."],[18,15,"Se on asuva hänen majassansa hänen puutteensa tähden: hänen majansa päälle pitää tulikiveä viskottaman.","Se on asuva hänen majassansa hänen puutteensa tähden: hänen majansa päälle pitää tulikiveä viskottaman."],[18,16,"Alhaalta pitää hänen juurensa kuivettuman, ja ylhäältä hänen elonsa niitettämän.","Alhaalta pitää hänen juurensa kuivettuman, ja ylhäältä hänen elonsa niitettämän."],[18,17,"Hänen muistonsa pitää hukkuman maan päältä, ja ei pidä ensinkään hänellä nimeä oleman kadulla.","Hänen muistonsa pitää hukkuman maan päältä, ja ei pidä ensinkään hänellä nimeä oleman kadulla."],[18,18,"Hän pitää ajettaman valkeudesta pimeyteen, ja pitää maalta heitettämän pois.","Hän pitää ajettaman valkeudesta pimeyteen, ja pitää maalta heitettämän pois."],[18,19,"Ei hänellä pidä yhtään lasta oleman, eikä lasten lasta hänen kanssansa; ja ei pidä yhtään hänen asuinsioihinsa jäämän.","Ei hänellä pidä yhtään lasta oleman, eikä lasten lasta hänen kanssansa; ja ei pidä yhtään hänen asuinsioihinsa jäämän."],[18,20,"Ne jotka hänen perässänsä tulevat, pitää hämmästymän hänen päivästänsä, ja ne jotka hänen edellänsä ovat olleet, pitää peljästymän.","Ne jotka hänen perässänsä tulevat, pitää hämmästymän hänen päivästänsä, ja ne jotka hänen edellänsä ovat olleet, pitää peljästymän."],[18,21,"Tämä on jumalattoman maja, ja tämä on sen sia, joka ei Jumalasta mitään tiedä.","Tämä on jumalattoman maja, ja tämä on sen sia, joka ei Jumalasta mitään tiedä."],[19,1,"Mutta Job vastasi ja sanoi:","Mutta Job vastasi ja sanoi:"],[19,2,"Kuinka kauvan te vaivaatte minun sieluani? ja runtelette minua sanoilla?","Kuinka kauvan te vaivaatte minun sieluani? ja runtelette minua sanoilla?"],[19,3,"Te olette nyt kymmenen kertaa pilkanneet minua; ja ette häpee minua niin vaivata.","Te olette nyt kymmenen kertaa pilkanneet minua; ja ette häpee minua niin vaivata."],[19,4,"Jos minä erehdyn, niin minä itselleni erehdyn.","Jos minä erehdyn, niin minä itselleni erehdyn."],[19,5,"Mutta te tosin nousette minua vastaan, ja soimaatte minun pilkkaani.","Mutta te tosin nousette minua vastaan, ja soimaatte minun pilkkaani."],[19,6,"Niin tietäkäät nyt, että Jumala hukuttaa minun, ja on piirittänyt minun verkkoihinsa.","Niin tietäkäät nyt, että Jumala hukuttaa minun, ja on piirittänyt minun verkkoihinsa."],[19,7,"Katso, ehkä minä vielä väkivallan tähden huutaisin, niin ei kuitenkaan kuulla minua: jos minä parkuisin, niin ei tässä ole oikeutta.","Katso, ehkä minä vielä väkivallan tähden huutaisin, niin ei kuitenkaan kuulla minua: jos minä parkuisin, niin ei tässä ole oikeutta."],[19,8,"Hän on aidannat minun tieni, etten minä taida sitä käydä, ja pannut pimeyden minun poluilleni.","Hän on aidannat minun tieni, etten minä taida sitä käydä, ja pannut pimeyden minun poluilleni."],[19,9,"Hän on riisunut minun kunniani minulta, ja ottanut pois kruunun minun päästäni.","Hän on riisunut minun kunniani minulta, ja ottanut pois kruunun minun päästäni."],[19,10,"Hän on maahan kukistanut minun joka kulmalta, ja laskenut minun menemään; ja on reväissyt ylös minun toivoni niinkuin puun.","Hän on maahan kukistanut minun joka kulmalta, ja laskenut minun menemään; ja on reväissyt ylös minun toivoni niinkuin puun."],[19,11,"Hän on hirmuisesti vihastunut minun päälleni, ja pitää minun vihamiehenänsä.","Hän on hirmuisesti vihastunut minun päälleni, ja pitää minun vihamiehenänsä."],[19,12,"Hänen sotajoukkonsa ovat kokoontuneet, ja asettaneet tiensä minua kohden, ja piirittäneet minun majani.","Hänen sotajoukkonsa ovat kokoontuneet, ja asettaneet tiensä minua kohden, ja piirittäneet minun majani."],[19,13,"Hän on eroittanut minun veljeni kauvas minusta, ja minun tuttavani ovat minulle muukalaisiksi tulleet.","Hän on eroittanut minun veljeni kauvas minusta, ja minun tuttavani ovat minulle muukalaisiksi tulleet."],[19,14,"Minun lähimmäiseni piiloivat minua, ja minun ystäväni ovat unhottaneet minun.","Minun lähimmäiseni piiloivat minua, ja minun ystäväni ovat unhottaneet minun."],[19,15,"Minun huonekuntalaiseni ja piikani pitävät minua vieraana, minä olen tuntemattomaksi tullut heidän silmäinsä edessä.","Minun huonekuntalaiseni ja piikani pitävät minua vieraana, minä olen tuntemattomaksi tullut heidän silmäinsä edessä."],[19,16,"Minä huusin palveliaani, ja ei hän vastannut minua: minun täytyy rukoilla häntä omalla suullani.","Minä huusin palveliaani, ja ei hän vastannut minua: minun täytyy rukoilla häntä omalla suullani."],[19,17,"Minun emäntäni vieroi minun henkeäni, ja minun täytyy palvella omia lapsiani.","Minun emäntäni vieroi minun henkeäni, ja minun täytyy palvella omia lapsiani."],[19,18,"Ja nuoretkin lapset minun katsovat ylön: jos minä nousen, niin he puhuvat minua vastaan.","Ja nuoretkin lapset minun katsovat ylön: jos minä nousen, niin he puhuvat minua vastaan."],[19,19,"Kaikki uskolliset ystäväni kauhistuvat minua; ja joita minä rakastin, ovat kääntäneet itsensä minua vastaan.","Kaikki uskolliset ystäväni kauhistuvat minua; ja joita minä rakastin, ovat kääntäneet itsensä minua vastaan."],[19,20,"Minun luuni tarttuivat minun nahkaani ja lihaani, ja en minä taida nahallani peittää hampaitani.","Minun luuni tarttuivat minun nahkaani ja lihaani, ja en minä taida nahallani peittää hampaitani."],[19,21,"Armahtakaat minun päälleni, armahtakaat minun päälleni, te minun ystäväni! sillä Jumalan käsi on minuun sattunut!","Armahtakaat minun päälleni, armahtakaat minun päälleni, te minun ystäväni! sillä Jumalan käsi on minuun sattunut!"],[19,22,"Miksi te vainootte minua niinkuin Jumalakin, ja ette taida minun lihastani ravittaa?","Miksi te vainootte minua niinkuin Jumalakin, ja ette taida minun lihastani ravittaa?"],[19,23,"Jospa minun puheeni kirjoitettaisiin! jospa ne kirjaan pantaisiin, ja painettaisiin!","Jospa minun puheeni kirjoitettaisiin! jospa ne kirjaan pantaisiin, ja painettaisiin!"],[19,24,"Raudalla kaivettaisiin lyijy ijankaikkiseksi muistoksi kiveen.","Raudalla kaivettaisiin lyijy ijankaikkiseksi muistoksi kiveen."],[19,25,"Sillä minä tiedän minun Lunastajani elävän: ja hän on tästälähin maan päällä seisova.","Sillä minä tiedän minun Lunastajani elävän: ja hän on tästälähin maan päällä seisova."],[19,26,"Ja vaikka vihdoin minun nahkani ja tämä (ruumis) lakastuu, saan minä kuitenkin minun lihassani nähdä Jumalan.","Ja vaikka vihdoin minun nahkani ja tämä (ruumis) lakastuu, saan minä kuitenkin minun lihassani nähdä Jumalan."],[19,27,"Hänen minä olen minulleni näkevä, ja minun silmäni katsovat häntä, ja ei kenkään outo. Minun munaskuuni ovat kuluneet minun helmassani.","Hänen minä olen minulleni näkevä, ja minun silmäni katsovat häntä, ja ei kenkään outo. Minun munaskuuni ovat kuluneet minun helmassani."],[19,28,"Tosin teidän pitäis sanoman: Miksi me vainoamme häntä? sillä tämän puheen perustus löytyy minun tykönäni.","Tosin teidän pitäis sanoman: Miksi me vainoamme häntä? sillä tämän puheen perustus löytyy minun tykönäni."],[19,29,"Peljätkäät siis miekkaa, sillä viha on pahain töiden kostomiekka, että te tietäisitte kurituksen tulevan.","Peljätkäät siis miekkaa, sillä viha on pahain töiden kostomiekka, että te tietäisitte kurituksen tulevan."],[20,1,"Silloin Zophar Naemasta vastasi ja sanoi:","Silloin Zophar Naemasta vastasi ja sanoi:"],[20,2,"Minun ajatakseni vaativat siis minua vastaamaan, ja en minä taida itsiäni pidättää.","Minun ajatakseni vaativat siis minua vastaamaan, ja en minä taida itsiäni pidättää."],[20,3,"Minä tahdon kuulla, jos joku minua nuhtelee ja laittaa; sillä minun ymmärrykseni benki vastaa minun puolestani.","Minä tahdon kuulla, jos joku minua nuhtelee ja laittaa; sillä minun ymmärrykseni benki vastaa minun puolestani."],[20,4,"Etkös tiedä sen aina niin käyneen siitä ajasta kuin ibminen on pantu maan päälle,","Etkös tiedä sen aina niin käyneen siitä ajasta kuin ibminen on pantu maan päälle,"],[20,5,"Että jumalattomien kerskaus ei ulotu kauvas; ulkokullattuin ilo on silmänräpäykseksi.","Että jumalattomien kerskaus ei ulotu kauvas; ulkokullattuin ilo on silmänräpäykseksi."],[20,6,"Jos hänen korkeutensa ulottuis taivaasen, ja hänen päänsä sattuis pilviin;","Jos hänen korkeutensa ulottuis taivaasen, ja hänen päänsä sattuis pilviin;"],[20,7,"Niin pitää hänen viimein katooman niinkuin loka, niin että ne jotka hänen ovat näneet, sanovat: kussa hän on?","Niin pitää hänen viimein katooman niinkuin loka, niin että ne jotka hänen ovat näneet, sanovat: kussa hän on?"],[20,8,"Niinkuin uni katoo, niin ei pidä häntä löydettämän, ja niinkuin yönäkö pitää hänen raukeaman.","Niinkuin uni katoo, niin ei pidä häntä löydettämän, ja niinkuin yönäkö pitää hänen raukeaman."],[20,9,"Se silmä, joka hänen nähnyt on, ei pidä häntä enää näkemän, ja hänen paikkansa ei pidä häntä enää näkemän.","Se silmä, joka hänen nähnyt on, ei pidä häntä enää näkemän, ja hänen paikkansa ei pidä häntä enää näkemän."],[20,10,"Hänen lapsensa pitää kerjääjiä palveleman, ja hänen kätensä pitää jälleen hänelle antaman, mitä hän ryövännyt on.","Hänen lapsensa pitää kerjääjiä palveleman, ja hänen kätensä pitää jälleen hänelle antaman, mitä hän ryövännyt on."],[20,11,"Hänen luunsa pitää maksaman hänen salaiset syntinsä, ja pitää makaaman maassa hänen kanssansa.","Hänen luunsa pitää maksaman hänen salaiset syntinsä, ja pitää makaaman maassa hänen kanssansa."],[20,12,"Ehkä vielä pahuus maistais makiasti hänen suussansa, kuitenkin pitää hänen sen kätkemän kielensä päälle.","Ehkä vielä pahuus maistais makiasti hänen suussansa, kuitenkin pitää hänen sen kätkemän kielensä päälle."],[20,13,"Hän säästää, ja ei hylkää sitä, vaan pitää sen suussansa.","Hän säästää, ja ei hylkää sitä, vaan pitää sen suussansa."],[20,14,"Hänen ruokansa pitää muuttuman hänen vatsassansa, kärmeen sapeksi hänen sisälmyksissänsä.","Hänen ruokansa pitää muuttuman hänen vatsassansa, kärmeen sapeksi hänen sisälmyksissänsä."],[20,15,"Sen tavaran jonka hän niellyt on, pitää hänen ylös oksentaman; ja Jumala ajaa ne ulos hänen vatsastansa.","Sen tavaran jonka hän niellyt on, pitää hänen ylös oksentaman; ja Jumala ajaa ne ulos hänen vatsastansa."],[20,16,"Hänen pitää imemän kärmeen myrkkyä, ja kyykärmeen kieli on hänen tappava.","Hänen pitää imemän kärmeen myrkkyä, ja kyykärmeen kieli on hänen tappava."],[20,17,"Ei hänen pidä näkemän ojia ja virtoja, joista hunaja ja voi vuotavat.","Ei hänen pidä näkemän ojia ja virtoja, joista hunaja ja voi vuotavat."],[20,18,"Hän tekee työtä, ja ei saa nautita, ja hänen kalunsa pitää toisen saaman, niin ettei hänellä pidä niistä iloa oleman.","Hän tekee työtä, ja ei saa nautita, ja hänen kalunsa pitää toisen saaman, niin ettei hänellä pidä niistä iloa oleman."],[20,19,"Sillä hän on polkenut ja hyljännyt köyhän, hän on repinyt itsellensä huoneita, joita ei hän ole rakentanut.","Sillä hän on polkenut ja hyljännyt köyhän, hän on repinyt itsellensä huoneita, joita ei hän ole rakentanut."],[20,20,"Sillä hänen vatsansa ei ole taitanut täyteen tulla, ja hänen kalliit kalunsa ei taida häntä pelastaa.","Sillä hänen vatsansa ei ole taitanut täyteen tulla, ja hänen kalliit kalunsa ei taida häntä pelastaa."],[20,21,"Hänen ruastansa ei pidä mitään jäämän; sentähden ei pidä hänen hyvät päivänsä pysyväiset oleman.","Hänen ruastansa ei pidä mitään jäämän; sentähden ei pidä hänen hyvät päivänsä pysyväiset oleman."],[20,22,"Ehkä hänellä olis yltäkyllä, niin pitää hänellä kuitenkin ahdistus oleman: kaikki käden vaiva pitää hänen päällensä tuleman.","Ehkä hänellä olis yltäkyllä, niin pitää hänellä kuitenkin ahdistus oleman: kaikki käden vaiva pitää hänen päällensä tuleman."],[20,23,"Hänen vatsansa pitää vihdoin täyteen tuleman, ja hänen pitää lähettämän vihansa hirmuisuuden hänen päällensä: hän antaa sataa sotansa hänen päällensä.","Hänen vatsansa pitää vihdoin täyteen tuleman, ja hänen pitää lähettämän vihansa hirmuisuuden hänen päällensä: hän antaa sataa sotansa hänen päällensä."],[20,24,"Hänen pitää pakeneman rautaisia sota-aseita, ja vaskijoutsen pitää hänen lävitsensä käymän.","Hänen pitää pakeneman rautaisia sota-aseita, ja vaskijoutsen pitää hänen lävitsensä käymän."],[20,25,"Avoin miekka pitää käymän hänen lävitsensä, ja miekan välkkynä, joka hänelle pitää karvas oleman, pitää pelvolla hänen päällensä tuleman.","Avoin miekka pitää käymän hänen lävitsensä, ja miekan välkkynä, joka hänelle pitää karvas oleman, pitää pelvolla hänen päällensä tuleman."],[20,26,"Koko pimeys on hänelle kätketty tavaraksi; tuli pitää hänen kuluttaman, joka ei puhallettu ole, ja sille, joka jää hänen majaansa, pitää pahoin käymän.","Koko pimeys on hänelle kätketty tavaraksi; tuli pitää hänen kuluttaman, joka ei puhallettu ole, ja sille, joka jää hänen majaansa, pitää pahoin käymän."],[20,27,"Taivaan pitää ilmoittaman hänen pahuutensa, ja maan pitää asettaman itsensä häntä vastaan.","Taivaan pitää ilmoittaman hänen pahuutensa, ja maan pitää asettaman itsensä häntä vastaan."],[20,28,"Hänen huoneensa hedelmä pitää vietämän pois, ja hajoitettaman hänen vihansa päivänä.","Hänen huoneensa hedelmä pitää vietämän pois, ja hajoitettaman hänen vihansa päivänä."],[20,29,"Tämä on jumalattoman ihmisen osa Jumalalta, ja hänen puheensa perintö Jumalalta.","Tämä on jumalattoman ihmisen osa Jumalalta, ja hänen puheensa perintö Jumalalta."],[21,1,"Job vastasi ja sanoi:","Job vastasi ja sanoi:"],[21,2,"Kuulkaat visusti minun puhettani, ja antakaat neuvoa teitänne.","Kuulkaat visusti minun puhettani, ja antakaat neuvoa teitänne."],[21,3,"Kärsikäät minua, että minä myös puhuisin: ja kuin minä puhunut olen, pilkkaa sitte.","Kärsikäät minua, että minä myös puhuisin: ja kuin minä puhunut olen, pilkkaa sitte."],[21,4,"Puhunko minä ihmisen kanssa? miksi ei minun henkeni pitäisi tästä murehtiman?","Puhunko minä ihmisen kanssa? miksi ei minun henkeni pitäisi tästä murehtiman?"],[21,5,"Katsokaat minun päälleni, ja hämmästykäät, ja pankaat kätenne suun eteen.","Katsokaat minun päälleni, ja hämmästykäät, ja pankaat kätenne suun eteen."],[21,6,"Koska minä sitä ajattelen, niin minä peljästyn, ja vavistus tulee minun lihani päälle.","Koska minä sitä ajattelen, niin minä peljästyn, ja vavistus tulee minun lihani päälle."],[21,7,"Miksi jumalattomat elävät, tulevat vanhaksi ja lisääntyvät tavarassa?","Miksi jumalattomat elävät, tulevat vanhaksi ja lisääntyvät tavarassa?"],[21,8,"Heidän siemenensä on pysyväinen heidän ympärillänsä, ja heidän sikiänsä ovat läsnä heitä.","Heidän siemenensä on pysyväinen heidän ympärillänsä, ja heidän sikiänsä ovat läsnä heitä."],[21,9,"Heidän huoneensa ovat vapaat pelvosta, ja Jumalan vitsa ei ole heidän päällänsä.","Heidän huoneensa ovat vapaat pelvosta, ja Jumalan vitsa ei ole heidän päällänsä."],[21,10,"Heidän sonninsa päästetään, ja ei käy väärin, heidän lehmänsä poikivat, ja ei ole hedelmättömät.","Heidän sonninsa päästetään, ja ei käy väärin, heidän lehmänsä poikivat, ja ei ole hedelmättömät."],[21,11,"Heidän nuoret lapsensa käyvät ulos niinkuin lauma, ja heidän lapsensa hyppäävät.","Heidän nuoret lapsensa käyvät ulos niinkuin lauma, ja heidän lapsensa hyppäävät."],[21,12,"He riemuitsevat trumpuilla ja kanteleilla, ja iloitsevat huiluilla.","He riemuitsevat trumpuilla ja kanteleilla, ja iloitsevat huiluilla."],[21,13,"He vanhenevat hyvissä päivissä, ja menevät silmänräpäyksessä helvettiin.","He vanhenevat hyvissä päivissä, ja menevät silmänräpäyksessä helvettiin."],[21,14,"Jotka sanovat Jumalalle: mene pois meidän tyköämme; sillä emme tahdo tietää sinun tietäs.","Jotka sanovat Jumalalle: mene pois meidän tyköämme; sillä emme tahdo tietää sinun tietäs."],[21,15,"Kuka on Kaikkivaltias, että meidän pitää häntä palveleman? eli mitä meidän siitä hyvää on, että me häntä rukoilemme?","Kuka on Kaikkivaltias, että meidän pitää häntä palveleman? eli mitä meidän siitä hyvää on, että me häntä rukoilemme?"],[21,16,"Mutta katso, heidän tavaransa ei ole heidän kädessänsä: jumalattomain neuvo pitää kaukana minusta oleman.","Mutta katso, heidän tavaransa ei ole heidän kädessänsä: jumalattomain neuvo pitää kaukana minusta oleman."],[21,17,"Kuinka jumalattoman kynttilä sammuu, ja heidän kadotuksensa tulee heidän päällensä? Hänen pitää jakaman surkeutta vihassansa.","Kuinka jumalattoman kynttilä sammuu, ja heidän kadotuksensa tulee heidän päällensä? Hänen pitää jakaman surkeutta vihassansa."],[21,18,"Heidän pitää oleman niinkuin korsi tuulessa, ja niinkuin akanat, jotka tuulispää vie salaisesti pois.","Heidän pitää oleman niinkuin korsi tuulessa, ja niinkuin akanat, jotka tuulispää vie salaisesti pois."],[21,19,"Jumala säästää hänen onnettomuutensa hänen lapsillensa; koska hän maksaa hänelle, silloin hänen pitää tietämän.","Jumala säästää hänen onnettomuutensa hänen lapsillensa; koska hän maksaa hänelle, silloin hänen pitää tietämän."],[21,20,"Hänen silmänsä pitää näkemän hänen kadotuksensa, ja Kaikkivaltiaan vihasta pitää hänen juoman.","Hänen silmänsä pitää näkemän hänen kadotuksensa, ja Kaikkivaltiaan vihasta pitää hänen juoman."],[21,21,"Sillä mitä hän tottelee hänen huonettansa hänen jälkeensä? Ja hänen kuukauttensa luku tuskin tulee puolillensa.","Sillä mitä hän tottelee hänen huonettansa hänen jälkeensä? Ja hänen kuukauttensa luku tuskin tulee puolillensa."],[21,22,"Kuka tahtoo opettaa Jumalaa, joka korkiatkin tuomitsee?","Kuka tahtoo opettaa Jumalaa, joka korkiatkin tuomitsee?"],[21,23,"Tämä kuolee vauraana ja terveenä, rikkaana ja onnellisena.","Tämä kuolee vauraana ja terveenä, rikkaana ja onnellisena."],[21,24,"Hänen piimäastiansa ovat täynnä rieskaa, ja hänen luunsa ovat täynnä ydintä.","Hänen piimäastiansa ovat täynnä rieskaa, ja hänen luunsa ovat täynnä ydintä."],[21,25,"Mutta toinen kuolee murheellisella mielellä, ja ei koskaan syönyt ilossa.","Mutta toinen kuolee murheellisella mielellä, ja ei koskaan syönyt ilossa."],[21,26,"Ja he makaavat ynnä maassa, ja madot peittävät heidät.","Ja he makaavat ynnä maassa, ja madot peittävät heidät."],[21,27,"Katso, minä tunnen teidän ajatuksenne ja teidän väärän aivoituksenne minua vastaan.","Katso, minä tunnen teidän ajatuksenne ja teidän väärän aivoituksenne minua vastaan."],[21,28,"Sillä te sanotte: kussa ruhtinaan huone on? ja kussa ovat majat, joissa jumalattomat asuiva?","Sillä te sanotte: kussa ruhtinaan huone on? ja kussa ovat majat, joissa jumalattomat asuiva?"],[21,29,"Ettekö ole tutkineet vaeltavaisilta? ja ettekö tiedä hänen merkkejänsä?","Ettekö ole tutkineet vaeltavaisilta? ja ettekö tiedä hänen merkkejänsä?"],[21,30,"Sillä paha säästetään kadotuksen päivään, ja hän pysyy hamaan vihan päivään asti.","Sillä paha säästetään kadotuksen päivään, ja hän pysyy hamaan vihan päivään asti."],[21,31,"Kuka sanoo hänen edessänsä hänen tiensä? ja kuka kostaa hänelle sen minkä hän tehnyt on?","Kuka sanoo hänen edessänsä hänen tiensä? ja kuka kostaa hänelle sen minkä hän tehnyt on?"],[21,32,"Mutta hän viedään hautaan, ja täytyy joukossa pysyä.","Mutta hän viedään hautaan, ja täytyy joukossa pysyä."],[21,33,"Ojan multa kelpasi hänelle, ja kaikki ihmiset viedään hänen perässänsä; ja ne jotka ovat hänen edellänsä olleet, ovat epälukuiset.","Ojan multa kelpasi hänelle, ja kaikki ihmiset viedään hänen perässänsä; ja ne jotka ovat hänen edellänsä olleet, ovat epälukuiset."],[21,34,"Miksi te minua lohdutatte turhaan? ja teidän vastauksenne löydetään vääräksi.","Miksi te minua lohdutatte turhaan? ja teidän vastauksenne löydetään vääräksi."],[22,1,"Silloin vastasi Eliphas Temanilainen, ja sanoi:","Silloin vastasi Eliphas Temanilainen, ja sanoi:"],[22,2,"Mitä mies taitaa Jumalalle hyödyllinen olla? vaan itsiänsä taitaa ymmärtäväinen hyödyttää.","Mitä mies taitaa Jumalalle hyödyllinen olla? vaan itsiänsä taitaa ymmärtäväinen hyödyttää."],[22,3,"Luuletkos Kaikkivaltiaalle kelpaavan, että sinus luet hurskaaksi? eli mitä se auttais, ehkä sinun ties olisivat ilman rikosta?","Luuletkos Kaikkivaltiaalle kelpaavan, että sinus luet hurskaaksi? eli mitä se auttais, ehkä sinun ties olisivat ilman rikosta?"],[22,4,"Luuletkos, että hän pelkää sinua rangaista ja käydä oikeudelle kanssas?","Luuletkos, että hän pelkää sinua rangaista ja käydä oikeudelle kanssas?"],[22,5,"Eikö sinun pahuutes ole suuri? Ja sinun vääryydelläs ei ole loppua.","Eikö sinun pahuutes ole suuri? Ja sinun vääryydelläs ei ole loppua."],[22,6,"Sinä olet ottanut pantin veljeltäs ilman syytä, ja olet riisunut vaatteen alastomalta.","Sinä olet ottanut pantin veljeltäs ilman syytä, ja olet riisunut vaatteen alastomalta."],[22,7,"Et sinä ole antanut väsyneelle vettä juoda; sinä olet kieltänyt isoovaiselta leivän.","Et sinä ole antanut väsyneelle vettä juoda; sinä olet kieltänyt isoovaiselta leivän."],[22,8,"Mutta voimallinen sai omistaa maan, ja arvossa pidettävä sai siinä asua.","Mutta voimallinen sai omistaa maan, ja arvossa pidettävä sai siinä asua."],[22,9,"Lesket olet sinä laskenut tyhjänä, ja taittanut orpoin käsivarret.","Lesket olet sinä laskenut tyhjänä, ja taittanut orpoin käsivarret."],[22,10,"Sentähden olet sinä kierretty pauloilla, ja hämmästys on sinun äkisti peljättänyt,","Sentähden olet sinä kierretty pauloilla, ja hämmästys on sinun äkisti peljättänyt,"],[22,11,"Eli pimeys, ettes näkisi; ja vedenpaljous on peittänyt sinun.","Eli pimeys, ettes näkisi; ja vedenpaljous on peittänyt sinun."],[22,12,"Eikö Jumala ole ylhäällä taivaissa? Ja katsos ylimmäisiä tähtiä, että ne korkiat ovat.","Eikö Jumala ole ylhäällä taivaissa? Ja katsos ylimmäisiä tähtiä, että ne korkiat ovat."],[22,13,"Ja sinä sanot: mitä Jumala tietää? taitaneeko hän tuomita sitä, mikä pimeydessä on?","Ja sinä sanot: mitä Jumala tietää? taitaneeko hän tuomita sitä, mikä pimeydessä on?"],[22,14,"Pilvet peittävät hänen, ettei hän näe: hän vaeltaa taivaan ympäristöllä.","Pilvet peittävät hänen, ettei hän näe: hän vaeltaa taivaan ympäristöllä."],[22,15,"Tahdotkos tuta maailman polkuja, joita väärät ihmiset käyneet ovat?","Tahdotkos tuta maailman polkuja, joita väärät ihmiset käyneet ovat?"],[22,16,"Jotka ennen aikaansa hukkuneet ovat, ja vesi on liottanut heidän perustuksensa.","Jotka ennen aikaansa hukkuneet ovat, ja vesi on liottanut heidän perustuksensa."],[22,17,"Ne jotka sanovat Jumalalle: mene meistä pois! mitä Kaikkivaltias taitais heidän tehdä.","Ne jotka sanovat Jumalalle: mene meistä pois! mitä Kaikkivaltias taitais heidän tehdä."],[22,18,"Vaikka hän on täyttänyt heidän huoneensa tavaralla; mutta jumalattomain neuvo olkoon kaukana minusta.","Vaikka hän on täyttänyt heidän huoneensa tavaralla; mutta jumalattomain neuvo olkoon kaukana minusta."],[22,19,"Hurskaat näkevät sen ja iloitsevat, ja viatoin pilkkaa heitä.","Hurskaat näkevät sen ja iloitsevat, ja viatoin pilkkaa heitä."],[22,20,"Meidän varamme ei pidä hukkuman, vaan heidän tähteensä pitää tulen polttaman.","Meidän varamme ei pidä hukkuman, vaan heidän tähteensä pitää tulen polttaman."],[22,21,"Niin sovi nyt hänen kanssansa, ja ole rauhallinen; siitä saat paljon hyvää.","Niin sovi nyt hänen kanssansa, ja ole rauhallinen; siitä saat paljon hyvää."],[22,22,"Kuule lakia hänen suustansa, ja käsitä hänen puheensa sinun sydämees.","Kuule lakia hänen suustansa, ja käsitä hänen puheensa sinun sydämees."],[22,23,"Jos sinä käännät sinus Kaikkivaltiaan tykö, niin sinä rakennetaan, ja saatat vääryyden kauvas majastas.","Jos sinä käännät sinus Kaikkivaltiaan tykö, niin sinä rakennetaan, ja saatat vääryyden kauvas majastas."],[22,24,"Niin sinä annat kullan mullasta, ja ojan kivistä kalliin kullan.","Niin sinä annat kullan mullasta, ja ojan kivistä kalliin kullan."],[22,25,"Kaikkivaltias on sinun kultas, ja hopiaa pitää sinulla paljo oleman.","Kaikkivaltias on sinun kultas, ja hopiaa pitää sinulla paljo oleman."],[22,26,"Silloin sinun ilos pitää oleman Kaikkivaltiaassa, ja nostaman kasvos Jumalan tykö.","Silloin sinun ilos pitää oleman Kaikkivaltiaassa, ja nostaman kasvos Jumalan tykö."],[22,27,"Sinä rukoilet häntä, ja hän kuulee sinua, ja sinä maksat lupaukses.","Sinä rukoilet häntä, ja hän kuulee sinua, ja sinä maksat lupaukses."],[22,28,"Mitä aioit, sen hän antaa sinulle menestyä; ja valkeus paistaa sinun teilläs.","Mitä aioit, sen hän antaa sinulle menestyä; ja valkeus paistaa sinun teilläs."],[22,29,"Sillä ne jotka itsensä nöyryyttävät, korottaa hän, ja se joka silmänsä painaa alas, vapautetaan.","Sillä ne jotka itsensä nöyryyttävät, korottaa hän, ja se joka silmänsä painaa alas, vapautetaan."],[22,30,"Sekin, joka ei viatoin ole, autetaan ja pelastetaan sinun kättes puhtauden tähden.","Sekin, joka ei viatoin ole, autetaan ja pelastetaan sinun kättes puhtauden tähden."],[23,1,"Job vastasi ja sanoi:","Job vastasi ja sanoi:"],[23,2,"Minun puheeni on vielä murheellinen, ja minun voimani on heikko huokausteni tähden.","Minun puheeni on vielä murheellinen, ja minun voimani on heikko huokausteni tähden."],[23,3,"Jospa minä tietäisin, kuinka minä hänen löytäisin, ja tulisin hänen istuimensa tykö!","Jospa minä tietäisin, kuinka minä hänen löytäisin, ja tulisin hänen istuimensa tykö!"],[23,4,"Ja asettaisin oikeuden hänen eteensä, ja täyttäisi suuni perustuksilla,","Ja asettaisin oikeuden hänen eteensä, ja täyttäisi suuni perustuksilla,"],[23,5,"Tietäisin, mitä hän vastais minua, ja ymmärtäisin, mitä hän minulle sanova olis.","Tietäisin, mitä hän vastais minua, ja ymmärtäisin, mitä hän minulle sanova olis."],[23,6,"Riiteleekö hän suurella voimalla minun kanssani? Ei, vaan itse antaa minulle voimaa.","Riiteleekö hän suurella voimalla minun kanssani? Ei, vaan itse antaa minulle voimaa."],[23,7,"Sillä minä vakuuteni osoittaisin hänen edessänsä, ja pääsisin ijäti vapaaksi siitä, joka minun tuomitsee.","Sillä minä vakuuteni osoittaisin hänen edessänsä, ja pääsisin ijäti vapaaksi siitä, joka minun tuomitsee."],[23,8,"Mutta jos minä kohdastansa käyn, niin ei hän ole siellä; jos minä menen takaperin, niin en minä häntä havaitse.","Mutta jos minä kohdastansa käyn, niin ei hän ole siellä; jos minä menen takaperin, niin en minä häntä havaitse."],[23,9,"Jos hän on vasemmalla puolella, niin en minä häntä käsitä; jos hän kätkee itsensä oikialle puolelle, niin en minä häntä näe.","Jos hän on vasemmalla puolella, niin en minä häntä käsitä; jos hän kätkee itsensä oikialle puolelle, niin en minä häntä näe."],[23,10,"Mutta hän tuntee minun tieni; koetelkaan minua, niin minä löydetään niinkuin kulta;","Mutta hän tuntee minun tieni; koetelkaan minua, niin minä löydetään niinkuin kulta;"],[23,11,"Sillä minä panen jalkani hänen askeleillensa, pidän hänen tiensä, ja en poikkee siitä.","Sillä minä panen jalkani hänen askeleillensa, pidän hänen tiensä, ja en poikkee siitä."],[23,12,"Ja en poikkee hänen huultensa käskyistä, ja kätken hänen suunsa sanat, niinkuin minun tapani on.","Ja en poikkee hänen huultensa käskyistä, ja kätken hänen suunsa sanat, niinkuin minun tapani on."],[23,13,"Hän on itse ainoa, kuka estää häntä? hän tekee, mitä hän tahtoo.","Hän on itse ainoa, kuka estää häntä? hän tekee, mitä hän tahtoo."],[23,14,"Sillä hän täyttää aivoitukseni minusta; ja tainkaltaisia on paljo hänen tykönänsä.","Sillä hän täyttää aivoitukseni minusta; ja tainkaltaisia on paljo hänen tykönänsä."],[23,15,"Sentähden olen minä hämmästynyt hänen edessänsä, ja koska minä sen ymmärrän, niin minä pelkään häntä.","Sentähden olen minä hämmästynyt hänen edessänsä, ja koska minä sen ymmärrän, niin minä pelkään häntä."],[23,16,"Ja Jumala on tehnyt minun sydämeni pehmiäksi, ja Kaikkivaltias on minun peljättänyt.","Ja Jumala on tehnyt minun sydämeni pehmiäksi, ja Kaikkivaltias on minun peljättänyt."],[23,17,"Sillä pimeys ei luovu minusta, ja synkeys ei kätketä minulta.","Sillä pimeys ei luovu minusta, ja synkeys ei kätketä minulta."],[24,1,"Siksi ei Kaikkivaltiaalta ole ajat salatut? ja ne, jotka hänen tuntevat, ei näe hänen päiviänsä?","Siksi ei Kaikkivaltiaalta ole ajat salatut? ja ne, jotka hänen tuntevat, ei näe hänen päiviänsä?"],[24,2,"He siirtävät rajan, he ryöväävät lauman ja ruokkivat sen. '","He siirtävät rajan, he ryöväävät lauman ja ruokkivat sen. '"],[24,3,"He ajavat orpoin aasit pois, ja ottavat leskein härjät pantiksi.","He ajavat orpoin aasit pois, ja ottavat leskein härjät pantiksi."],[24,4,"Köyhäin täytyy tiellä paeta heitä, ja siviät maan päällä lymyttävät itsensä.","Köyhäin täytyy tiellä paeta heitä, ja siviät maan päällä lymyttävät itsensä."],[24,5,"Katso, niinkuin metsä-aasit korvessa, lähtevät he ulos ja samoovat varhain saaliin perään: korvessa on jokaiselle heistä ruokaa, niin myös nuorukaisille.","Katso, niinkuin metsä-aasit korvessa, lähtevät he ulos ja samoovat varhain saaliin perään: korvessa on jokaiselle heistä ruokaa, niin myös nuorukaisille."],[24,6,"He niittävät pellolla hänen tulonsa, ja poimivat ja hakevat jumalattoman viinamäessä.","He niittävät pellolla hänen tulonsa, ja poimivat ja hakevat jumalattoman viinamäessä."],[24,7,"Alastoman antavat he maata ilman vaatetta ja peittämättä pakkasessa.","Alastoman antavat he maata ilman vaatetta ja peittämättä pakkasessa."],[24,8,"Vuorten vuotamisesta tulevat he märäksi; ja ettei heillä yhtään turvaa ole, turvaavat he mäkiin.","Vuorten vuotamisesta tulevat he märäksi; ja ettei heillä yhtään turvaa ole, turvaavat he mäkiin."],[24,9,"He repivät orvot nisistä, ja panttaavat köyhän.","He repivät orvot nisistä, ja panttaavat köyhän."],[24,10,"Alastoman antavat he käydä verhotta, ja ottavat isoovaiselta jalalliset pois.","Alastoman antavat he käydä verhotta, ja ottavat isoovaiselta jalalliset pois."],[24,11,"He pusertavat öljyä huonettensa vaiheella, ja janoovat viinaa kuurnitessa.","He pusertavat öljyä huonettensa vaiheella, ja janoovat viinaa kuurnitessa."],[24,12,"He saattavat kansan kaupungissa huokaamaan, ja tapettuin sielut huutamaan: ja ei Jumala heitä rankaise.","He saattavat kansan kaupungissa huokaamaan, ja tapettuin sielut huutamaan: ja ei Jumala heitä rankaise."],[24,13,"Sentähden ovat he vilpistyneet valkeudesta, ja ei tunne sen tietä, ja ei palaja sen poluille.","Sentähden ovat he vilpistyneet valkeudesta, ja ei tunne sen tietä, ja ei palaja sen poluille."],[24,14,"Murhaaja nousee varhain ja tappaa köyhän ja tarvitsevan, ja on yöllä niinkuin varas.","Murhaaja nousee varhain ja tappaa köyhän ja tarvitsevan, ja on yöllä niinkuin varas."],[24,15,"Salavuoteisen silmät vartioitsevat hämärää, ja sanoo: ei minua yksikään silmä näe; ja luulee itsensä peitetyksi.","Salavuoteisen silmät vartioitsevat hämärää, ja sanoo: ei minua yksikään silmä näe; ja luulee itsensä peitetyksi."],[24,16,"Pimeässä hän kaivaa itsensä huoneisiin, jotka he päivällä ovat itsellensä merkinneet, ja ei tahdo tietää valkeutta.","Pimeässä hän kaivaa itsensä huoneisiin, jotka he päivällä ovat itsellensä merkinneet, ja ei tahdo tietää valkeutta."],[24,17,"Sillä vaikka aamu heille tulis, on se heille niinkuin pimeys; sillä hän tuntee pimeyden kauhistuksen.","Sillä vaikka aamu heille tulis, on se heille niinkuin pimeys; sillä hän tuntee pimeyden kauhistuksen."],[24,18,"Hän on keviä veden päällä, heidän osansa pitää kirotun oleman maalla; ja ei hän katso viinamäkien tietä.","Hän on keviä veden päällä, heidän osansa pitää kirotun oleman maalla; ja ei hän katso viinamäkien tietä."],[24,19,"Helvetti ottaa syntiset pois niinkuin pouta, ja niinkuin kuivuus kuluttaa lumisen veden.","Helvetti ottaa syntiset pois niinkuin pouta, ja niinkuin kuivuus kuluttaa lumisen veden."],[24,20,"Laupius pitää unhottaman hänen, madot syövät hänen makeutensa, ei häntä pidä muistettaman; hän pitää särjettämän niinkuin lahopuu.","Laupius pitää unhottaman hänen, madot syövät hänen makeutensa, ei häntä pidä muistettaman; hän pitää särjettämän niinkuin lahopuu."],[24,21,"Hän on saattanut murheelliseksi hedelmättömän, joka ei synnytä, ja ei tehnyt leskelle mitään hyvää.","Hän on saattanut murheelliseksi hedelmättömän, joka ei synnytä, ja ei tehnyt leskelle mitään hyvää."],[24,22,"Ja on vetänyt voimalliset allensa väellänsä; koska hän seisoo, ei pidä hänen tietämän elämästänsä.","Ja on vetänyt voimalliset allensa väellänsä; koska hän seisoo, ei pidä hänen tietämän elämästänsä."],[24,23,"Hän tekee itsellensä levon, johon hän luottaa, ja hänen silmänsä katsovat heidän teitänsä.","Hän tekee itsellensä levon, johon hän luottaa, ja hänen silmänsä katsovat heidän teitänsä."],[24,24,"He ovat vähän aikaa korotetut, vaan he tulevat tyhjään, ja kukistetaan, ja saavat lopun niinkuin kaikki kappaleet, ja niinkuin oas tähkäpäästä, lyödään he pois.","He ovat vähän aikaa korotetut, vaan he tulevat tyhjään, ja kukistetaan, ja saavat lopun niinkuin kaikki kappaleet, ja niinkuin oas tähkäpäästä, lyödään he pois."],[24,25,"Eikö se niin ole? kuka nuhtelee minua valhetteliaksi, ja minun sanani tyhjäksi tekee?","Eikö se niin ole? kuka nuhtelee minua valhetteliaksi, ja minun sanani tyhjäksi tekee?"],[25,1,"Silloin vastasi Bildad Suasta ja sanoi:","Silloin vastasi Bildad Suasta ja sanoi:"],[25,2,"Hallitus ja pelko on hänen tykönänsä, joka tekee rauhan korkeittensa seassa.","Hallitus ja pelko on hänen tykönänsä, joka tekee rauhan korkeittensa seassa."],[25,3,"Kuka voi lukea hänen joukkonsa? ja kenen päälle ei paista hänen valkeutensa?","Kuka voi lukea hänen joukkonsa? ja kenen päälle ei paista hänen valkeutensa?"],[25,4,"Kuinka on ihminen hurskas Jumalan edessä? eli kuinka vaimon lapsi on puhdas?","Kuinka on ihminen hurskas Jumalan edessä? eli kuinka vaimon lapsi on puhdas?"],[25,5,"Katso, kuu ei valaise vielä, eikä tähdet ole vielä kirkkaat hänen silmäinsä edessä:","Katso, kuu ei valaise vielä, eikä tähdet ole vielä kirkkaat hänen silmäinsä edessä:"],[25,6,"Kuinka paljo vähemmin ihminen, se mato, ja ihmisen lapsi se toukka?","Kuinka paljo vähemmin ihminen, se mato, ja ihmisen lapsi se toukka?"],[26,1,"Job vastasi ja sanoi:","Job vastasi ja sanoi:"],[26,2,"Ketäs autat? sitäkö, jolla ei voimaa ole? autatkos sitä, jolla ei voimaa ole käsivarressa?","Ketäs autat? sitäkö, jolla ei voimaa ole? autatkos sitä, jolla ei voimaa ole käsivarressa?"],[26,3,"Ketäs neuvot? sitäkö, joka ei mitään tiedä, ja opetat voimallista toimittamaan?","Ketäs neuvot? sitäkö, joka ei mitään tiedä, ja opetat voimallista toimittamaan?"],[26,4,"Kenen edessä sinä puhut, ja kenen edessä henkes käy ulos?","Kenen edessä sinä puhut, ja kenen edessä henkes käy ulos?"],[26,5,"Uljaat huokaavat, niin myös ne, jotka veden alla asuvat.","Uljaat huokaavat, niin myös ne, jotka veden alla asuvat."],[26,6,"Helvetti on avoinna hänen edessänsä, ja kadotuksella ei ole peitettä.","Helvetti on avoinna hänen edessänsä, ja kadotuksella ei ole peitettä."],[26,7,"Hän venyttää pohjoisen tyhjän päälle, ja maa riippuu tyhjän päällä.","Hän venyttää pohjoisen tyhjän päälle, ja maa riippuu tyhjän päällä."],[26,8,"Vedet hän kokoo pilviinsä, ja pilvet ei repee niiden alla.","Vedet hän kokoo pilviinsä, ja pilvet ei repee niiden alla."],[26,9,"Hän pitää istuimensa, ja levittää pilvensä sen päälle.","Hän pitää istuimensa, ja levittää pilvensä sen päälle."],[26,10,"Hän on asettanut määrän vetten ympärille, siihenasti kuin valkeus ja pimeys loppuvat.","Hän on asettanut määrän vetten ympärille, siihenasti kuin valkeus ja pimeys loppuvat."],[26,11,"Taivaan patsaat vapisevat ja hämmästyvät hänen kurituksestansa.","Taivaan patsaat vapisevat ja hämmästyvät hänen kurituksestansa."],[26,12,"Voimallansa on hän halaissut meren, ja hänen ymmärryksestänsä tyventyy meren ylpeys.","Voimallansa on hän halaissut meren, ja hänen ymmärryksestänsä tyventyy meren ylpeys."],[26,13,"Taivas tulee kirkkaaksi hänen ilmansa kautta, ja hän valmistaa kädellänsä pitkän kärmeen.","Taivas tulee kirkkaaksi hänen ilmansa kautta, ja hän valmistaa kädellänsä pitkän kärmeen."],[26,14,"Katso, näin tapahtuu hänen tekoinsa kanssa, mutta näistä olemme me vähän kuulleet; vaan kuka voi ymmärtää hänen väkevyytensä jylinän?","Katso, näin tapahtuu hänen tekoinsa kanssa, mutta näistä olemme me vähän kuulleet; vaan kuka voi ymmärtää hänen väkevyytensä jylinän?"],[27,1,"Ja Job puhui vielä sananlaskunsa ja sanoi:","Ja Job puhui vielä sananlaskunsa ja sanoi:"],[27,2,"Niin totta kuin Jumala elää, joka minun oikeuteni kieltää, ja Kaikkivaltias, joka minun sieluni murheelliseksi saattaa:","Niin totta kuin Jumala elää, joka minun oikeuteni kieltää, ja Kaikkivaltias, joka minun sieluni murheelliseksi saattaa:"],[27,3,"Niinkauvan kuin minun henkeni on minussa, ja Jumalalta puhallus minun sieraimissani,","Niinkauvan kuin minun henkeni on minussa, ja Jumalalta puhallus minun sieraimissani,"],[27,4,"Ei pidä minun huuleni vääryyttä puhuman, ja minun kieleni ei pidä petosta ottaman eteensä.","Ei pidä minun huuleni vääryyttä puhuman, ja minun kieleni ei pidä petosta ottaman eteensä."],[27,5,"Pois se minusta, että minä sanoisin teidät hurskaaksi, siihenasti kuin minun loppuni tulee, en minä luovu jumalisuudestani.","Pois se minusta, että minä sanoisin teidät hurskaaksi, siihenasti kuin minun loppuni tulee, en minä luovu jumalisuudestani."],[27,6,"Minun oikeudestani, jonka minä pidän, en minä luovu. Minun omatuntoni ei kalva minua koko elinaikani.","Minun oikeudestani, jonka minä pidän, en minä luovu. Minun omatuntoni ei kalva minua koko elinaikani."],[27,7,"Mutta minun viholliseni löydetään jumalattomaksi, ja minun vastahakoiseni vääräksi.","Mutta minun viholliseni löydetään jumalattomaksi, ja minun vastahakoiseni vääräksi."],[27,8,"Sillä mikä on ulkokullatun toivo, että hän niin ahne on, koska Jumala ottaa hänen sielunsa pois?","Sillä mikä on ulkokullatun toivo, että hän niin ahne on, koska Jumala ottaa hänen sielunsa pois?"],[27,9,"Luuletkos Jumalan kuulevan hänen huutoansa, kuin hänelle ahdistus tulee?","Luuletkos Jumalan kuulevan hänen huutoansa, kuin hänelle ahdistus tulee?"],[27,10,"Kuinka hänellä taitaa olla ilo Kaikkivaltiaalta? ja rukoilla Jumalaa joka aika?","Kuinka hänellä taitaa olla ilo Kaikkivaltiaalta? ja rukoilla Jumalaa joka aika?"],[27,11,"Minä opetan teitä Jumalan kädestä, ja mitä Kaikkivaltiaalle kelpaa, en minä salaa.","Minä opetan teitä Jumalan kädestä, ja mitä Kaikkivaltiaalle kelpaa, en minä salaa."],[27,12,"Katso, te olette kaikki taitavinanne; miksi siis te senkaltaisia turhia asioita otatte eteenne?","Katso, te olette kaikki taitavinanne; miksi siis te senkaltaisia turhia asioita otatte eteenne?"],[27,13,"Tämä on Jumalalta jumalattoman palkka, ja tyrannein perimys, jonka he Kaikkivaltiaalta saavat:","Tämä on Jumalalta jumalattoman palkka, ja tyrannein perimys, jonka he Kaikkivaltiaalta saavat:"],[27,14,"Jos hän saa paljon lapsia, niin ne hukataan miekalla, ja hänen sikiänsä ei ravita leivällä.","Jos hän saa paljon lapsia, niin ne hukataan miekalla, ja hänen sikiänsä ei ravita leivällä."],[27,15,"Hänen jälkeenjääneensä pitää haudattaman kuolemaan, ja hänen leskensä ei pidä itkemän.","Hänen jälkeenjääneensä pitää haudattaman kuolemaan, ja hänen leskensä ei pidä itkemän."],[27,16,"Jos hän kokoo rahaa niinkuin tuhkaa, ja valmistaa hänellensä vaatteita niinkuin lokaa,","Jos hän kokoo rahaa niinkuin tuhkaa, ja valmistaa hänellensä vaatteita niinkuin lokaa,"],[27,17,"Niin hänen pitää kyllä valmistaman, mutta hurskas pukee ne yllensä, ja viatoin jakaa rahan.","Niin hänen pitää kyllä valmistaman, mutta hurskas pukee ne yllensä, ja viatoin jakaa rahan."],[27,18,"Hän rakentaa huoneensa niinkuin toukka, ja niinkuin vartia tekee itsellensä lakan.","Hän rakentaa huoneensa niinkuin toukka, ja niinkuin vartia tekee itsellensä lakan."],[27,19,"Rikas kuolee, vaan ei koota: koska joku silmänsä avaa, niin ei häntä enää löydetä.","Rikas kuolee, vaan ei koota: koska joku silmänsä avaa, niin ei häntä enää löydetä."],[27,20,"Hänen päällensä lankee pelko niinkuin vesi; rajuilma ottaa varkain hänen yöllä pois.","Hänen päällensä lankee pelko niinkuin vesi; rajuilma ottaa varkain hänen yöllä pois."],[27,21,"Itätuuli vie hänen pois, että hän hukkuu, ja tuulispää siirtää hänen sialtansa.","Itätuuli vie hänen pois, että hän hukkuu, ja tuulispää siirtää hänen sialtansa."],[27,22,"Nämät Jumala hänelle lähettää, ja ei säästä häntä: kaikki pitää hänen kädestänsä puuttuman.","Nämät Jumala hänelle lähettää, ja ei säästä häntä: kaikki pitää hänen kädestänsä puuttuman."],[27,23,"Hänen tähtensä pitää käsiä paukutettaman ja vihellettämän, kussa hän on ollut.","Hänen tähtensä pitää käsiä paukutettaman ja vihellettämän, kussa hän on ollut."],[28,1,"Hopialla on hänen lähtemisensä, ja kullalla sia, jossa valetaan.","Hopialla on hänen lähtemisensä, ja kullalla sia, jossa valetaan."],[28,2,"Rauta otetaan maasta, ja kivistä vaski valetaan.","Rauta otetaan maasta, ja kivistä vaski valetaan."],[28,3,"Pimeydelle asetti hän lopun, ja kaiken täydellisyyden hän tutki, niin myös kiven, joka paksussa pimeydessä on, ja kuoleman varjon.","Pimeydelle asetti hän lopun, ja kaiken täydellisyyden hän tutki, niin myös kiven, joka paksussa pimeydessä on, ja kuoleman varjon."],[28,4,"Siitä vuotaa senkaltainen osa, että ympäriasuvaiset ei taida siitä jalkaisin käydä ylitse: se tyhjetään ihmisiltä ja vuotaa pois.","Siitä vuotaa senkaltainen osa, että ympäriasuvaiset ei taida siitä jalkaisin käydä ylitse: se tyhjetään ihmisiltä ja vuotaa pois."],[28,5,"Vilja kasvaa maasta, jonka alla se muutetaan niinkuin tuulelta.","Vilja kasvaa maasta, jonka alla se muutetaan niinkuin tuulelta."],[28,6,"Saphiri löydetään muutamista paikoista, ja maan kokkareita, joissa kultaa on.","Saphiri löydetään muutamista paikoista, ja maan kokkareita, joissa kultaa on."],[28,7,"Sitä polkua ei ole yksikään lintu tuntenut, eikä variksen silmä nähnyt.","Sitä polkua ei ole yksikään lintu tuntenut, eikä variksen silmä nähnyt."],[28,8,"Ne ylpiät sikiät ei ole sitä sotkuneet, eikä jalopeura käynyt sen päällä.","Ne ylpiät sikiät ei ole sitä sotkuneet, eikä jalopeura käynyt sen päällä."],[28,9,"Kädellä kallioon ruvetaan, ja vuoret ylösalaisin kukistetaan.","Kädellä kallioon ruvetaan, ja vuoret ylösalaisin kukistetaan."],[28,10,"Ojat lasketaan kallioista, ja kaikkein kalliimmatkin näkee silmä.","Ojat lasketaan kallioista, ja kaikkein kalliimmatkin näkee silmä."],[28,11,"Virrat estetään juoksemasta, ja ne ilmoitetaan, mitkä näissä peitetyt ovat.","Virrat estetään juoksemasta, ja ne ilmoitetaan, mitkä näissä peitetyt ovat."],[28,12,"Mutta kusta taito löydetään, ja kussa on ymmärryksen sia?","Mutta kusta taito löydetään, ja kussa on ymmärryksen sia?"],[28,13,"Ei yksikään ihminen tiedä hänen siaansa, eikä löydeta elävien maasta.","Ei yksikään ihminen tiedä hänen siaansa, eikä löydeta elävien maasta."],[28,14,"Syvyys sanoo: ei se ole minussa, ja meri sanoo: ei se ole minun tykönäni.","Syvyys sanoo: ei se ole minussa, ja meri sanoo: ei se ole minun tykönäni."],[28,15,"Ei hänestä anneta kultaa, eikä hopiaa punnita sen hinnaksi.","Ei hänestä anneta kultaa, eikä hopiaa punnita sen hinnaksi."],[28,16,"Ei Ophirin kulta, eli kalliit Onikin ja Saphirin kivet ole verratut hänen kanssansa.","Ei Ophirin kulta, eli kalliit Onikin ja Saphirin kivet ole verratut hänen kanssansa."],[28,17,"Kulta ja kallis kivi ei taideta siihen verrattaa, eikä se taideta vaihetettaa kultaisiin astioihin.","Kulta ja kallis kivi ei taideta siihen verrattaa, eikä se taideta vaihetettaa kultaisiin astioihin."],[28,18,"Ramot ja Gabis ei ole mitään sen suhteen: se pidetään kalliimpana päärlyjä.","Ramot ja Gabis ei ole mitään sen suhteen: se pidetään kalliimpana päärlyjä."],[28,19,"Topatsi Etiopiasta ei ole siihen verrattava, ja puhtain kulta ei maksa mitään sen suhteen.","Topatsi Etiopiasta ei ole siihen verrattava, ja puhtain kulta ei maksa mitään sen suhteen."],[28,20,"Kusta siis taito tulee? ja kussa on ymmärryksen sia?","Kusta siis taito tulee? ja kussa on ymmärryksen sia?"],[28,21,"Hän on peitetty kaikkein elävien silmistä, ja salattu taivaan linnuiltakin.","Hän on peitetty kaikkein elävien silmistä, ja salattu taivaan linnuiltakin."],[28,22,"Kadotus ja kuolema sanovat: me olemme korvillamme kuulleet hänen sanomansa.","Kadotus ja kuolema sanovat: me olemme korvillamme kuulleet hänen sanomansa."],[28,23,"Jumala tietää hänen tiensä, ja hän tuntee hänen siansa.","Jumala tietää hänen tiensä, ja hän tuntee hänen siansa."],[28,24,"Sillä hän katselee maan ääriin, ja näkee kaikki, mitä taivaan alla on,","Sillä hän katselee maan ääriin, ja näkee kaikki, mitä taivaan alla on,"],[28,25,"Niin että hän antaa tuulelle hänen painonsa ja vedelle hänen mittansa.","Niin että hän antaa tuulelle hänen painonsa ja vedelle hänen mittansa."],[28,26,"Koska hän asetti sateelle määrän ja pitkäisen tulen leimauksille hänen tiensä,","Koska hän asetti sateelle määrän ja pitkäisen tulen leimauksille hänen tiensä,"],[28,27,"Silloin näki hän sen ja luki sen: hän valmisti sen ja myös tutki sen,","Silloin näki hän sen ja luki sen: hän valmisti sen ja myös tutki sen,"],[28,28,"Ja sanoi ihmiselle: katso, Herran pelko on taito; ja karttaa pahaa on ymmärrys.","Ja sanoi ihmiselle: katso, Herran pelko on taito; ja karttaa pahaa on ymmärrys."],[29,1,"Job puhui taas sananlaskunsa ja sanoi:","Job puhui taas sananlaskunsa ja sanoi:"],[29,2,"Ah jos minä olisin niinkuin entisinä kuukausina! niinä päivinä, joina Jumala minun kätki,","Ah jos minä olisin niinkuin entisinä kuukausina! niinä päivinä, joina Jumala minun kätki,"],[29,3,"Koska hänen valkeutensa paisti minun pääni päälle, ja minä kävin pimeissä hänen valkeudessansa,","Koska hänen valkeutensa paisti minun pääni päälle, ja minä kävin pimeissä hänen valkeudessansa,"],[29,4,"Niinkuin minä olin nuorena olessani; koska Jumalan salaisuus oli minun majani päällä;","Niinkuin minä olin nuorena olessani; koska Jumalan salaisuus oli minun majani päällä;"],[29,5,"Koska Kaikkivaltias oli vielä minun kanssani, ja minun nuorukaiseni minun ympärilläni;","Koska Kaikkivaltias oli vielä minun kanssani, ja minun nuorukaiseni minun ympärilläni;"],[29,6,"Koska minä pesin minun tieni voilla, ja kallio vuoti minulle öljy-ojat;","Koska minä pesin minun tieni voilla, ja kallio vuoti minulle öljy-ojat;"],[29,7,"Koska minä menin kaupunin porteille, ja annoin valmistaa istuimeni kujille;","Koska minä menin kaupunin porteille, ja annoin valmistaa istuimeni kujille;"],[29,8,"Kuin nuoret näkivät minun, niin he pakenivat, ja vanhat nousivat ja seisoivat minun edessäni,","Kuin nuoret näkivät minun, niin he pakenivat, ja vanhat nousivat ja seisoivat minun edessäni,"],[29,9,"Ylimmäiset lakkasivat puhumasta, ja panivat kätensä suunsa päälle,","Ylimmäiset lakkasivat puhumasta, ja panivat kätensä suunsa päälle,"],[29,10,"Ruhtinasten ääni kätkeysi, ja heidän kielensä suun lakeen tarttui.","Ruhtinasten ääni kätkeysi, ja heidän kielensä suun lakeen tarttui."],[29,11,"Sillä kenen korva minun kuuli, se kiitti minua onnelliseksi, ja jonka silmä minun näki, se todisti minusta.","Sillä kenen korva minun kuuli, se kiitti minua onnelliseksi, ja jonka silmä minun näki, se todisti minusta."],[29,12,"Sillä minä autin köyhää, joka huusi, ja orpoa, jolla ei auttajaa ollut.","Sillä minä autin köyhää, joka huusi, ja orpoa, jolla ei auttajaa ollut."],[29,13,"Niiden siunaus, jotka katoomallansa olivat, tuli minun päälleni; ja minä ilahutin leskein sydämen.","Niiden siunaus, jotka katoomallansa olivat, tuli minun päälleni; ja minä ilahutin leskein sydämen."],[29,14,"Vanhurskaus oli minun pukuni, jonka minä päälleni puin, ja minun oikeuteni oli minulle niinkuin hame ja kaunistus.","Vanhurskaus oli minun pukuni, jonka minä päälleni puin, ja minun oikeuteni oli minulle niinkuin hame ja kaunistus."],[29,15,"Minä olin sokian silmä ja ontuvan jalka.","Minä olin sokian silmä ja ontuvan jalka."],[29,16,"Minä olin köyhäin isä, ja jonka asiaa en minä ymmärtänyt, sen minä visusti tutkin.","Minä olin köyhäin isä, ja jonka asiaa en minä ymmärtänyt, sen minä visusti tutkin."],[29,17,"Minä särjin väärän syömähampaat, ja otin saaliin hänen hampaistansa,","Minä särjin väärän syömähampaat, ja otin saaliin hänen hampaistansa,"],[29,18,"Minä ajattelin: minä riuduin pesässäni, ja teen päiväni moneksi niinkuin sannan.","Minä ajattelin: minä riuduin pesässäni, ja teen päiväni moneksi niinkuin sannan."],[29,19,"Minun juureni putkahti veden tykönä, ja kaste pysyi laihoni päällä.","Minun juureni putkahti veden tykönä, ja kaste pysyi laihoni päällä."],[29,20,"Minun kunniallisuuteni uudistui minun edessäni, ja minun joutseni muuttui uudeksi minun kädessäni.","Minun kunniallisuuteni uudistui minun edessäni, ja minun joutseni muuttui uudeksi minun kädessäni."],[29,21,"He kuulivat minua ja odottivat, ja vaikenivat minun neuvooni.","He kuulivat minua ja odottivat, ja vaikenivat minun neuvooni."],[29,22,"Minun sanani jälkeen ei yksikään enempää puhunut, ja minun puheeni tiukkui heidän päällensä.","Minun sanani jälkeen ei yksikään enempää puhunut, ja minun puheeni tiukkui heidän päällensä."],[29,23,"He odottivat minua niinkuin sadetta, ja avasivat suunsa niinkuin ehtoosadetta vastaan.","He odottivat minua niinkuin sadetta, ja avasivat suunsa niinkuin ehtoosadetta vastaan."],[29,24,"Jos minä nauroin heidän puoleensa, ei he luottaneet sen päälle, eikä tahtoneet minua murheesen saattaa.","Jos minä nauroin heidän puoleensa, ei he luottaneet sen päälle, eikä tahtoneet minua murheesen saattaa."],[29,25,"Kuin minä tulin heidän kokouksiinsa, niin minun täytyi istua ylimpänä: ja asuin niinkuin kuningas sotaväen keskellä, lohduttaissani murheellisia.","Kuin minä tulin heidän kokouksiinsa, niin minun täytyi istua ylimpänä: ja asuin niinkuin kuningas sotaväen keskellä, lohduttaissani murheellisia."],[30,1,"Nyt minun nuorempani nauravat minua, joiden isiä en minä olisi pannut minun laumani koirain sekaan;","Nyt minun nuorempani nauravat minua, joiden isiä en minä olisi pannut minun laumani koirain sekaan;"],[30,2,"Joiden voiman minä tyhjänä pidin, jotka ei ijällisiksi tulleet;","Joiden voiman minä tyhjänä pidin, jotka ei ijällisiksi tulleet;"],[30,3,"Ne jotka nälän ja tuskan tähden pakenivat erinänsä korpeen, äsken turmeltuneet ja köyhtyneet,","Ne jotka nälän ja tuskan tähden pakenivat erinänsä korpeen, äsken turmeltuneet ja köyhtyneet,"],[30,4,"Jotka nukulaisia repivät pensasten ympäri; ja katajan juuret olivat heidän ruokansa:","Jotka nukulaisia repivät pensasten ympäri; ja katajan juuret olivat heidän ruokansa:"],[30,5,"He ajettiin ulos, ja huudettiin heitä vastaan niinkuin varasta.","He ajettiin ulos, ja huudettiin heitä vastaan niinkuin varasta."],[30,6,"He asuivat kauhiain ojain tykönä maan luolissa ja vuorten rotkoissa.","He asuivat kauhiain ojain tykönä maan luolissa ja vuorten rotkoissa."],[30,7,"Pensasten keskellä he huusivat, ja ohdakkein sekaan he kokosivat itsensä,","Pensasten keskellä he huusivat, ja ohdakkein sekaan he kokosivat itsensä,"],[30,8,"Turhain ja hyljättyin ihmisten lapset, jotka halvimmat olivat maan päällä.","Turhain ja hyljättyin ihmisten lapset, jotka halvimmat olivat maan päällä."],[30,9,"Ja nyt minä olen heidän lauluksensa tullut, ja minun täytyy heidän juttunansa olla.","Ja nyt minä olen heidän lauluksensa tullut, ja minun täytyy heidän juttunansa olla."],[30,10,"He kauhistavat minua, ja erkanevat kauvas minusta; ja ei he häpee sylkeä minun kasvoilleni.","He kauhistavat minua, ja erkanevat kauvas minusta; ja ei he häpee sylkeä minun kasvoilleni."],[30,11,"Sillä hän on minun köyteni päästänyt, ja on nöyryyttänyt minun: He ovat suitset minun edestäni heittäneet pois.","Sillä hän on minun köyteni päästänyt, ja on nöyryyttänyt minun: He ovat suitset minun edestäni heittäneet pois."],[30,12,"Oikialle puolelle nousivat nuorukaiset: He lykkäsivät pois minun jalkani, ja tekivät tien minua kohden, hukuttaaksensa minua.","Oikialle puolelle nousivat nuorukaiset: He lykkäsivät pois minun jalkani, ja tekivät tien minua kohden, hukuttaaksensa minua."],[30,13,"He ovat kukistaneet minun polkuni: se oli huokia heille minua vahingoittaa, ilman kenenkään avuta.","He ovat kukistaneet minun polkuni: se oli huokia heille minua vahingoittaa, ilman kenenkään avuta."],[30,14,"He ovat tulleet sisälle niinkuin suurten rakoin lävitse, ja ovat sekaseuraisin karaneet sisälle.","He ovat tulleet sisälle niinkuin suurten rakoin lävitse, ja ovat sekaseuraisin karaneet sisälle."],[30,15,"Pelko on kääntynyt minua vastaan, ja niinkuin tuuli vainonnut minun kunniaani, ja niinkuin pilvi, on minun autuuteni mennyt ohitse.","Pelko on kääntynyt minua vastaan, ja niinkuin tuuli vainonnut minun kunniaani, ja niinkuin pilvi, on minun autuuteni mennyt ohitse."],[30,16,"Mutta nyt kääntää minun sieluni itsensä minua vastaan, ja minun murhepäiväni ovat minun käsittäneet.","Mutta nyt kääntää minun sieluni itsensä minua vastaan, ja minun murhepäiväni ovat minun käsittäneet."],[30,17,"Yöllä minun luuni lävistettiin kaikin paikoin lävitse, ja minun suoneni ei saa lepoa.","Yöllä minun luuni lävistettiin kaikin paikoin lävitse, ja minun suoneni ei saa lepoa."],[30,18,"Suuren voiman kautta minun vaatteeni muutetaan, ja hän on vyöttänyt minun niinkuin hameeni pään lävellä.","Suuren voiman kautta minun vaatteeni muutetaan, ja hän on vyöttänyt minun niinkuin hameeni pään lävellä."],[30,19,"Minä sotkutaan lokaan, ja verrataan tomuun ja tuhkaan.","Minä sotkutaan lokaan, ja verrataan tomuun ja tuhkaan."],[30,20,"Jos minä hudan sinun tykös, niin et sinä vastaa minua: jos minä käyn edes, niin et sinä minusta tietävinäs ole.","Jos minä hudan sinun tykös, niin et sinä vastaa minua: jos minä käyn edes, niin et sinä minusta tietävinäs ole."],[30,21,"Sinä olet muuttunut minulle hirmuiseksi, ja vainoot minua kätes voimalla.","Sinä olet muuttunut minulle hirmuiseksi, ja vainoot minua kätes voimalla."],[30,22,"Sinä nostat minun tuuleen, ja annat minun ajaa sen päällä, ja sulaat minun voimallisesti.","Sinä nostat minun tuuleen, ja annat minun ajaa sen päällä, ja sulaat minun voimallisesti."],[30,23,"Sillä minä tiedän, ettäs annat minun kuolemaan, joka on se huone, joka kaikille eläville on asetettu.","Sillä minä tiedän, ettäs annat minun kuolemaan, joka on se huone, joka kaikille eläville on asetettu."],[30,24,"Ei hän kuitenkaan ojenna kättänsä luutarhaan, eikä he huuda kadotuksestansa.","Ei hän kuitenkaan ojenna kättänsä luutarhaan, eikä he huuda kadotuksestansa."],[30,25,"Minä itkin kovana aikana, ja minun sieluni armahti köyhää.","Minä itkin kovana aikana, ja minun sieluni armahti köyhää."],[30,26,"Minä odotin hyvää, ja paha tuli: minä odotin valkeutta, ja pimeys tuli.","Minä odotin hyvää, ja paha tuli: minä odotin valkeutta, ja pimeys tuli."],[30,27,"Minun sisällykseni kiehuvat lakkaamatta: Murheen aika on minun ennättänyt.","Minun sisällykseni kiehuvat lakkaamatta: Murheen aika on minun ennättänyt."],[30,28,"Minä käyn mustettuna, ehkei aurinko minua ruskoittanut: minä nousen kansan seassa ja huudan.","Minä käyn mustettuna, ehkei aurinko minua ruskoittanut: minä nousen kansan seassa ja huudan."],[30,29,"Minä olen kärmetten veli, strutsilinnun poikain kumppani.","Minä olen kärmetten veli, strutsilinnun poikain kumppani."],[30,30,"Minun nahkani minun päälläni on mustettunut, ja minun luuni ovat helteestä palaneet.","Minun nahkani minun päälläni on mustettunut, ja minun luuni ovat helteestä palaneet."],[30,31,"Minun kanteleeni on muuttunut valitukseksi, ja minun huiluni itkuksi.","Minun kanteleeni on muuttunut valitukseksi, ja minun huiluni itkuksi."],[31,1,"Minä olen tehnyt liiton silmäini kanssa, etten minä katsoisi neitseen päälle.","Minä olen tehnyt liiton silmäini kanssa, etten minä katsoisi neitseen päälle."],[31,2,"Mutta mitä Jumala ylhäältä antaa minulle osaksi ja Kaikkivaltias korkialta perinnöksi?","Mutta mitä Jumala ylhäältä antaa minulle osaksi ja Kaikkivaltias korkialta perinnöksi?"],[31,3,"Eikö väärän pitäisi näkemän senkaltaista vaivaisuutta, ja pahantekiän senkaltaista surkeutta kärsimän?","Eikö väärän pitäisi näkemän senkaltaista vaivaisuutta, ja pahantekiän senkaltaista surkeutta kärsimän?"],[31,4,"Eikö hän näe minun teitäni ja lueskele kaikkia minun askeleitani?","Eikö hän näe minun teitäni ja lueskele kaikkia minun askeleitani?"],[31,5,"Olenko minä vaeltanut turhassa menossa, eli minun jalkani kiiruhtaneet petokseen?","Olenko minä vaeltanut turhassa menossa, eli minun jalkani kiiruhtaneet petokseen?"],[31,6,"Punnitkaan hän minua oikialla vaa'alla, niin Jumala ymmärtää minun vakuuteni.","Punnitkaan hän minua oikialla vaa'alla, niin Jumala ymmärtää minun vakuuteni."],[31,7,"Jos minun askeleeni ovat poikenneet tieltä, ja minun sydämeni seurannut silmiäni, ja jotakin riippunut minun käsissäni,","Jos minun askeleeni ovat poikenneet tieltä, ja minun sydämeni seurannut silmiäni, ja jotakin riippunut minun käsissäni,"],[31,8,"Niin minä kylväisin ja toinen söis, ja minun sikiäni hukkuis juurinensa.","Niin minä kylväisin ja toinen söis, ja minun sikiäni hukkuis juurinensa."],[31,9,"Jos minun sydämeni on vietelty vaimon perään, ja olen väijynyt lähimmäiseni ovella,","Jos minun sydämeni on vietelty vaimon perään, ja olen väijynyt lähimmäiseni ovella,"],[31,10,"Niin minun emäntäni häväistäkään muilta, ja muut maatkaan hänen;","Niin minun emäntäni häväistäkään muilta, ja muut maatkaan hänen;"],[31,11,"Sillä se on häpiä ja paha työ tuomarien edessä;","Sillä se on häpiä ja paha työ tuomarien edessä;"],[31,12,"Sillä se olis tuli joka polttais kadotukseen, ja kaiken minun saatuni peräti hukuttais.","Sillä se olis tuli joka polttais kadotukseen, ja kaiken minun saatuni peräti hukuttais."],[31,13,"Jos olen katsonut ylön palveliani eli palkkapiikani oikeuden, riidellessänsä minun kanssani,","Jos olen katsonut ylön palveliani eli palkkapiikani oikeuden, riidellessänsä minun kanssani,"],[31,14,"Mitä minä sitte tekisin kuin Jumala nousee? eli mitä minä vastaisin häntä, kuin hän kostaa?","Mitä minä sitte tekisin kuin Jumala nousee? eli mitä minä vastaisin häntä, kuin hän kostaa?"],[31,15,"Eikö hän ole tehnyt häntä, joka minunkin äitini kohdussa teki? ja on meidät molemmat kohdussa valmistanut.","Eikö hän ole tehnyt häntä, joka minunkin äitini kohdussa teki? ja on meidät molemmat kohdussa valmistanut."],[31,16,"Olenko minä kieltänyt tarvitsevaisilta, mitä he minulta ovat pyytäneet, ja antanut leskein silmät heikoksi tulla?","Olenko minä kieltänyt tarvitsevaisilta, mitä he minulta ovat pyytäneet, ja antanut leskein silmät heikoksi tulla?"],[31,17,"Olenko minä syönyt palani yksinäni, ettei orpo ole myös siitä syönyt?","Olenko minä syönyt palani yksinäni, ettei orpo ole myös siitä syönyt?"],[31,18,"Sillä nuoruudestani olen minä ollut niinkuin isä, ja hamasta äitini kohdusta olen minä mielelläni holhonnut.","Sillä nuoruudestani olen minä ollut niinkuin isä, ja hamasta äitini kohdusta olen minä mielelläni holhonnut."],[31,19,"Jos minä olen nähnyt jonkun hukkuvan, ettei hänellä ollut vaatetta, ja sallinut käydä köyhän peittämättä;","Jos minä olen nähnyt jonkun hukkuvan, ettei hänellä ollut vaatetta, ja sallinut käydä köyhän peittämättä;"],[31,20,"Jos ei hänen lanteensa ole siunannut minua, kuin hän minun lammasnahoillani lämmitettiin;","Jos ei hänen lanteensa ole siunannut minua, kuin hän minun lammasnahoillani lämmitettiin;"],[31,21,"Jos olen nostanut käteni orpoja vastaan, ehkä minä näin minun voimallisena porteissa olevan;","Jos olen nostanut käteni orpoja vastaan, ehkä minä näin minun voimallisena porteissa olevan;"],[31,22,"Niin kaatukoon minun hartiani lapaluiltani, ja minun käsivarteni särkyköön luinensa.","Niin kaatukoon minun hartiani lapaluiltani, ja minun käsivarteni särkyköön luinensa."],[31,23,"Sillä Jnmalan rangaistus on minulle vavistukseksi, ja en taida hänen korkeuttansa välttää.","Sillä Jnmalan rangaistus on minulle vavistukseksi, ja en taida hänen korkeuttansa välttää."],[31,24,"Olenko minä asettanut kullan turvakseni? ja sanonut puhtaalle kullalle: sinä olet minun uskallukseni?","Olenko minä asettanut kullan turvakseni? ja sanonut puhtaalle kullalle: sinä olet minun uskallukseni?"],[31,25,"Olenko minä iloinnut tavarani paljoudesta, ja että käteni paljon riistaa koonneet ovat?","Olenko minä iloinnut tavarani paljoudesta, ja että käteni paljon riistaa koonneet ovat?"],[31,26,"Olenko minä katsonut valkeutta, koska se kirkkaasti paisti, ja kuuta, koska se täydellinen oli?","Olenko minä katsonut valkeutta, koska se kirkkaasti paisti, ja kuuta, koska se täydellinen oli?"],[31,27,"Onko minun sydämeni salaa minua vietellyt, suuta antamaan kädelleni?","Onko minun sydämeni salaa minua vietellyt, suuta antamaan kädelleni?"],[31,28,"Joka myös vääryys on tuomarien edessä; sillä niin olisin minä kieltänyt Jumalan ylhäältä.","Joka myös vääryys on tuomarien edessä; sillä niin olisin minä kieltänyt Jumalan ylhäältä."],[31,29,"Olenko minä iloinnut viholliseni vastoinkäymisestä? taikka riemuinnut, että onnettomuus tuli hänen päällensä?","Olenko minä iloinnut viholliseni vastoinkäymisestä? taikka riemuinnut, että onnettomuus tuli hänen päällensä?"],[31,30,"Sillä en minä antanut minun suuni syntiä tehdä, sadatellakseni hänen sieluansa.","Sillä en minä antanut minun suuni syntiä tehdä, sadatellakseni hänen sieluansa."],[31,31,"Eivätkö miehet, jotka minun majassani ovat, sanoisi: jospa emme hänen lihastansa ravittaisi?","Eivätkö miehet, jotka minun majassani ovat, sanoisi: jospa emme hänen lihastansa ravittaisi?"],[31,32,"Muukalaisen ei pitänyt yötä ulkona oleman; vaan vaellusväelle avasin minä oveni.","Muukalaisen ei pitänyt yötä ulkona oleman; vaan vaellusväelle avasin minä oveni."],[31,33,"Olenko minä niinkuin ihminen peittänyt minun pahuuteni, salatakseni minun vääryyttäni?","Olenko minä niinkuin ihminen peittänyt minun pahuuteni, salatakseni minun vääryyttäni?"],[31,34,"Olenko minä hämmästynyt suurta joukkoa? eli olenko minä sukulaisteni ylönkatsetta peljännyt? ollut ääneti, ja en mennyt ovesta ulos?","Olenko minä hämmästynyt suurta joukkoa? eli olenko minä sukulaisteni ylönkatsetta peljännyt? ollut ääneti, ja en mennyt ovesta ulos?"],[31,35,"Kuka antais minulle kuultelian, että Kaikkivaltias kuulis minun pyyntöni, että joku kirjoittais kirjan minun asiastani;","Kuka antais minulle kuultelian, että Kaikkivaltias kuulis minun pyyntöni, että joku kirjoittais kirjan minun asiastani;"],[31,36,"Niin minä ottaisin sen hartioilleni, ja sitoisin ympärilleni niinkuin kruunun.","Niin minä ottaisin sen hartioilleni, ja sitoisin ympärilleni niinkuin kruunun."],[31,37,"Minä ilmoittaisin hänelle minun askeleini luvun, ja niinkuin ruhtinas kantaisin sen edes.","Minä ilmoittaisin hänelle minun askeleini luvun, ja niinkuin ruhtinas kantaisin sen edes."],[31,38,"Jos minun maani huutais minua vastaan, ja sen vaot kaikki ynnä itkisivät;","Jos minun maani huutais minua vastaan, ja sen vaot kaikki ynnä itkisivät;"],[31,39,"Jos minä olen sen hedelmän maksamatta syönyt, ja tehnyt peltomiesten elämän työlääksi;","Jos minä olen sen hedelmän maksamatta syönyt, ja tehnyt peltomiesten elämän työlääksi;"],[31,40,"Niin kasvakoon minulle nisuista orjantappuria ja ohrista pahoja ruohoja. Jobin sanat loppuvat.","Niin kasvakoon minulle nisuista orjantappuria ja ohrista pahoja ruohoja. Jobin sanat loppuvat."],[32,1,"Niin ne kolme miestä lakkasivat vastaamasta Jobia, että hän piti itsensä hurskaana.","Niin ne kolme miestä lakkasivat vastaamasta Jobia, että hän piti itsensä hurskaana."],[32,2,"Mutta Elihu Barakelin poika Busista, Ramin sukukunnasta, vihastui Jobin päälle, että hän piti sielunsa hurskaampana Jumalaa,","Mutta Elihu Barakelin poika Busista, Ramin sukukunnasta, vihastui Jobin päälle, että hän piti sielunsa hurskaampana Jumalaa,"],[32,3,"Ja närkästyi kolmen ystävänsä päälle, ettei he mitään vastausta löytäneet, ja kuitenkin tuomitsivat Jobin.","Ja närkästyi kolmen ystävänsä päälle, ettei he mitään vastausta löytäneet, ja kuitenkin tuomitsivat Jobin."],[32,4,"Sillä Elihu odotti niinkauvan kuin he puhuivat Jobin kanssa, että he olivat vanhemmat häntä.","Sillä Elihu odotti niinkauvan kuin he puhuivat Jobin kanssa, että he olivat vanhemmat häntä."],[32,5,"Kuin Elihu näki, ettei vastausta ollut kolmen miehen suussa, vihastui hän.","Kuin Elihu näki, ettei vastausta ollut kolmen miehen suussa, vihastui hän."],[32,6,"Ja näin vastasi Elihu Barakelin poika Busista ja sanoi: minä olen nuori, ja te olette vanhat, sentähden minä häpesin ja pelkäsin osoittaa teille minun taitoani.","Ja näin vastasi Elihu Barakelin poika Busista ja sanoi: minä olen nuori, ja te olette vanhat, sentähden minä häpesin ja pelkäsin osoittaa teille minun taitoani."],[32,7,"Minä ajattelin: puhukaan vuodet, ja vanhuus osoittakoon taitonsa.","Minä ajattelin: puhukaan vuodet, ja vanhuus osoittakoon taitonsa."],[32,8,"Mutta henki on ihmisessä; ja Kaikkivaltiaan henki tekee hänen ymmärtäväiseksi.","Mutta henki on ihmisessä; ja Kaikkivaltiaan henki tekee hänen ymmärtäväiseksi."],[32,9,"Suuret ei ole taitavimmat, eikä vanhat ymmärrä, mikä oikeus on.","Suuret ei ole taitavimmat, eikä vanhat ymmärrä, mikä oikeus on."],[32,10,"Sentähden minäkin puhun. Kuulkaat minua: minäkin osoitan tietoni.","Sentähden minäkin puhun. Kuulkaat minua: minäkin osoitan tietoni."],[32,11,"Katso, minä olen odottanut teidän puhuissanne, minä olen ottanut teidän ymmärryksestänne vaarin, siihenasti että te olisitte osanneet oikeuden.","Katso, minä olen odottanut teidän puhuissanne, minä olen ottanut teidän ymmärryksestänne vaarin, siihenasti että te olisitte osanneet oikeuden."],[32,12,"Ja minä olen ottanut teistä vaarin; ja katso, ei ole yksikään teistä Jobia nuhdellen voittanut, eli hänen sanaansa vastata taitanut.","Ja minä olen ottanut teistä vaarin; ja katso, ei ole yksikään teistä Jobia nuhdellen voittanut, eli hänen sanaansa vastata taitanut."],[32,13,"Ettette sanoisi: me olemme löytäneet taidon; että Jumala on hänen hyljännyt, ja ei yksikään muu.","Ettette sanoisi: me olemme löytäneet taidon; että Jumala on hänen hyljännyt, ja ei yksikään muu."],[32,14,"Sillä ei hän ole minua vastaan puhunut, enkä minä vastaa häntä niinkuin te puhuitte.","Sillä ei hän ole minua vastaan puhunut, enkä minä vastaa häntä niinkuin te puhuitte."],[32,15,"He pelkäävät, ja ei taida silleen mitään vastata, eikä mitään puhua.","He pelkäävät, ja ei taida silleen mitään vastata, eikä mitään puhua."],[32,16,"Että minä olen odottanut, ja ei he taida mitään puhua; vaan he vaikenivat, ja ei enää vastaa mitään.","Että minä olen odottanut, ja ei he taida mitään puhua; vaan he vaikenivat, ja ei enää vastaa mitään."],[32,17,"Niin minä vastaan kuitenkin osani, ja osoitan tietoni.","Niin minä vastaan kuitenkin osani, ja osoitan tietoni."],[32,18,"Sillä minä olen niin täynnä sanoja, että minun henkeni ahdistaa minun vatsaani.","Sillä minä olen niin täynnä sanoja, että minun henkeni ahdistaa minun vatsaani."],[32,19,"Katso, minun vatsani on niinkuin viina, jonka henki ei avattu ole, joka uudet leilit särkee.","Katso, minun vatsani on niinkuin viina, jonka henki ei avattu ole, joka uudet leilit särkee."],[32,20,"Minun täytyy puhua, että minä saisin henkeni vetää: minun täytyy avata huuleni ja vastata.","Minun täytyy puhua, että minä saisin henkeni vetää: minun täytyy avata huuleni ja vastata."],[32,21,"En minä muotoa katso, enkä ihmisen mielen perään puhu.","En minä muotoa katso, enkä ihmisen mielen perään puhu."],[32,22,"Sillä en minä tiedä (jos minä niin teen), että minun Luojani tempaa äkisti minun pois.","Sillä en minä tiedä (jos minä niin teen), että minun Luojani tempaa äkisti minun pois."],[33,1,"Kuule siis, Job, minun puhettani, ja ota vaari kaikista sanoistani!","Kuule siis, Job, minun puhettani, ja ota vaari kaikista sanoistani!"],[33,2,"Katso, minä avaan suuni, ja kieleni puhuu minun suussani.","Katso, minä avaan suuni, ja kieleni puhuu minun suussani."],[33,3,"Minun sydämeni puhuu oikeuden, ja minun huuleni sanoo puhtaan ymmärryksen.","Minun sydämeni puhuu oikeuden, ja minun huuleni sanoo puhtaan ymmärryksen."],[33,4,"Jumalan henki on tehnyt minun, ja KaikkivaItiaan henki on minulle antanut elämän.","Jumalan henki on tehnyt minun, ja KaikkivaItiaan henki on minulle antanut elämän."],[33,5,"Jos taidat, niin vastaa minua; valmista itses, ja tule minun eteeni.","Jos taidat, niin vastaa minua; valmista itses, ja tule minun eteeni."],[33,6,"Katso, minä olen Jumalan oma niinkuin sinäkin, ja savesta olen minä myös tehty.","Katso, minä olen Jumalan oma niinkuin sinäkin, ja savesta olen minä myös tehty."],[33,7,"Katso, ei sinun tarvitse hämmästyä minua, ja minun käteni ei ole sinulle raskas.","Katso, ei sinun tarvitse hämmästyä minua, ja minun käteni ei ole sinulle raskas."],[33,8,"Sinä olet puhunut minun korvaini kuullen: sinun ääntäs täytyy minun kuulla:","Sinä olet puhunut minun korvaini kuullen: sinun ääntäs täytyy minun kuulla:"],[33,9,"Minä olen puhdas ja ilman laitosta, viatoin ja synnitöin.","Minä olen puhdas ja ilman laitosta, viatoin ja synnitöin."],[33,10,"Katso, hän on löytänyt syyn minua vastaan, sentähden pitää hän minun vihollisenansa.","Katso, hän on löytänyt syyn minua vastaan, sentähden pitää hän minun vihollisenansa."],[33,11,"Hän on pannut minun jalkani jalkapuuhun, ja kätkenyt minun tieni.","Hän on pannut minun jalkani jalkapuuhun, ja kätkenyt minun tieni."],[33,12,"Katso, juuri siitä minä päätän, ettes ole hurskas; sillä Jumala on suurempi kuin yksikään ihminen.","Katso, juuri siitä minä päätän, ettes ole hurskas; sillä Jumala on suurempi kuin yksikään ihminen."],[33,13,"Miksis riitelet hänen kanssansa, ettei hän tee sinulle lukua kaikista töistänsä?","Miksis riitelet hänen kanssansa, ettei hän tee sinulle lukua kaikista töistänsä?"],[33,14,"Jos Jumala vihdoin jotakin käskee, ei hän sitä jälistä ajattele.","Jos Jumala vihdoin jotakin käskee, ei hän sitä jälistä ajattele."],[33,15,"Uninäössä yöllä, kuin uni tulee ihmisten päälle, kuin he makaavat vuoteessa,","Uninäössä yöllä, kuin uni tulee ihmisten päälle, kuin he makaavat vuoteessa,"],[33,16,"Silloin hän ilmoittaa ihmisten korviin, ja vahvistaa sen heidän nuhtelemisellansa,","Silloin hän ilmoittaa ihmisten korviin, ja vahvistaa sen heidän nuhtelemisellansa,"],[33,17,"Kääntääksensä ihmistä aivoituksestansa, ja varjellaksensa ylpeydestä.","Kääntääksensä ihmistä aivoituksestansa, ja varjellaksensa ylpeydestä."],[33,18,"Hän säästää hänen sieluansa turmeluksesta, ja hänen elämäänsä, ettei se miekkaan lankeaisi.","Hän säästää hänen sieluansa turmeluksesta, ja hänen elämäänsä, ettei se miekkaan lankeaisi."],[33,19,"Ja kurittaa häntä kivulla vuoteessansa, ja kaikki hänen luunsa väkevällä kivulla,","Ja kurittaa häntä kivulla vuoteessansa, ja kaikki hänen luunsa väkevällä kivulla,"],[33,20,"Ja niin toimittaa hänen kauhistumaan ruokaa, ja hänen mielensä kyylyttämään ravintoa;","Ja niin toimittaa hänen kauhistumaan ruokaa, ja hänen mielensä kyylyttämään ravintoa;"],[33,21,"Että hänen lihansa surkastuu, niin ettei sitä nähdä, ja hänen luunsa särkyvät, niin ettei niitä mielellä katsella;","Että hänen lihansa surkastuu, niin ettei sitä nähdä, ja hänen luunsa särkyvät, niin ettei niitä mielellä katsella;"],[33,22,"Että hänen sielunsa lähenee turmelusta, ja hänen elämänsä kuolemaa.","Että hänen sielunsa lähenee turmelusta, ja hänen elämänsä kuolemaa."],[33,23,"Kuin siis hänen tykönsä tulee enkeli, välimies, joka ainoa on enempi tuhansia, ilmoittamaan sille ihmiselle vanhurskauttansa,","Kuin siis hänen tykönsä tulee enkeli, välimies, joka ainoa on enempi tuhansia, ilmoittamaan sille ihmiselle vanhurskauttansa,"],[33,24,"Ja armahtaa häntä, ja sanoo: pelasta häntä menemästä alas turmelukseen; sillä minä olen löytänyt sovinnon;","Ja armahtaa häntä, ja sanoo: pelasta häntä menemästä alas turmelukseen; sillä minä olen löytänyt sovinnon;"],[33,25,"Niin hänen lihansa tuorehtii enemmin kuin lapsuudessa ja tulee taas niinkuin nuoruutensa aikana.","Niin hänen lihansa tuorehtii enemmin kuin lapsuudessa ja tulee taas niinkuin nuoruutensa aikana."],[33,26,"Hän rukoilee Jumalaa, joka hänelle osoittaa armon: hän antaa kasvonsa nähdä ilolla, ja maksaa ihmiselle hänen vanhurskautensa.","Hän rukoilee Jumalaa, joka hänelle osoittaa armon: hän antaa kasvonsa nähdä ilolla, ja maksaa ihmiselle hänen vanhurskautensa."],[33,27,"Hän tunnustaa ihmiselle ja sanoo: minä olen syntiä tehnyt ja oikeuden vääntänyt; vaan ei se minua auttanut.","Hän tunnustaa ihmiselle ja sanoo: minä olen syntiä tehnyt ja oikeuden vääntänyt; vaan ei se minua auttanut."],[33,28,"Hän pelasti minun sieluni, ettei se tulisi turmelukseen, vaan että minun elämäni näkis valkeuden.","Hän pelasti minun sieluni, ettei se tulisi turmelukseen, vaan että minun elämäni näkis valkeuden."],[33,29,"Katso, nämät kaikki tekee Jumala itsekullekin kolme kertaa,","Katso, nämät kaikki tekee Jumala itsekullekin kolme kertaa,"],[33,30,"Tuodaksensa heidän sielunsa jälleen turmeluksesta ja valaistaksensa elävien valkeudella.","Tuodaksensa heidän sielunsa jälleen turmeluksesta ja valaistaksensa elävien valkeudella."],[33,31,"Job, ota tästä vaari ja kuule, ole myös ääneti, että minä puhuisin!","Job, ota tästä vaari ja kuule, ole myös ääneti, että minä puhuisin!"],[33,32,"Mutta jos sinulla on jotakin puhumista, niin vastaa minua. Puhu! sillä minä tahdon, ettäs olisit vanhurskas.","Mutta jos sinulla on jotakin puhumista, niin vastaa minua. Puhu! sillä minä tahdon, ettäs olisit vanhurskas."],[33,33,"Jos ei, niin kuule sinä minua, ja ole ääneti; minä opetan sinulle taidon.","Jos ei, niin kuule sinä minua, ja ole ääneti; minä opetan sinulle taidon."],[34,1,"Ja Elihu vielä sanoi:","Ja Elihu vielä sanoi:"],[34,2,"Te taitavat, kuulkaat minun puhettani, ja te ymmärtäväiset, ottakaat korviinne.","Te taitavat, kuulkaat minun puhettani, ja te ymmärtäväiset, ottakaat korviinne."],[34,3,"Sillä korva koettelee puheen, ja suu maistaa ruan.","Sillä korva koettelee puheen, ja suu maistaa ruan."],[34,4,"Valitkaamme meillemme oikeus, tietääksemme keskenämme, mikä hyvä on.","Valitkaamme meillemme oikeus, tietääksemme keskenämme, mikä hyvä on."],[34,5,"Sillä Job on sanonut: minä olen hurskas, ja Jumala on kieltänyt minulta oikeuteni.","Sillä Job on sanonut: minä olen hurskas, ja Jumala on kieltänyt minulta oikeuteni."],[34,6,"Minun täytyy valhetella, ehkä minulla vielä oikeus olis: minä vaivataan ilman ansiota minun nuoliltani.","Minun täytyy valhetella, ehkä minulla vielä oikeus olis: minä vaivataan ilman ansiota minun nuoliltani."],[34,7,"Kuka on Jobin vertainen, joka irvistystä juo niinkuin vettä,","Kuka on Jobin vertainen, joka irvistystä juo niinkuin vettä,"],[34,8,"Ja käy pahantekiäin kanssa tiellä, niin että vaeltaa jumalattomain kanssa?","Ja käy pahantekiäin kanssa tiellä, niin että vaeltaa jumalattomain kanssa?"],[34,9,"Sillä hän on sanonut: Ei se auta ihmistä, että hän pyytää Jumalalle kelvata.","Sillä hän on sanonut: Ei se auta ihmistä, että hän pyytää Jumalalle kelvata."],[34,10,"Sentähden, te toimelliset, kuulkaat minua. Pois se, että Jumala olis jumalatoin ja Kaikkivaltias väärä.","Sentähden, te toimelliset, kuulkaat minua. Pois se, että Jumala olis jumalatoin ja Kaikkivaltias väärä."],[34,11,"Sillä hän antaa itsekullekin ihmiselle ansionsa jälkeen, ja maksaa tiensä jälkeen.","Sillä hän antaa itsekullekin ihmiselle ansionsa jälkeen, ja maksaa tiensä jälkeen."],[34,12,"Ilman epäilemätä, ei Jumala tuomitse ketään vääryydellä, eikä Kaikkivaltias käännä oikeutta.","Ilman epäilemätä, ei Jumala tuomitse ketään vääryydellä, eikä Kaikkivaltias käännä oikeutta."],[34,13,"Kuka on asettanut ne mitkä maan päällä ovat, ja kuka on pannut koko maanpiirin?","Kuka on asettanut ne mitkä maan päällä ovat, ja kuka on pannut koko maanpiirin?"],[34,14,"Jos hän tahtois, niin hän vois kaikkein hengen ja elämän koota tykönsä.","Jos hän tahtois, niin hän vois kaikkein hengen ja elämän koota tykönsä."],[34,15,"Kaikki liha kuolis yhteen, ja ihminen tulis tuhaksi jälleen.","Kaikki liha kuolis yhteen, ja ihminen tulis tuhaksi jälleen."],[34,16,"Onko sinulla ymmärrystä, niin kuule näitä, ja ota vaari puheeni äänestä.","Onko sinulla ymmärrystä, niin kuule näitä, ja ota vaari puheeni äänestä."],[34,17,"Taivuttaisko joku sentähden oikeuden, että hän vihaa häntä, ja tahtoisitkos hurskaan ja jalon tuomita jumalattomaksi?","Taivuttaisko joku sentähden oikeuden, että hän vihaa häntä, ja tahtoisitkos hurskaan ja jalon tuomita jumalattomaksi?"],[34,18,"Pitäiskö sanottaman kuninkaalle: sinä Belial! ja ruhtinaille: te jumalattomat!","Pitäiskö sanottaman kuninkaalle: sinä Belial! ja ruhtinaille: te jumalattomat!"],[34,19,"Joka ei kuitenkaan katso ruhtinain muotoa, eikä pidä eroitusta rikkaan ja köyhän välillä; sillä he ovat kaikki hänen käsialansa.","Joka ei kuitenkaan katso ruhtinain muotoa, eikä pidä eroitusta rikkaan ja köyhän välillä; sillä he ovat kaikki hänen käsialansa."],[34,20,"Pikaisesti täytyy heidän kuolla vielä puoliyönäkin: kansan täytyy hämmästyä ja hukkua: väkevä voimatoinna otetaan pois.","Pikaisesti täytyy heidän kuolla vielä puoliyönäkin: kansan täytyy hämmästyä ja hukkua: väkevä voimatoinna otetaan pois."],[34,21,"Sillä hänen silmänsä näkevät jokaisen tien, ja hän katsoo kaikki heidän askeleensa.","Sillä hänen silmänsä näkevät jokaisen tien, ja hän katsoo kaikki heidän askeleensa."],[34,22,"Ei pimiä eikä kuoleman varjo ole siellä, että pahantekiät itsensä siinä salaisivat.","Ei pimiä eikä kuoleman varjo ole siellä, että pahantekiät itsensä siinä salaisivat."],[34,23,"Sillä ei ole yhdellekään sallittu, että hän tulis Jumalan kanssa oikeudelle.","Sillä ei ole yhdellekään sallittu, että hän tulis Jumalan kanssa oikeudelle."],[34,24,"Hän musertaa monta epälukuista tuimaa, ja asettaa muita heidän siaansa;","Hän musertaa monta epälukuista tuimaa, ja asettaa muita heidän siaansa;"],[34,25,"Että hän tuntee heidän työnsä, ja kukistaa heitä yöllä, että he muserretaan rikki.","Että hän tuntee heidän työnsä, ja kukistaa heitä yöllä, että he muserretaan rikki."],[34,26,"Hän heittää jumalattomat ilmeisesti kokoon,","Hän heittää jumalattomat ilmeisesti kokoon,"],[34,27,"Ettei he häntä seuranneet, ja ei tahtoneet ymmärtää hänen teitänsä;","Ettei he häntä seuranneet, ja ei tahtoneet ymmärtää hänen teitänsä;"],[34,28,"Että vaivaisten hunto tulis hänen eteensä ja hän kuulis viheliäisten huudon.","Että vaivaisten hunto tulis hänen eteensä ja hän kuulis viheliäisten huudon."],[34,29,"Jos hän antaa rauhan, kuka tahtoo kadottaa? ja jos hän peittää kasvonsa, kuka taitaa katsoa hänen päällensä, kansan ja ihmisten seassa?","Jos hän antaa rauhan, kuka tahtoo kadottaa? ja jos hän peittää kasvonsa, kuka taitaa katsoa hänen päällensä, kansan ja ihmisten seassa?"],[34,30,"Niin ei hän anna ulkokullatun hallita, kansan lankeemuksen tähden.","Niin ei hän anna ulkokullatun hallita, kansan lankeemuksen tähden."],[34,31,"Minä puhun Jumalan edessä, joka sanoo: minä olen säästänyt, en minä turmele.","Minä puhun Jumalan edessä, joka sanoo: minä olen säästänyt, en minä turmele."],[34,32,"Ellen minä ole osannut, niin opeta sinä minua: jos minä olen tehnyt väärin, niin en minä sitä silleen tee.","Ellen minä ole osannut, niin opeta sinä minua: jos minä olen tehnyt väärin, niin en minä sitä silleen tee."],[34,33,"Onko joku, joka vastaa sinun puolestas, koska et sinä tahdo? se on sinun ehdossas, ja ei minun. Jos sinä nyt jotakin tiedät,niin puhu.","Onko joku, joka vastaa sinun puolestas, koska et sinä tahdo? se on sinun ehdossas, ja ei minun. Jos sinä nyt jotakin tiedät,niin puhu."],[34,34,"Toimellisten miesten sallin minä kyllä puhua minulleni. Ja taitava mies kuulee minua.","Toimellisten miesten sallin minä kyllä puhua minulleni. Ja taitava mies kuulee minua."],[34,35,"Mutta Job puhuu tyhmästi, ja hänen puheessansa ei ole ymmärrystä.","Mutta Job puhuu tyhmästi, ja hänen puheessansa ei ole ymmärrystä."],[34,36,"Minun isäni! anna Jobia koeteltaa loppuun asti, että hän kääntää itsensä vääräin ihmisten tykö.","Minun isäni! anna Jobia koeteltaa loppuun asti, että hän kääntää itsensä vääräin ihmisten tykö."],[34,37,"Hän on paitsi entisiä syntejänsä vielä nyt pilkannut: anna hänen meidän edessämme lyödyksi tulla, ja sitte hän riidelkään kyllä sanoillansa Jumalan edessä.","Hän on paitsi entisiä syntejänsä vielä nyt pilkannut: anna hänen meidän edessämme lyödyksi tulla, ja sitte hän riidelkään kyllä sanoillansa Jumalan edessä."],[35,1,"Ja Elihu vastasi ja sanoi:","Ja Elihu vastasi ja sanoi:"],[35,2,"Luuletkos sen oikiaksi, ettäs sanot: minä olen hurskaampi Jumalaa?","Luuletkos sen oikiaksi, ettäs sanot: minä olen hurskaampi Jumalaa?"],[35,3,"Sillä sinä sanot: mitä siitä hyvää on, mitä se auttaa, jos joku välttää syntiä?","Sillä sinä sanot: mitä siitä hyvää on, mitä se auttaa, jos joku välttää syntiä?"],[35,4,"Minä vastaan sinua sanoilla, ja sinun ystäviäs sinun kanssas.","Minä vastaan sinua sanoilla, ja sinun ystäviäs sinun kanssas."],[35,5,"Katso taivaasen ja näe, ja katso pilviin, että ne ovat korkiammat sinua.","Katso taivaasen ja näe, ja katso pilviin, että ne ovat korkiammat sinua."],[35,6,"Jos sinä syntiä teet, mitäs taidat hänelle tehdä? ja jos sinun pahuutes on suuri, mitäs taidat hänelle tehdä?","Jos sinä syntiä teet, mitäs taidat hänelle tehdä? ja jos sinun pahuutes on suuri, mitäs taidat hänelle tehdä?"],[35,7,"Ja jos sinä olet hurskas, mitäs taidat hänelle antaa? eli mitä hän ottaa sinun kädestäs?","Ja jos sinä olet hurskas, mitäs taidat hänelle antaa? eli mitä hän ottaa sinun kädestäs?"],[35,8,"Ihmiselle sinun kaltaiselles tekee sinun pahuutes jotakin, ja ihmisen lapselle sinun hurskautes.","Ihmiselle sinun kaltaiselles tekee sinun pahuutes jotakin, ja ihmisen lapselle sinun hurskautes."],[35,9,"Ne huutavat, kuin heille paljo väkivaltaa tapahtuu, ja valittavat voimallisten käsivartta,","Ne huutavat, kuin heille paljo väkivaltaa tapahtuu, ja valittavat voimallisten käsivartta,"],[35,10,"Jotka ei sano: Kussa on Jumala, minun Luojani, joka yöllä tekee virret?","Jotka ei sano: Kussa on Jumala, minun Luojani, joka yöllä tekee virret?"],[35,11,"Joka meitä tekee oppineemmaksi eläimiä maan päällä, ja taitavammaksi taivaan lintuja.","Joka meitä tekee oppineemmaksi eläimiä maan päällä, ja taitavammaksi taivaan lintuja."],[35,12,"Mutta he valittavat pahain ylpeyttä; ja ei hän kuule heitä.","Mutta he valittavat pahain ylpeyttä; ja ei hän kuule heitä."],[35,13,"Sillä ei jumala kuule turhaa, ja Kaikkivaltias ei katso sitä.","Sillä ei jumala kuule turhaa, ja Kaikkivaltias ei katso sitä."],[35,14,"Nyt sinä sanot: et sinä näe häntä; mutta tuomio on hänen edessänsä, vaan odota häntä.","Nyt sinä sanot: et sinä näe häntä; mutta tuomio on hänen edessänsä, vaan odota häntä."],[35,15,"Jos ei hänen vihansa niin äkisti kosta, ja ei ole tietävinänsä, että siinä niin monta rikosta on;","Jos ei hänen vihansa niin äkisti kosta, ja ei ole tietävinänsä, että siinä niin monta rikosta on;"],[35,16,"Sentähden on Job turhaan suunsa avannut ja taitamattomia puheita puhunut.","Sentähden on Job turhaan suunsa avannut ja taitamattomia puheita puhunut."],[36,1,"Elihu puhui vielä ja sanoi:","Elihu puhui vielä ja sanoi:"],[36,2,"Odota vielä vähä, minä osoitan sinulle sen; sillä minulla on vielä nyt jotakin Jumalan puolesta sanomista.","Odota vielä vähä, minä osoitan sinulle sen; sillä minulla on vielä nyt jotakin Jumalan puolesta sanomista."],[36,3,"Minä tuon minun ymmärrykseni kaukaa, ja osoitan, että minun Luojani on hurskas.","Minä tuon minun ymmärrykseni kaukaa, ja osoitan, että minun Luojani on hurskas."],[36,4,"Sillä minun puheessani ei tosin ole petosta, minun ymmärrykseni on vilpitöin sinun edessäs.","Sillä minun puheessani ei tosin ole petosta, minun ymmärrykseni on vilpitöin sinun edessäs."],[36,5,"Katso, Jumala on voimallinen, ei kuitenkaan hän ketään hylkää: Hän on voimallinen sydämensä väestä.","Katso, Jumala on voimallinen, ei kuitenkaan hän ketään hylkää: Hän on voimallinen sydämensä väestä."],[36,6,"Jumalatointa ei hän varjele, vaan auttaa köyhää oikeuteen.","Jumalatointa ei hän varjele, vaan auttaa köyhää oikeuteen."],[36,7,"Ei hän käännä silmiänsä pois hurskaasta: hän on myös kuningasten kanssa istuimella: hän antaa heidän pysyä alinomati, että he korkiaksi tulevat.","Ei hän käännä silmiänsä pois hurskaasta: hän on myös kuningasten kanssa istuimella: hän antaa heidän pysyä alinomati, että he korkiaksi tulevat."],[36,8,"Ja ehkä vangit olisivat jalkapuussa, ja sidottuna surkeuden köysillä:","Ja ehkä vangit olisivat jalkapuussa, ja sidottuna surkeuden köysillä:"],[36,9,"Niin hän ilmoittaa heille heidän työnsä ja rikoksensa, että he ovat tehneet väkivaltaa,","Niin hän ilmoittaa heille heidän työnsä ja rikoksensa, että he ovat tehneet väkivaltaa,"],[36,10,"Ja avaa heidän korvansa kuritukseen, ja sanoo heille, että he kääntyisivät pois vääryydestä.","Ja avaa heidän korvansa kuritukseen, ja sanoo heille, että he kääntyisivät pois vääryydestä."],[36,11,"Jos he kuulevat ja palvelevat häntä, niin he hyvissä päivissä vanhenevat ja ilolla elävät.","Jos he kuulevat ja palvelevat häntä, niin he hyvissä päivissä vanhenevat ja ilolla elävät."],[36,12,"Jos ei he kuule, niin he kaatuvat miekalla, ja hukkuvat ennenkuin he sen havaitsevat.","Jos ei he kuule, niin he kaatuvat miekalla, ja hukkuvat ennenkuin he sen havaitsevat."],[36,13,"Ulkokullatut kartuttavat vihan: ei he huuda, kuin he vankina ovat;","Ulkokullatut kartuttavat vihan: ei he huuda, kuin he vankina ovat;"],[36,14,"Niin heidän sielunsa kuolee nuoruudessa, ja heidän elämänsä huorintekiäin seassa.","Niin heidän sielunsa kuolee nuoruudessa, ja heidän elämänsä huorintekiäin seassa."],[36,15,"Mutta vaivaista auttaa hän vaivaisuudessa, ja avaa köyhäin korvan murheessa.","Mutta vaivaista auttaa hän vaivaisuudessa, ja avaa köyhäin korvan murheessa."],[36,16,"Hän tempaa sinunkin ahdistuksen kidasta avaruuteen, jolla ei pohjaa ole; ja sinun pöydälläs on lepo, täytetty kaikella hyvällä.","Hän tempaa sinunkin ahdistuksen kidasta avaruuteen, jolla ei pohjaa ole; ja sinun pöydälläs on lepo, täytetty kaikella hyvällä."],[36,17,"Ja sinä olet täydellisesti havaitseva jumalattoman tuomion; mutta tuomio ja oikeus vahvistaa sinun.","Ja sinä olet täydellisesti havaitseva jumalattoman tuomion; mutta tuomio ja oikeus vahvistaa sinun."],[36,18,"Katso, ettei viha ole vietellyt sinua voimassas, eli suuret lahjat ole kääntäneet sinua.","Katso, ettei viha ole vietellyt sinua voimassas, eli suuret lahjat ole kääntäneet sinua."],[36,19,"Luuletkos hänen huolivan jalouttas, kultaa eli jonkun väkevyyttä ja varaa?","Luuletkos hänen huolivan jalouttas, kultaa eli jonkun väkevyyttä ja varaa?"],[36,20,"Ei sinun tarvitse ikävöidä yötä, karatakses ihmisten päälle siallansa.","Ei sinun tarvitse ikävöidä yötä, karatakses ihmisten päälle siallansa."],[36,21,"Kavahda sinuas, ja älä käännä sinuas vääryyteen, niikuin sinä surkeuden tähden ruvennut olet.","Kavahda sinuas, ja älä käännä sinuas vääryyteen, niikuin sinä surkeuden tähden ruvennut olet."],[36,22,"Katso, Jumala on korkia voimassansa: kuka on senkaltainen opettaja kuin hän on?","Katso, Jumala on korkia voimassansa: kuka on senkaltainen opettaja kuin hän on?"],[36,23,"Kuka tutkii hänen tiensä? ja kuka sanoo hänelle: sinä teet väärin?","Kuka tutkii hänen tiensä? ja kuka sanoo hänelle: sinä teet väärin?"],[36,24,"Muista, ettäs ylistät hänen töitänsä, niinkuin ihmiset veisaavat.","Muista, ettäs ylistät hänen töitänsä, niinkuin ihmiset veisaavat."],[36,25,"Sillä kaikki ihmiset sen nähneet ovat: Ihmiset näkevät sen kaukaa.","Sillä kaikki ihmiset sen nähneet ovat: Ihmiset näkevät sen kaukaa."],[36,26,"Katso, Jumala on suuri, ja emme tiedä sitä: hänen vuosilukunsa ovat arvaamattomat.","Katso, Jumala on suuri, ja emme tiedä sitä: hänen vuosilukunsa ovat arvaamattomat."],[36,27,"Sillä hän tekee veden pieniksi pisaroiksi, ja ajaa pilvensä kokoon sateeksi,","Sillä hän tekee veden pieniksi pisaroiksi, ja ajaa pilvensä kokoon sateeksi,"],[36,28,"Että pilvet pisaroitsevat ja vuotavat vahvasti ihmisten päälle.","Että pilvet pisaroitsevat ja vuotavat vahvasti ihmisten päälle."],[36,29,"Koska hän aikoo hajoittaa pilvensä ja majansa jylinän.","Koska hän aikoo hajoittaa pilvensä ja majansa jylinän."],[36,30,"Katso, niin hän levittää valkeutensa sen päälle, ja peittää meren syvyyden.","Katso, niin hän levittää valkeutensa sen päälle, ja peittää meren syvyyden."],[36,31,"Sillä näillä tuomitsee hän kansan; ja antaa ruokaa runsaasti.","Sillä näillä tuomitsee hän kansan; ja antaa ruokaa runsaasti."],[36,32,"Hän kätkee valkeuden käsissänsä, ja käskee sen palata.","Hän kätkee valkeuden käsissänsä, ja käskee sen palata."],[36,33,"Sen ilmoittaa hänen lähimmäisensä, joka on pitkäisen viha pilvissä.","Sen ilmoittaa hänen lähimmäisensä, joka on pitkäisen viha pilvissä."],[37,1,"Siitä myös hämmästyy minun sydämeni ja vapisee.","Siitä myös hämmästyy minun sydämeni ja vapisee."],[37,2,"Kuulkaat visusti hänen vihansa huutoa, ja puhetta, joka hänen suustansa käy ulos.","Kuulkaat visusti hänen vihansa huutoa, ja puhetta, joka hänen suustansa käy ulos."],[37,3,"Hän toimittaa sen oikeuden kaikkein taivasten alla; ja hänen leimauksensa paistaa maan ääristä.","Hän toimittaa sen oikeuden kaikkein taivasten alla; ja hänen leimauksensa paistaa maan ääristä."],[37,4,"Senjälkeen kuuluu pitkäisen jylinä, ja se jylisee suurella äänellä; ja koska hänen jylinänsä kuullaan, ei sitä taideta estää.","Senjälkeen kuuluu pitkäisen jylinä, ja se jylisee suurella äänellä; ja koska hänen jylinänsä kuullaan, ei sitä taideta estää."],[37,5,"Jumala jylistää pauhinallansa ihmeellisesti, ja tekee suuria ja tutkimattomia töitä.","Jumala jylistää pauhinallansa ihmeellisesti, ja tekee suuria ja tutkimattomia töitä."],[37,6,"Hän puhuu lumelle, ja se kohta tulee maan päälle, ja sadekuurolle, ja niin sadekuurolla on voima.","Hän puhuu lumelle, ja se kohta tulee maan päälle, ja sadekuurolle, ja niin sadekuurolla on voima."],[37,7,"Hänen kädessänsä ovat kaikki ihmiset kätketyt, että kaikki tuntisivat hänen tekonsa.","Hänen kädessänsä ovat kaikki ihmiset kätketyt, että kaikki tuntisivat hänen tekonsa."],[37,8,"Metsän pedot pakenevat varjoon ja pysyvät asumapaikoissansa.","Metsän pedot pakenevat varjoon ja pysyvät asumapaikoissansa."],[37,9,"Etelästä tulee tuulispää ja pohjasta kylmä.","Etelästä tulee tuulispää ja pohjasta kylmä."],[37,10,"Jumalan hengestä tulee pakkanen ja ahdistaa laviat vedet.","Jumalan hengestä tulee pakkanen ja ahdistaa laviat vedet."],[37,11,"Seijes myös hajoittaa pilvet, ja hänen valkeutensa levittää itsensä pilvien lävitse.","Seijes myös hajoittaa pilvet, ja hänen valkeutensa levittää itsensä pilvien lävitse."],[37,12,"Hän kääntää pilvensä kuhunka hän tahtoo, tekemään kaikkia, mitä hän tahtoo maan piirin päällä.","Hän kääntää pilvensä kuhunka hän tahtoo, tekemään kaikkia, mitä hän tahtoo maan piirin päällä."],[37,13,"Jos se tapahtuu yhdelle sukukunnalle eli maakunnalle, koska hän löydetään laupiaaksi.","Jos se tapahtuu yhdelle sukukunnalle eli maakunnalle, koska hän löydetään laupiaaksi."],[37,14,"Kuules näitä Job: seiso ja ota vaari Jumalan ihmeellisistä töistä.","Kuules näitä Job: seiso ja ota vaari Jumalan ihmeellisistä töistä."],[37,15,"Tiedätkös, koska Jumala saattaa nämät heidän päällensä, ja koska hän antaa pilviensä valkeuden paistaa?","Tiedätkös, koska Jumala saattaa nämät heidän päällensä, ja koska hän antaa pilviensä valkeuden paistaa?"],[37,16,"Tiedätkös, kuinka pilvet hajoittavat heitänsä? täydellisen viisauden ihmeellisiä töitä?","Tiedätkös, kuinka pilvet hajoittavat heitänsä? täydellisen viisauden ihmeellisiä töitä?"],[37,17,"Että sinun vaattees lämpeevät, kuin ilma tyventyy etelästä?","Että sinun vaattees lämpeevät, kuin ilma tyventyy etelästä?"],[37,18,"Levitätkö sinä hänen kanssansa pilviä, jotka vahvat ovat niinkuin valettu peili?","Levitätkö sinä hänen kanssansa pilviä, jotka vahvat ovat niinkuin valettu peili?"],[37,19,"Ilmoita sinä meille, mitä meidän pitäis hänelle sanoman; sillä emme ulotu hänen tykönsä pimeydeltä.","Ilmoita sinä meille, mitä meidän pitäis hänelle sanoman; sillä emme ulotu hänen tykönsä pimeydeltä."],[37,20,"Kuka luettelee hänelle, mitä minä puhun? jos joku puhuu, niin hän niellään.","Kuka luettelee hänelle, mitä minä puhun? jos joku puhuu, niin hän niellään."],[37,21,"Ei nähdä nyt valkeutta, joka pilvissä leimahtaa; vaan kuin tuuli puhaltaa, niin seijestyy.","Ei nähdä nyt valkeutta, joka pilvissä leimahtaa; vaan kuin tuuli puhaltaa, niin seijestyy."],[37,22,"Pohjoisesta tulee kulta peljättävän Jumalan kunniaksi.","Pohjoisesta tulee kulta peljättävän Jumalan kunniaksi."],[37,23,"Mutta Kaikkivaltiasta emme taida löytää, joka on niin suuri voimassa; ja ei hän tarvitse vastata oikeudessansa ja suuressa vanhurskaudessansa.","Mutta Kaikkivaltiasta emme taida löytää, joka on niin suuri voimassa; ja ei hän tarvitse vastata oikeudessansa ja suuressa vanhurskaudessansa."],[37,24,"Sentähden täytyy ihmisten häntä peljätä: ja ei hän katso yhtään taitavaa sydämestä.","Sentähden täytyy ihmisten häntä peljätä: ja ei hän katso yhtään taitavaa sydämestä."],[38,1,"Ja Herra vastasi Jobia tuulispäästä ja sanoi:","Ja Herra vastasi Jobia tuulispäästä ja sanoi:"],[38,2,"Kuka on se, joka taidossansa niin eksyy ja puhuu niin taitamattomasti?","Kuka on se, joka taidossansa niin eksyy ja puhuu niin taitamattomasti?"],[38,3,"Vyötä nyt kupees niin kuin mies: Minä kysyn sinulta, opeta minua.","Vyötä nyt kupees niin kuin mies: Minä kysyn sinulta, opeta minua."],[38,4,"Kussas silloin olit, koska minä maan perustin? Ilmoita se, jos sinulla se ymmärrys on.","Kussas silloin olit, koska minä maan perustin? Ilmoita se, jos sinulla se ymmärrys on."],[38,5,"Tiedätkös, kuka hänen määränsä asettanut on? eli kuka on vetänyt ojennusnuoran hänen päällensä?","Tiedätkös, kuka hänen määränsä asettanut on? eli kuka on vetänyt ojennusnuoran hänen päällensä?"],[38,6,"Mihinkä ovat hänen jalkansa vajotetut, eli kuka on hänen kulmakivensä laskenut?","Mihinkä ovat hänen jalkansa vajotetut, eli kuka on hänen kulmakivensä laskenut?"],[38,7,"Kuin aamutähdet ynnä minua kiittivät, ja kaikki Jumalan lapset riemuitsivat.","Kuin aamutähdet ynnä minua kiittivät, ja kaikki Jumalan lapset riemuitsivat."],[38,8,"Kuka on sulkenut meren ovinensa, koska se ratkesi ja lähti ulos niinkuin äidin kohdusta?","Kuka on sulkenut meren ovinensa, koska se ratkesi ja lähti ulos niinkuin äidin kohdusta?"],[38,9,"Kuin minä puetin sen pilvillä, ja käärin synkeydellä niinkuin kapaloilla;","Kuin minä puetin sen pilvillä, ja käärin synkeydellä niinkuin kapaloilla;"],[38,10,"Kuin minä estin sen paisumisen säädylläni, ja asetin siihen teljen ja ovet eteen,","Kuin minä estin sen paisumisen säädylläni, ja asetin siihen teljen ja ovet eteen,"],[38,11,"Ja sanoin: tähän asti pitää sinun tuleman ja ei edemmäksi: tässä pitää sinun korkiat aaltos asettuman.","Ja sanoin: tähän asti pitää sinun tuleman ja ei edemmäksi: tässä pitää sinun korkiat aaltos asettuman."],[38,12,"Oletkos eläissäs käskenyt aamulle, ja aamuruskolle osoittanut hänen siansa?","Oletkos eläissäs käskenyt aamulle, ja aamuruskolle osoittanut hänen siansa?"],[38,13,"Käsittää maan ääriä, ja puhdistaa siitä jumalattomat.","Käsittää maan ääriä, ja puhdistaa siitä jumalattomat."],[38,14,"Se pitää muutettaman niinkuin sinetin savi; niin että he tulevat niinkuin vaate.","Se pitää muutettaman niinkuin sinetin savi; niin että he tulevat niinkuin vaate."],[38,15,"Ja jumalattomilta otetaan pois heidän valkeutensa, ja ylpeiden käsivarsi rikotaan.","Ja jumalattomilta otetaan pois heidän valkeutensa, ja ylpeiden käsivarsi rikotaan."],[38,16,"Oletkos tullut meren pohjaan, ja vaeltanut syvyyden jälkiä?","Oletkos tullut meren pohjaan, ja vaeltanut syvyyden jälkiä?"],[38,17,"Onko kuoleman ovet koskaan auvenneet etees, eli oletkos nähnyt kuoleman varjon ovet?","Onko kuoleman ovet koskaan auvenneet etees, eli oletkos nähnyt kuoleman varjon ovet?"],[38,18,"Oletkos ymmärtänyt, kuinka leviä maa on? annas kuulla, tiedätkös kaikki nämät.","Oletkos ymmärtänyt, kuinka leviä maa on? annas kuulla, tiedätkös kaikki nämät."],[38,19,"Mikä tie on sinne, kussa valkeus asuu? ja kuka on pimeyden sia?","Mikä tie on sinne, kussa valkeus asuu? ja kuka on pimeyden sia?"],[38,20,"Ettäs saattaisit hänen rajoillensa ja osaisit polut hänen huoneesensa.","Ettäs saattaisit hänen rajoillensa ja osaisit polut hänen huoneesensa."],[38,21,"Tiesitkös, koska sinä syntyvä olit ja kuinka paljo sinulla päiviä olis?","Tiesitkös, koska sinä syntyvä olit ja kuinka paljo sinulla päiviä olis?"],[38,22,"Oletkos siellä ollut, kusta lumi tulee? eli oletkos nähnyt, kusta rakeet tulevat?","Oletkos siellä ollut, kusta lumi tulee? eli oletkos nähnyt, kusta rakeet tulevat?"],[38,23,"Jotka minä olen tallella pitänyt murhepäivään asti, sodan ja tappeluksen päivään asti.","Jotka minä olen tallella pitänyt murhepäivään asti, sodan ja tappeluksen päivään asti."],[38,24,"Minkä tien kautta valkeus hajoittaa hänensä, ja itätuuli tuulee maan päälle?","Minkä tien kautta valkeus hajoittaa hänensä, ja itätuuli tuulee maan päälle?"],[38,25,"Kuka on sadekuurolle jakanut juoksunsa, ja pitkäisen valkialle ja jylinälle hänen tiensä?","Kuka on sadekuurolle jakanut juoksunsa, ja pitkäisen valkialle ja jylinälle hänen tiensä?"],[38,26,"Niin että se sataa senkin maan päälle, jossa ei ketään ole, korvessa, jossa ei yhtään ihmistä ole;","Niin että se sataa senkin maan päälle, jossa ei ketään ole, korvessa, jossa ei yhtään ihmistä ole;"],[38,27,"Että se täyttäis erämaan ja korven, ja saattais ruohot vihottamaan.","Että se täyttäis erämaan ja korven, ja saattais ruohot vihottamaan."],[38,28,"Onko sateella isää? eli kuka on synnyttänyt kasteen pisarat?","Onko sateella isää? eli kuka on synnyttänyt kasteen pisarat?"],[38,29,"Kenen kohdusta jää on tullut? ja kuka on härmän synnyttänyt taivaan alla?","Kenen kohdusta jää on tullut? ja kuka on härmän synnyttänyt taivaan alla?"],[38,30,"Vedet kätkevät itsensä niinkuin kivi, ja syvyydet päältä kiinnitetään.","Vedet kätkevät itsensä niinkuin kivi, ja syvyydet päältä kiinnitetään."],[38,31,"Taidatkos sitoa Seulaisen siteet, eli päästää Kointähden siteet?","Taidatkos sitoa Seulaisen siteet, eli päästää Kointähden siteet?"],[38,32,"Taidatkos tuoda taivaan merkit edes aikanansa, eli johdattaa Otavan lastensa kanssa?","Taidatkos tuoda taivaan merkit edes aikanansa, eli johdattaa Otavan lastensa kanssa?"],[38,33,"Tiedätkös, kuinka taivas hallitaan? eli taidatkos hänen hallituksensa toimittaa maan päällä?","Tiedätkös, kuinka taivas hallitaan? eli taidatkos hänen hallituksensa toimittaa maan päällä?"],[38,34,"Taidatkos korottaa äänes ylös pilviin, että veden paljous sinun peittäis?","Taidatkos korottaa äänes ylös pilviin, että veden paljous sinun peittäis?"],[38,35,"Taidatkos lähettää pitkäisen leimaukset matkaan menemään ja sanomaan sinulle: tässä me olemme?","Taidatkos lähettää pitkäisen leimaukset matkaan menemään ja sanomaan sinulle: tässä me olemme?"],[38,36,"Kuka on asettanut taidon salaisuuteen eli kuka on ajatukselle antanut toimen?","Kuka on asettanut taidon salaisuuteen eli kuka on ajatukselle antanut toimen?"],[38,37,"Kuka on niin taitava, että hän pilvet lukea taitaa? ja kuka taitaa tukita vesitydyt taivaassa?","Kuka on niin taitava, että hän pilvet lukea taitaa? ja kuka taitaa tukita vesitydyt taivaassa?"],[38,38,"Kuin tomu kastuu ja juoksee yhteen, ja kokkareet ryhtyvät toinen toiseensa.","Kuin tomu kastuu ja juoksee yhteen, ja kokkareet ryhtyvät toinen toiseensa."],[38,39,"(H 39:1) Taidatkos jalopeuralle antaa hänen saaliinsa ajaaksensa takaa? ja ravita nuoret jalopeurat?","(H 39:1) Taidatkos jalopeuralle antaa hänen saaliinsa ajaaksensa takaa? ja ravita nuoret jalopeurat?"],[38,40,"(H 39:2) Niin että he makaavat sioillansa, ja lepäävät luolissansa, joissa he väijyvät.","(H 39:2) Niin että he makaavat sioillansa, ja lepäävät luolissansa, joissa he väijyvät."],[38,41,"(H 39:3) Kuka valmistaa kaarneelle ruan, kuin hänen poikansa huutavat Jumalaa, ja ei he tietä eksyksissä, kussa heidän ruokansa on?","(H 39:3) Kuka valmistaa kaarneelle ruan, kuin hänen poikansa huutavat Jumalaa, ja ei he tietä eksyksissä, kussa heidän ruokansa on?"],[39,1,"(H 39:4) Tiedätkös, koska metsävuohet poikivat, eli oletkos havainnut peurat käyvän tiineenä?","(H 39:4) Tiedätkös, koska metsävuohet poikivat, eli oletkos havainnut peurat käyvän tiineenä?"],[39,2,"(H 39:5) Oletkos lukenut heidän kuukautensa, koska ne täydellänsä ovat? eli tiedätkös ajan, koska he poikivat?","(H 39:5) Oletkos lukenut heidän kuukautensa, koska ne täydellänsä ovat? eli tiedätkös ajan, koska he poikivat?"],[39,3,"(H 39:6) He kumartavat heitänsä poikiessansa, ja ajavat sen pois, josta heillä kipu on.","(H 39:6) He kumartavat heitänsä poikiessansa, ja ajavat sen pois, josta heillä kipu on."],[39,4,"(H 39:7) Heidän poikansa vahvistuvat ja kasvavat jyvistä: ne menevät ulos, ja ei palaja heidän tykönsä.","(H 39:7) Heidän poikansa vahvistuvat ja kasvavat jyvistä: ne menevät ulos, ja ei palaja heidän tykönsä."],[39,5,"(H 39:8) Kuka on metsä-aasin antanut niin vapaana käydä? kuka on metsä-aasin siteen päästänyt?","(H 39:8) Kuka on metsä-aasin antanut niin vapaana käydä? kuka on metsä-aasin siteen päästänyt?"],[39,6,"(H 39:9) Jolle minä olen erämaan huoneeksi antanut ja korven asuinsiaksi.","(H 39:9) Jolle minä olen erämaan huoneeksi antanut ja korven asuinsiaksi."],[39,7,"(H 39:10) Hän katsoo ylön kaupungin pauhinaa: vartian huutoa ei hän kuule.","(H 39:10) Hän katsoo ylön kaupungin pauhinaa: vartian huutoa ei hän kuule."],[39,8,"(H 39:11) Hän katsoo vuorella laiduntansa, ja etsii kussa viheriäistä on.","(H 39:11) Hän katsoo vuorella laiduntansa, ja etsii kussa viheriäistä on."],[39,9,"(H 39:12) Luuletkos yksisarvisen palvelevan sinuas, ja makaavan yötä sinun seimelläs?","(H 39:12) Luuletkos yksisarvisen palvelevan sinuas, ja makaavan yötä sinun seimelläs?"],[39,10,"(H 39:13) Taidatkos sitoa yksisarvisen vaolle köydellä, niin että hän kiskois ketoa laaksossa sinun perässäs?","(H 39:13) Taidatkos sitoa yksisarvisen vaolle köydellä, niin että hän kiskois ketoa laaksossa sinun perässäs?"],[39,11,"(H 39:14) Taidatkos sinus luottaa häneen, ehkä hän paljon voi, ja jättää työs hänen haltuunsa?","(H 39:14) Taidatkos sinus luottaa häneen, ehkä hän paljon voi, ja jättää työs hänen haltuunsa?"],[39,12,"(H 39:15) Uskotkos hänen siemenes kotia tuovan, ja riihees kokoovan?","(H 39:15) Uskotkos hänen siemenes kotia tuovan, ja riihees kokoovan?"],[39,13,"(H 39:16) Ovatko riikinkukkoin sulat kauniimmat kuin nälkäkurjen sulat?","(H 39:16) Ovatko riikinkukkoin sulat kauniimmat kuin nälkäkurjen sulat?"],[39,14,"(H 39:17) Joka munansa jättää maahan, ja antaa maan lämpimän hautoa niitä.","(H 39:17) Joka munansa jättää maahan, ja antaa maan lämpimän hautoa niitä."],[39,15,"(H 39:18) Hän unohtaa ne tallattavan,ja että peto kedolla ne rikkois.","(H 39:18) Hän unohtaa ne tallattavan,ja että peto kedolla ne rikkois."],[39,16,"(H 39:19) Hän on niin kova poikiansa vastaan, kuin ei ne hänen olisikaan: Ei hän tottele turhaan työtä tehdä.","(H 39:19) Hän on niin kova poikiansa vastaan, kuin ei ne hänen olisikaan: Ei hän tottele turhaan työtä tehdä."],[39,17,"(H 39:20) Sillä Jumala on häneltä taidon ottanut pois, ja ei ole antanut hänelle ymmärrystä.","(H 39:20) Sillä Jumala on häneltä taidon ottanut pois, ja ei ole antanut hänelle ymmärrystä."],[39,18,"(H 39:21) Kuin hän ylentää itsensä korkeuteen, nauraa hän hevosta ja miestä.","(H 39:21) Kuin hän ylentää itsensä korkeuteen, nauraa hän hevosta ja miestä."],[39,19,"(H 39:22) Taidatkos antaa hevoselle väen, eli taidatkos kaunistaa hänen kaulansa hirnumisella?","(H 39:22) Taidatkos antaa hevoselle väen, eli taidatkos kaunistaa hänen kaulansa hirnumisella?"],[39,20,"(H 39:23) Taidatkos peljättää hänen niinkuin heinäsirkan? peljättävä on hänen sieramiensa päristys.","(H 39:23) Taidatkos peljättää hänen niinkuin heinäsirkan? peljättävä on hänen sieramiensa päristys."],[39,21,"(H 39:24) Hän kaivaa maata kavioillansa, on riemuinen väkevyydessänsä, ja menee sota-aseita vastaan.","(H 39:24) Hän kaivaa maata kavioillansa, on riemuinen väkevyydessänsä, ja menee sota-aseita vastaan."],[39,22,"(H 39:25) Hän nauraa pelkoa ja ei hämmästy, eikä pakene miekkaa.","(H 39:25) Hän nauraa pelkoa ja ei hämmästy, eikä pakene miekkaa."],[39,23,"(H 39:26) Ehkä vielä viini kalisis häntä vastaan, ja keihäät ja kilvet välkkyisivät;","(H 39:26) Ehkä vielä viini kalisis häntä vastaan, ja keihäät ja kilvet välkkyisivät;"],[39,24,"(H 39:27) Hän korskuu, pudistelee ja kaivaa maata, ja ei tottele vasikitorven helinää.","(H 39:27) Hän korskuu, pudistelee ja kaivaa maata, ja ei tottele vasikitorven helinää."],[39,25,"(H 39:28) Kuin vaskitorvi heliästi soi, luihkaa hän: hui, ja haastaa sodan taampaa, niin myös päämiesten huudon ja riemun.","(H 39:28) Kuin vaskitorvi heliästi soi, luihkaa hän: hui, ja haastaa sodan taampaa, niin myös päämiesten huudon ja riemun."],[39,26,"(H 39:29) Lentääkö haukka sinun ymmärryksestäs, ja hajoittaa siipensä etelään käsin?","(H 39:29) Lentääkö haukka sinun ymmärryksestäs, ja hajoittaa siipensä etelään käsin?"],[39,27,"(H 39:30) Lentääkö kotka sinun kädestäs niin korkialle, että hän tekee pesänsä korkeuteen?","(H 39:30) Lentääkö kotka sinun kädestäs niin korkialle, että hän tekee pesänsä korkeuteen?"],[39,28,"(H 39:31) Hän asuu vuorilla ja yöttelee vuorten kukkuloilla ja vahvoissa paikoissa.","(H 39:31) Hän asuu vuorilla ja yöttelee vuorten kukkuloilla ja vahvoissa paikoissa."],[39,29,"(H 39:32) Sieltä hän katsoo ruan perään, ja hänen silmänsä näkevät kauvas.","(H 39:32) Sieltä hän katsoo ruan perään, ja hänen silmänsä näkevät kauvas."],[39,30,"(H 39:33) Hänen poikansa särpävät verta; ja kussa raato on, siellä myös hän on.","(H 39:33) Hänen poikansa särpävät verta; ja kussa raato on, siellä myös hän on."],[40,1,"(H 39:34) Ja Herra vastasi Jobia ja sanoi:","(H 39:34) Ja Herra vastasi Jobia ja sanoi:"],[40,2,"(H 39:35) Joka riitelee Kaikkivaltiaan kanssa, eikö hänen pitäis sitä vahvistaman? ja se joka nuhtelee Jumalaa, eikö hänen pitäis vastaaman?","(H 39:35) Joka riitelee Kaikkivaltiaan kanssa, eikö hänen pitäis sitä vahvistaman? ja se joka nuhtelee Jumalaa, eikö hänen pitäis vastaaman?"],[40,3,"(H 39:36) Job vastasi Herraa ja sanoi:","(H 39:36) Job vastasi Herraa ja sanoi:"],[40,4,"(H 39:37) Katso, minä olen halpa, mitä minä sinua vastaan? minä lasken käteni suuni päälle.","(H 39:37) Katso, minä olen halpa, mitä minä sinua vastaan? minä lasken käteni suuni päälle."],[40,5,"(H 39:38) Minä olen kerran puhunut, en minä enempää vastaa, enkä toiste sitä enää tee.","(H 39:38) Minä olen kerran puhunut, en minä enempää vastaa, enkä toiste sitä enää tee."],[40,6,"(H 40:1) Ja Herra vastasi Jobia tuulispäästä ja sanoi:","(H 40:1) Ja Herra vastasi Jobia tuulispäästä ja sanoi:"],[40,7,"(H 40:2) Vyötä kupees niinkuin mies: Minä kysyn sinulta, ja vastaa sinä minua.","(H 40:2) Vyötä kupees niinkuin mies: Minä kysyn sinulta, ja vastaa sinä minua."],[40,8,"(H 40:3) Pitäiskö sinun minun tuomioni tyhjäksi tekemän, ja minua vääräksi soimaaman, ettäs itse olisit hurskas?","(H 40:3) Pitäiskö sinun minun tuomioni tyhjäksi tekemän, ja minua vääräksi soimaaman, ettäs itse olisit hurskas?"],[40,9,"(H 40:4) Onko sinulla käsivarsi niinkuin Jumalalla? ja taidatkos yhdenkaltaisella äänellä jylistää hänen kanssansa.","(H 40:4) Onko sinulla käsivarsi niinkuin Jumalalla? ja taidatkos yhdenkaltaisella äänellä jylistää hänen kanssansa."],[40,10,"(H 40:5) Kaunista sinus suurella kunnialla ja korkeudella: pueta sinus kiitoksella ja kunnialla,","(H 40:5) Kaunista sinus suurella kunnialla ja korkeudella: pueta sinus kiitoksella ja kunnialla,"],[40,11,"(H 40:6) Hajoita sinun julmuutes viha, ja katso kaikkia ylpeitä ja nöyryytä heitä.","(H 40:6) Hajoita sinun julmuutes viha, ja katso kaikkia ylpeitä ja nöyryytä heitä."],[40,12,"(H 40:7) Katso kaikkia ylpeitä, ja alaspaina heitä, ja kukista jumalattomat paikastansa.","(H 40:7) Katso kaikkia ylpeitä, ja alaspaina heitä, ja kukista jumalattomat paikastansa."],[40,13,"(H 40:8) Hautaa heitä kaikkia maahan, ja upota heidän jaloutensa kätköön.","(H 40:8) Hautaa heitä kaikkia maahan, ja upota heidän jaloutensa kätköön."],[40,14,"(H 40:9) Niin minä tunnustan sinun oikian kätes auttavan sinua.","(H 40:9) Niin minä tunnustan sinun oikian kätes auttavan sinua."],[40,15,"(H 40:10) Katso nyt Behemotia, jonka minä sinun vierees tehnyt olen, joka syö heiniä niinkuin härkä.","(H 40:10) Katso nyt Behemotia, jonka minä sinun vierees tehnyt olen, joka syö heiniä niinkuin härkä."],[40,16,"(H 40:11) Katso, hänen väkensä on hänen kupeissansa, ja hänen voimansa hänen vatsansa navassa.","(H 40:11) Katso, hänen väkensä on hänen kupeissansa, ja hänen voimansa hänen vatsansa navassa."],[40,17,"(H 40:12) Hänen häntänsä ojentuu niinkuin sedripuu, ja hänen salaisen kalunsa suonet ovat niinkuin puun oksat.","(H 40:12) Hänen häntänsä ojentuu niinkuin sedripuu, ja hänen salaisen kalunsa suonet ovat niinkuin puun oksat."],[40,18,"(H 40:13) Hänen luunsa ovat vahvat niinkuin vaski, hänen ruotonsa niinkuin rautaiset seipäät.","(H 40:13) Hänen luunsa ovat vahvat niinkuin vaski, hänen ruotonsa niinkuin rautaiset seipäät."],[40,19,"(H 40:14) Hän on alku Jumalan teistä; joka hänen tehnyt on, hän voittaa hänen miekallansa.","(H 40:14) Hän on alku Jumalan teistä; joka hänen tehnyt on, hän voittaa hänen miekallansa."],[40,20,"(H 40:15) Vuori kantaa hänelle ruohot; ja kaikki pedot leikitsevät siellä.","(H 40:15) Vuori kantaa hänelle ruohot; ja kaikki pedot leikitsevät siellä."],[40,21,"(H 40:16) Hän makaa mielellänsä varjossa, lymyssä kaisloissa ja mudassa.","(H 40:16) Hän makaa mielellänsä varjossa, lymyssä kaisloissa ja mudassa."],[40,22,"(H 40:17) Pensas peittää hänen varjollansa, ja ojan halavat peittävät hänen.","(H 40:17) Pensas peittää hänen varjollansa, ja ojan halavat peittävät hänen."],[40,23,"(H 40:18) Katso, koska virta ylöttää häntä, niin ei hän pelkää: hän on rohkia, vaikka Jordan hänen suuhunsa asti kuohuis.","(H 40:18) Katso, koska virta ylöttää häntä, niin ei hän pelkää: hän on rohkia, vaikka Jordan hänen suuhunsa asti kuohuis."],[40,24,"(H 40:19) Hän saavutetaan nähtensä, ja pauloilla pistetään hänen nenänsä lävitse.","(H 40:19) Hän saavutetaan nähtensä, ja pauloilla pistetään hänen nenänsä lävitse."],[41,1,"(H 40:20) Taidatkos vetää Leviatanin ongella, ja sitoa hänen kielensä nuoralla?","(H 40:20) Taidatkos vetää Leviatanin ongella, ja sitoa hänen kielensä nuoralla?"],[41,2,"(H 40:21) Taidatkos panna ongen hänen sierameensa, ja hänen leukaluunsa pistää naskalilla lävitse?","(H 40:21) Taidatkos panna ongen hänen sierameensa, ja hänen leukaluunsa pistää naskalilla lävitse?"],[41,3,"(H 40:22) Luuletkos, että hän sinua paljon rukoilee, ja liehakoitsee sinun edessäs?","(H 40:22) Luuletkos, että hän sinua paljon rukoilee, ja liehakoitsee sinun edessäs?"],[41,4,"(H 40:23) Luuletkos, että hän tekee liiton sinun kanssas, saadakses häntä alinomaiseksi orjakses?","(H 40:23) Luuletkos, että hän tekee liiton sinun kanssas, saadakses häntä alinomaiseksi orjakses?"],[41,5,"(H 40:24) Taidatkos leikitä hänen kanssansa niinkuin linnun kanssa, eli sitoa hänen sinun piikais sekaan?","(H 40:24) Taidatkos leikitä hänen kanssansa niinkuin linnun kanssa, eli sitoa hänen sinun piikais sekaan?"],[41,6,"(H 40:25) Luuletkos hänen kumppaneilta leikattaman, jaettaa kauppamiehille.","(H 40:25) Luuletkos hänen kumppaneilta leikattaman, jaettaa kauppamiehille."],[41,7,"(H 40:26) Taidatkos täyttää koko verkkohuoneen hänen nahallansa, eli kalamiesten kokkoin hänen päällänsä.","(H 40:26) Taidatkos täyttää koko verkkohuoneen hänen nahallansa, eli kalamiesten kokkoin hänen päällänsä."],[41,8,"(H 40:27) Koska sinä häneen rupeet kädelläs, niin muista, ettäs tulet sotaan, josta et sinä mitään voita.","(H 40:27) Koska sinä häneen rupeet kädelläs, niin muista, ettäs tulet sotaan, josta et sinä mitään voita."],[41,9,"(H 40:28) Katso, hänen toivonsa pettää hänen; sillä koska hän hänen näkee, mukeltaneeko hän pois?","(H 40:28) Katso, hänen toivonsa pettää hänen; sillä koska hän hänen näkee, mukeltaneeko hän pois?"],[41,10,"(H 41:1) Ei ole niin rohkiaa, kuin tohtii hänen herättää: kuka siis seisoo minun edessäni?","(H 41:1) Ei ole niin rohkiaa, kuin tohtii hänen herättää: kuka siis seisoo minun edessäni?"],[41,11,"(H 41:2) Kuka on minulle jotakin ennen antanut, että minä sen hänelle maksaisin? Minun ovat kaikki, mitä kaikkein taivasten alla on.","(H 41:2) Kuka on minulle jotakin ennen antanut, että minä sen hänelle maksaisin? Minun ovat kaikki, mitä kaikkein taivasten alla on."],[41,12,"(H 41:3) Minun täytyy puhua kuinka suuri, kuinka väkevä ja kuinka kaunis hän on.","(H 41:3) Minun täytyy puhua kuinka suuri, kuinka väkevä ja kuinka kaunis hän on."],[41,13,"(H 41:4) Kuka riisuu hänen vaatteensa? Kuka tohtii ruveta hänen hampaisiinsa?","(H 41:4) Kuka riisuu hänen vaatteensa? Kuka tohtii ruveta hänen hampaisiinsa?"],[41,14,"(H 41:5) Kuka voi avata hänen leukaluunsa, jotka ovat hirmuiset hänen hammastensa ympäri?","(H 41:5) Kuka voi avata hänen leukaluunsa, jotka ovat hirmuiset hänen hammastensa ympäri?"],[41,15,"(H 41:6) Hänen suomuksensa ovat pulskiat, kiinnitetyt toinen toiseensa, niinkuin sinetti.","(H 41:6) Hänen suomuksensa ovat pulskiat, kiinnitetyt toinen toiseensa, niinkuin sinetti."],[41,16,"(H 41:7) Yksi on kiinni toisessa, niin ettei tuuli pääse lävitse.","(H 41:7) Yksi on kiinni toisessa, niin ettei tuuli pääse lävitse."],[41,17,"(H 41:8) Ne ovat kiinni toinen toisessansa ja pysyvät yhdessä, ettei heitä taideta eroittaa.","(H 41:8) Ne ovat kiinni toinen toisessansa ja pysyvät yhdessä, ettei heitä taideta eroittaa."],[41,18,"(H 41:9) Hänen aivastamisestansa kiiltää valkeus, ja hänen silmänsä ovat niinkuin aamuruskon silmälaudat.","(H 41:9) Hänen aivastamisestansa kiiltää valkeus, ja hänen silmänsä ovat niinkuin aamuruskon silmälaudat."],[41,19,"(H 41:10) Hänen sunstansa käyvät tulisoitot ulos, ja tuliset kipinät sinkoilevat.","(H 41:10) Hänen sunstansa käyvät tulisoitot ulos, ja tuliset kipinät sinkoilevat."],[41,20,"(H 41:11) Hänen sieraimistansa käy ulos savu, niinkuin kiehuvasta padasta ja kattilasta.","(H 41:11) Hänen sieraimistansa käy ulos savu, niinkuin kiehuvasta padasta ja kattilasta."],[41,21,"(H 41:12) Hänen henkensä on niinkuin tulinen hiili, ja hänen suustansa käy liekki ulos.","(H 41:12) Hänen henkensä on niinkuin tulinen hiili, ja hänen suustansa käy liekki ulos."],[41,22,"(H 41:13) Hänen kaulansa on vahva; ja se on hänen ilonsa, kuin hän tekee jotakin vahinkoa.","(H 41:13) Hänen kaulansa on vahva; ja se on hänen ilonsa, kuin hän tekee jotakin vahinkoa."],[41,23,"(H 41:14) Hänen lihansa jäsenet ovat kiinni toinen toisessansa, ne ovat hänessä kiinni, ettei hän liikuteta.","(H 41:14) Hänen lihansa jäsenet ovat kiinni toinen toisessansa, ne ovat hänessä kiinni, ettei hän liikuteta."],[41,24,"(H 41:15) Hänen sydämensä on kova niinkuin kivi, ja niin vahva kuin alimmainen myllyn kivi.","(H 41:15) Hänen sydämensä on kova niinkuin kivi, ja niin vahva kuin alimmainen myllyn kivi."],[41,25,"(H 41:16) Kuin hän korottaa itsensä, niin väkevät peljästyvät; kuin hän joutuu edes, niin ei siellä armoa ole.","(H 41:16) Kuin hän korottaa itsensä, niin väkevät peljästyvät; kuin hän joutuu edes, niin ei siellä armoa ole."],[41,26,"(H 41:17) Jos hänen tykönsä mennään miekalla eli keihäällä, aseilla eli haarniskoilla, niin ei hän itsiänsä liikuta.","(H 41:17) Jos hänen tykönsä mennään miekalla eli keihäällä, aseilla eli haarniskoilla, niin ei hän itsiänsä liikuta."],[41,27,"(H 41:18) Ei hän rautaa tottele enempi kuin kortta, eikä vaskea enempi kuin lahopuuta.","(H 41:18) Ei hän rautaa tottele enempi kuin kortta, eikä vaskea enempi kuin lahopuuta."],[41,28,"(H 41:19) Ei häntä nuolet karkota, ja linkokivet ovat hänelle niinkuin akanat.","(H 41:19) Ei häntä nuolet karkota, ja linkokivet ovat hänelle niinkuin akanat."],[41,29,"(H 41:20) Vasara on hänen edssänsä niinkuin korsi; hän pilkkaa liehuvia keihäitä.","(H 41:20) Vasara on hänen edssänsä niinkuin korsi; hän pilkkaa liehuvia keihäitä."],[41,30,"(H 41:21) Ja hän taitaa maata terävällä kivellä, hän makaa terävällä niinkuin sontatunkiolla.","(H 41:21) Ja hän taitaa maata terävällä kivellä, hän makaa terävällä niinkuin sontatunkiolla."],[41,31,"(H 41:22) Hän saattaa syvän meren kiehumaan niinkuin padan, ja liikuttaa yhteen niinkuin voiteen.","(H 41:22) Hän saattaa syvän meren kiehumaan niinkuin padan, ja liikuttaa yhteen niinkuin voiteen."],[41,32,"(H 41:23) Hänen jälkeensä polku valkenee; hän tekee syvyydet sangen harmaaksi.","(H 41:23) Hänen jälkeensä polku valkenee; hän tekee syvyydet sangen harmaaksi."],[41,33,"(H 41:24) Ei ole maalla hänen vertaistansa; hän on tehty pelkäämättömäksi.","(H 41:24) Ei ole maalla hänen vertaistansa; hän on tehty pelkäämättömäksi."],[41,34,"(H 41:25) Hän katsoo kaikki korkiat ylön; hän on kaikkein ylpeiden kuningas.","(H 41:25) Hän katsoo kaikki korkiat ylön; hän on kaikkein ylpeiden kuningas."],[42,1,"Ja Job vastasi Herraa ja sanoi:","Ja Job vastasi Herraa ja sanoi:"],[42,2,"Minä tiedän sinun kaikki voivan: ja ei ole sinulta yksikään ajatus peitetty.","Minä tiedän sinun kaikki voivan: ja ei ole sinulta yksikään ajatus peitetty."],[42,3,"Se on turha ihminen, joka ajattelee peittää neuvonsa: sentähden tunnustan minä, että minä taitamattomasti puhunut olen sitä, joka on minun tietoni ylitse ja jota en minä ymmärrä.","Se on turha ihminen, joka ajattelee peittää neuvonsa: sentähden tunnustan minä, että minä taitamattomasti puhunut olen sitä, joka on minun tietoni ylitse ja jota en minä ymmärrä."],[42,4,"Niin kuules nyt, anna mimun puhua: minä kysyn sinulta, opeta minua.","Niin kuules nyt, anna mimun puhua: minä kysyn sinulta, opeta minua."],[42,5,"Minä olen kuullut sinua tarkoilla korvilla, ja minun silmäni ovat nyt nähneet sinun.","Minä olen kuullut sinua tarkoilla korvilla, ja minun silmäni ovat nyt nähneet sinun."],[42,6,"Sentähden pidän minä itseni viallisena, ja kadun tomussa ja tuhassa.","Sentähden pidän minä itseni viallisena, ja kadun tomussa ja tuhassa."],[42,7,"Kuin Herra nämät sanat oli Jobille puhunut, sanoi Herra Eliphaalle Temanilaiselle: minun vihani on julmistunut sinun ja kahden sinun ystäväs päälle; sillä ette ole oikein puhuneet minusta, niinkuin minun palveliani Job.","Kuin Herra nämät sanat oli Jobille puhunut, sanoi Herra Eliphaalle Temanilaiselle: minun vihani on julmistunut sinun ja kahden sinun ystäväs päälle; sillä ette ole oikein puhuneet minusta, niinkuin minun palveliani Job."],[42,8,"Niin ottakaat nyt seitsemän mullia ja seitsemän oinasta, ja menkäät palveliani Jobin tykö, ja uhratkaat polttouhria teidän edestänne, ja palveliani Job rukoilkaan teidän edestänne; sillä hänen puoleensa minä katson, niin etten minä tee teille tyhmyytenne jälkeen; sillä ette ole oikein puhuneet minusta, niinkuin minun palveliani Job.","Niin ottakaat nyt seitsemän mullia ja seitsemän oinasta, ja menkäät palveliani Jobin tykö, ja uhratkaat polttouhria teidän edestänne, ja palveliani Job rukoilkaan teidän edestänne; sillä hänen puoleensa minä katson, niin etten minä tee teille tyhmyytenne jälkeen; sillä ette ole oikein puhuneet minusta, niinkuin minun palveliani Job."],[42,9,"Niin menivät Eliphas Temanilainen, Bildad Suasta ja Zophar Naemasta, ja tekivät niinkuin Herra heille sanonut oli. Ja Herra katsoi Jobin puoleen.","Niin menivät Eliphas Temanilainen, Bildad Suasta ja Zophar Naemasta, ja tekivät niinkuin Herra heille sanonut oli. Ja Herra katsoi Jobin puoleen."],[42,10,"Ja Herra käänsi Jobin vankeuden, koska hän rukoili ystäviensä edestä. Ja Herra antoi Jobille kaksi sen vertaa kaikista mitä hänellä ennen ollut oli.","Ja Herra käänsi Jobin vankeuden, koska hän rukoili ystäviensä edestä. Ja Herra antoi Jobille kaksi sen vertaa kaikista mitä hänellä ennen ollut oli."],[42,11,"Ja hänen tykönsä tulivat kaikki hänen veljensä, ja kaikki hänen sisarensa, ja kaikki ne jotka hänen ennen tunsivat, ja söivät hänen kanssansa, ja hänen huoneessansa ja käänsivät heitänsä hänen puoleensa, ja lohduttivat häntä kaikesta siitä pahasta, minkä Herra oli antanut tulla hänen päällensä. Ja itsekukin heistä antoi hänelle yhden rahan ja kultarenkaan.","Ja hänen tykönsä tulivat kaikki hänen veljensä, ja kaikki hänen sisarensa, ja kaikki ne jotka hänen ennen tunsivat, ja söivät hänen kanssansa, ja hänen huoneessansa ja käänsivät heitänsä hänen puoleensa, ja lohduttivat häntä kaikesta siitä pahasta, minkä Herra oli antanut tulla hänen päällensä. Ja itsekukin heistä antoi hänelle yhden rahan ja kultarenkaan."],[42,12,"Ja Herra siunasi Jobia sitte enempi kuin ennen, että hän sai neljätoistakymmentä tuhatta lammasta, ja kuusituhatta kamelia, ja tuhannen paria härkiä ja tuhannen aasia.","Ja Herra siunasi Jobia sitte enempi kuin ennen, että hän sai neljätoistakymmentä tuhatta lammasta, ja kuusituhatta kamelia, ja tuhannen paria härkiä ja tuhannen aasia."],[42,13,"Ja hän sai seitsemän poikaa ja kolme tytärtä,","Ja hän sai seitsemän poikaa ja kolme tytärtä,"],[42,14,"Ja kutsui ensimäisen nimen Jemina, toisen Ketsia ja kolmannen Kerenhapuk.","Ja kutsui ensimäisen nimen Jemina, toisen Ketsia ja kolmannen Kerenhapuk."],[42,15,"Ja ei löydetty niin kauniita vaimoja kaikessa maassa, kuin Jobin tyttäret olivat. Ja heidän isänsä antoi heille perimisen heidän veljeinsä kanssa.","Ja ei löydetty niin kauniita vaimoja kaikessa maassa, kuin Jobin tyttäret olivat. Ja heidän isänsä antoi heille perimisen heidän veljeinsä kanssa."],[42,16,"Ja Job eli sitte sata ja neljäkymmentä vuotta, niin että hän sai nähdä lapsensa ja lastensa lapset hamaan neljänteen polveen.","Ja Job eli sitte sata ja neljäkymmentä vuotta, niin että hän sai nähdä lapsensa ja lastensa lapset hamaan neljänteen polveen."],[42,17,"Ja Job kuoli vanhana ja elämästä kyllänsä saaneena","Ja Job kuoli vanhana ja elämästä kyllänsä saaneena"]]}};